import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> arr = [1, 3, 2, 7, 9, 11, 3, 5];
  int n = arr.length;

  int maxLog = (log(n) / log(2)).floor() + 1;

  List<List<int>> st = List.generate(maxLog, (_) => List.filled(n, 0));
  for (int i = 0; i < n; i++) {
    st[0][i] = arr[i];
  }
  for (int k = 1; k < maxLog; k++) {
    for (int i = 0; i + (1 << k) <= n; i++) {
      st[k][i] = min(
        st[k - 1][i],
        st[k - 1][i + (1 << (k - 1))],
      );
    }
  }

  int query(int l, int r) {
    int length = r - l + 1;
    int k = (log(length) / log(2)).floor();
    return min(
      st[k][l],
      st[k][r - (1 << k) + 1],
    );
  }

  List<List<int>> queries = [
    [0, 2],
    [1, 5],
    [3, 7],
    [2, 4],
  ];
  for (var qr in queries) {
    int l = qr[0], r = qr[1];
    int ans = query(l, r);
    print('RMQ($l, $r) = $ans');
  }
}

