Set<int> fn0(List<int> pixels) {
  Set<int> result = {};
  for (int pixel in pixels) {
    int r = (pixel >> 16) & 0xFF;
    int g = (pixel >> 8) & 0xFF;
    int b = pixel & 0xFF;
    if (r > g && r > b) {
      if ((r - g) > 10 || (r - b) > 10) {
        int diff = (r - g).abs() * 256 + (r - b).abs();
        result.add(diff);
      }
    }
  }
  return result;
}

