@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String log) {
  Map<int, int> stock = {};
  Set<int> alerts = {};
  int i = 0;
  int state = 0;
  int wh = 0;
  String op = '';
  int qty = 0;
  while (i < log.length) {
    String c = log[i];
    if (state == 0) {
      if (c.codeUnitAt(0) >= 49 && c.codeUnitAt(0) <= 57) {
        wh = int.parse(c);
        state = 1;
      }
    } else if (state == 1) {
      if (c == '+' || c == '-') {
        op = c;
        state = 2;
      }
    } else if (state == 2) {
      if (c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) {
        qty = int.parse(c);
        int prev = stock[wh] ?? 0;
        int next = op == '+' ? prev + qty : prev - qty;
        stock[wh] = next;
        if (next < 0) alerts.add(wh);
        state = 0;
      }
    }
    i++;
  }
  return alerts;
}

