List<int> fn0(List<int> rolls) {
  if (rolls.isEmpty) return [];
  List<int> result = [];
  int current = rolls[0];
  int count = 1;
  for (int i = 1; i < rolls.length; i++) {
    if (rolls[i] == current) {
      count++;
    } else {
      result.add(current);
      result.add(count);
      current = rolls[i];
      count = 1;
    }
  }
  result.add(current);
  result.add(count);
  return result;
}

