import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> orders) {
  Set<int> possible = {0};
  for (int order in orders) {
    Set<int> next = {};
    int half = order ~/ 2;
    for (int total in possible) {
      next.add(total + order);
      next.add(total + half);
    }
    possible = next;
  }
  return possible;
}

tests:
void main() {
  final implementation = fn0;

  expect(implementation([]).toList()..sort(), [0]);
  expect(implementation([4]).toList()..sort(), [2, 4]);
  expect(implementation([10]).toList()..sort(), [5, 10]);
  expect(implementation([4, 6]).toList()..sort(), [5, 7, 8, 10]);
  expect(implementation([1, 1]).toList()..sort(), [0, 1, 2]);
  expect(implementation([3, 5, 2]).toList()..sort(), [4, 5, 6, 7, 8, 9, 10]);
  expect(implementation([0]).toList()..sort(), [0]);
  expect(implementation([7, 3]).toList()..sort(), [4, 6, 8, 10]);
  expect(implementation([2, 2, 2]).toList()..sort(), [3, 4, 5, 6]);
}

void expect(dynamic a, dynamic b) {
  if (a == b) return;

  if (a is List && b is List) {
    expectList(a, b);
  } else if (a is Map && b is Map) {
    expectMap(a, b);
  } else if (a is Set && b is Set) {
    expectSet(a, b);
  } else {
    throw '$a != $b';
  }
}

void expectSet(Set a, Set b) {
  if (a.length != b.length) throw 'set lengths are not equal';

  for (var v in a) {
    if (!b.contains(v)) throw '$v not in $b';
  }
}

void expectList(List a, List b) {
  if (a.length != b.length) throw 'list lengths are not equal';

  for (var i = 0; i < a.length; i++) {
    expect(a[i], b[i]);
  }
}

void expectMap(Map a, Map b) {
  if (a.length != b.length) throw 'map lengths are not equal';

  for (var key in a.keys) {
    expect(a[key], b[key]);
  }
}

