import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<List<double>> amounts) {
  int count = 0;
  for (int i = 0; i < amounts.length; i++) {
    List<double> row = amounts[i];
    for (int j = 0; j < row.length; j++) {
      double val = row[j];
      double scaled = val * 4;
      int roundedInt = scaled.round();
      double rounded = roundedInt / 4.0;
      if (rounded > val) {
        count++;
      }
    }
  }
  return count;
}

