import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> strengths, int binWidth) {
  if (strengths.isEmpty) {
    return -1.0;
  }
  int total = 0;
  for (int s in strengths) {
    int bin = ((-s) - 1) ~/ binWidth;
    total += bin;
  }
  return total / strengths.length;
}

