import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(int x1, int y1, int size1, int x2, int y2, int size2) {
  List<int> countColors(int x, int y, int size) {
    int cells = size * size;
    int black = cells ~/ 2;
    int white = cells ~/ 2;

    if (cells % 2 == 1) {
      if ((x + y) % 2 == 0) {
        black++;
      } else {
        white++;
      }
    }

    return [black, white];
  }

  List<int> first = countColors(x1, y1, size1);
  List<int> second = countColors(x2, y2, size2);

  int overlapLeft = x1 > x2 ? x1 : x2;
  int overlapBottom = y1 > y2 ? y1 : y2;
  int overlapRight = (x1 + size1) < (x2 + size2)
      ? (x1 + size1)
      : (x2 + size2);
  int overlapTop = (y1 + size1) < (y2 + size2)
      ? (y1 + size1)
      : (y2 + size2);

  int overlapBlack = 0;
  int overlapWhite = 0;

  if (overlapLeft < overlapRight && overlapBottom < overlapTop) {
    int overlapSizeX = overlapRight - overlapLeft;
    int overlapSizeY = overlapTop - overlapBottom;
    int overlapCells = overlapSizeX * overlapSizeY;

    overlapBlack = overlapCells ~/ 2;
    overlapWhite = overlapCells ~/ 2;

    if (overlapCells % 2 == 1) {
      if ((overlapLeft + overlapBottom) % 2 == 0) {
        overlapBlack++;
      } else {
        overlapWhite++;
      }
    }
  }

  int totalBlack = first[0] + second[0] - overlapBlack;
  int totalWhite = first[1] + second[1] - overlapWhite;

  return totalBlack == totalWhite;
}

