List<String> fn0(List<String> phases, int minDuration) {
  List<String> result = [];
  int n = phases.length;
  if (n == 0 || minDuration <= 0) return result;
  int left = 0;
  for (int right = 0; right < n; right++) {
    if (right > 0 && phases[right] != phases[right - 1]) {
      if (right - left >= minDuration && !result.contains(phases[left])) {
        result.add(phases[left]);
      }
      left = right;
    }
  }
  if (n - left >= minDuration && !result.contains(phases[left])) {
    result.add(phases[left]);
  }
  return result;
}

