int fn0(String inventory) {
  if (inventory.isEmpty) return 0;
  var total = 0;
  for (final entry in inventory.split(',')) {
    final token = entry.trim();
    if (token.isEmpty) continue;
    final space = token.lastIndexOf(' ');
    final qty = (space != -1 && space + 1 < token.length && token[space + 1] == 'x')
        ? int.tryParse(token.substring(space + 2)) ?? 1
        : 1;
    total += qty;
  }
  return total;
}

