int fn0(List<int> barcodeDigits, int target) {
  int lo = 0, hi = barcodeDigits.length - 1, result = -1;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (barcodeDigits[mid] == target) {
      result = mid;
      hi = mid - 1;
    } else if (barcodeDigits[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return result;
}

