@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<String> squares, int minGroupCount) {
  final Map<int, int> squareCounts = <int, int>{};
  final Map<int, int> groupCounts = <int, int>{};

  for (String square in squares) {
    if (square.length != 2) {
      continue;
    }
    int file = square.codeUnitAt(0) - 97;
    int rank = square.codeUnitAt(1) - 49;
    if (file < 0 || file > 7 || rank < 0 || rank > 7) {
      continue;
    }

    int id = rank * 8 + file;
    int color = (file + rank) % 2;
    int group = file * 2 + color;
    squareCounts[id] = (squareCounts[id] ?? 0) + 1;
    groupCounts[group] = (groupCounts[group] ?? 0) + 1;
  }

  final Set<int> result = <int>{};
  for (int id in squareCounts.keys) {
    if (squareCounts[id]! >= 2) {
      int file = id % 8;
      int rank = id ~/ 8;
      int group = file * 2 + ((file + rank) % 2);
      if ((groupCounts[group] ?? 0) >= minGroupCount) {
        result.add(id);
      }
    }
  }
  return result;
}

