@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<Map<String, double>> schedule) {
  var sorted = List<Map<String, double>>.from(schedule);
  sorted.sort((a, b) {
    int timeCompare = a['time']!.compareTo(b['time']!);
    if (timeCompare != 0) return timeCompare;
    return a['temp']!.compareTo(b['temp']!);
  });
  for (var entry in sorted) {
    double temp = entry['temp']!;
    if (temp < 10.0 || temp > 30.0) return false;
  }
  for (int i = 0; i < sorted.length - 1; i++) {
    double time1 = sorted[i]['time']!;
    double temp1 = sorted[i]['temp']!;
    double time2 = sorted[i+1]['time']!;
    double temp2 = sorted[i+1]['temp']!;
    if (time1 == time2) return false;
    double timeDiffHours = (time2 - time1) / 60.0;
    double tempDiff = (temp2 - temp1).abs();
    double rate = tempDiff / timeDiffHours;
    if (rate > 2.0) return false;
  }
  return true;
}

