import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(
    int boardSize, int startRow, int startCol, int moves) {
  final Map<String, double> memo = {};
  double dfs(int r, int c, int m) {
    if (m <= 0) return 0.0;
    final String key = '$r,$c,$m';
    if (memo.containsKey(key)) return memo[key]!;
    double score = 0.0;
    final List<List<int>> dirs = const [
      [2, 1], [2, -1], [-2, 1], [-2, -1],
      [1, 2], [1, -2], [-1, 2], [-1, -2]
    ];
    for (final d in dirs) {
      final int nr = r + d[0];
      final int nc = c + d[1];
      if (nr >= 0 && nr < boardSize && nc >= 0 && nc < boardSize) {
        final bool isEdge = (nr == 0 || nr == boardSize - 1 ||
            nc == 0 || nc == boardSize - 1);
        final double stepScore = isEdge ? 0.5 : 1.0;
        score += stepScore + dfs(nr, nc, m - 1);
      }
    }
    final double result = score / 8.0;
    memo[key] = result;
    return result;
  }
  return dfs(startRow, startCol, moves);
}

