@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> packetSizes, int mtu, int headerSize, int maxFragmentsPerPacket) {
  int maxPayload = mtu - headerSize;
  if (maxPayload <= 0) return 0.0;
  int totalOffered = 0;
  int totalDelivered = 0;
  for (int size in packetSizes) {
    if (size <= 0) continue;
    totalOffered += size;
    int fragments = (size + maxPayload - 1) ~/ maxPayload;
    if (fragments <= maxFragmentsPerPacket) {
      totalDelivered += size;
    }
  }
  if (totalOffered == 0) return 0.0;
  return totalDelivered / totalOffered;
}

