import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  double objective(List<double> solution) {
    double x = solution[0];
    double y = solution[1];
    return (x - 1) * (x - 1) + (y - 1) * (y - 1) + sin(3 * x) + sin(3 * y);
  }

  Random rand = Random(0);
  List<double> current = [rand.nextDouble() * 10 - 5, rand.nextDouble() * 10 - 5];
  double currentCost = objective(current);

  List<double> best = List.from(current);
  double bestCost = currentCost;

  double initialTemp = 100.0;
  double finalTemp = 0.1;
  int maxIterations = 10000;
  double coolingRate = 0.995; 

  double temp = initialTemp;

  for (int i = 0; i < maxIterations; i++) {

    List<double> fn0 = List.from(current);
    fn0[0] += rand.nextDouble() * 0.1 - 0.05;
    fn0[1] += rand.nextDouble() * 0.1 - 0.05;

    double candidateCost = objective(fn0);

    double costDiff = candidateCost - currentCost;

    if (costDiff < 0 || rand.nextDouble() < exp(-costDiff / temp)) {
      current = fn0;
      currentCost = candidateCost;

      if (currentCost < bestCost) {
        best = List.from(current);
        bestCost = currentCost;
      }
    }

    temp *= coolingRate;

    if (temp < finalTemp) {
      break;
    }
  }

  print('Best solution: x=${best[0]}, y=${best[1]}');
  print('Best cost: $bestCost');
}

