import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<List<int>> manifests) {
  final Set<String> occupied = <String>{};

  for (final manifest in manifests) {
    if (manifest.length != 4) {
      return false;
    }

    final int x1 = manifest[0];
    final int y1 = manifest[1];
    final int x2 = manifest[2];
    final int y2 = manifest[3];

    if (x1 >= x2 || y1 >= y2) {
      return false;
    }

    for (int x = x1; x < x2; x++) {
      for (int y = y1; y < y2; y++) {
        final String key = '$x,$y';
        if (occupied.contains(key)) {
          return false;
        }
        occupied.add(key);
      }
    }
  }

  if (occupied.isEmpty) {
    return false;
  }

  final List<String> stack = <String>[occupied.first];
  final Set<String> visited = <String>{};
  int endpoints = 0;

  while (stack.isNotEmpty) {
    final String cell = stack.removeLast();
    if (!visited.add(cell)) {
      continue;
    }

    final List<String> parts = cell.split(',');
    final int x = int.parse(parts[0]);
    final int y = int.parse(parts[1]);

    int degree = 0;
    final List<String> neighbors = <String>[
      '${x + 1},$y',
      '${x - 1},$y',
      '$x,${y + 1}',
      '$x,${y - 1}'
    ];

    for (final neighbor in neighbors) {
      if (occupied.contains(neighbor)) {
        degree++;
        if (!visited.contains(neighbor)) {
          stack.add(neighbor);
        }
      }
    }

    if (degree > 2) {
      return false;
    }

    if (degree == 1) {
      endpoints++;
    }
  }

  if (visited.length != occupied.length) {
    return false;
  }

  if (occupied.length == 1) {
    return endpoints == 0;
  }

  return endpoints == 2;
}

