import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<num>> points = [
    [2, 3],
    [5, 4],
    [9, 6],
    [4, 7],
    [8, 1],
    [7, 2]
  ];

  KDNode? root = buildKDTree(points, 0);

  printKDTree(root, 0);
}

class KDNode {
  List<num> point;
  KDNode? left;
  KDNode? right;
  int axis;

  KDNode(this.point, this.axis, {this.left, this.right});
}

KDNode? buildKDTree(List<List<num>> points, int depth) {
  if (points.isEmpty) return null;

  int k = points[0].length;
  int axis = depth % k;

  points.sort((a, b) => a[axis].compareTo(b[axis]));

  int median = points.length ~/ 2;
  List<num> medianPoint = points[median];

  var left = buildKDTree(points.sublist(0, median), depth + 1);
  var right = buildKDTree(points.sublist(median + 1), depth + 1);

  return KDNode(medianPoint, axis, left: left, right: right);
}

void printKDTree(KDNode? node, int depth) {
  if (node == null) return;
  String indent = '  ' * depth;
  print('$indent${node.point} (axis=${node.axis})');
  printKDTree(node.left, depth + 1);
  printKDTree(node.right, depth + 1);
}

