import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<int> keys, int numBuckets, int k) {
  if (numBuckets <= 0 || k <= 0) return [];
  List<int> counts = List.filled(numBuckets, 0);
  for (int key in keys) {
    int b = key % numBuckets;
    if (b < 0) b += numBuckets;
    counts[b]++;
  }
  int low = 0;
  int high = keys.length;
  while (low < high) {
    int mid = (low + high + 1) ~/ 2;
    int numHeavy = 0;
    for (int c in counts) {
      if (c >= mid) numHeavy++;
    }
    if (numHeavy >= k) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  int threshold = low;
  List<String> result = [];
  for (int i = 0; i < numBuckets; i++) {
    if (counts[i] >= threshold) {
      result.add('bucket$i');
    }
  }
  result.sort();
  return result;
}

