  Set<int> squares = {};
  for (int r = 0; r < 8; r++) {
    for (int c = 0; c < 8; c++) {
      int steps = (r - row).abs() + (c - col).abs();
      if (steps <= distance) {
        squares.add(r * 8 + c);
      }
    }
  }
  return squares;
}

