import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final random = Random(0);
  final targetString = "HELLO WORLD";
  final populationSize = 100;
  final mutationRate = 0.01;
  final eliteSize = 20;

  final charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";

  String generateIndividual(int length) {
    return List.generate(length, (_) => charset[random.nextInt(charset.length)]).join();
  }

  int calculateFitness(String individual) {
    int fitness = 0;
    for (int i = 0; i < individual.length; i++) {
      if (i < targetString.length && individual[i] == targetString[i]) {
        fitness++;
      }
    }
    return fitness;
  }

  String tournamentSelection(List<String> population, List<int> fitnesses) {
    final tournamentSize = 5;
    int bestIndex = random.nextInt(population.length);
    int bestFitness = fitnesses[bestIndex];

    for (int i = 1; i < tournamentSize; i++) {
      int index = random.nextInt(population.length);
      if (fitnesses[index] > bestFitness) {
        bestIndex = index;
        bestFitness = fitnesses[index];
      }
    }
    return population[bestIndex];
  }

  String crossover(String parent1, String parent2) {
    final crossoverPoint = random.nextInt(parent1.length);
    return parent1.substring(0, crossoverPoint) + parent2.substring(crossoverPoint);
  }

  String mutate(String individual) {
    final chars = individual.split('');
    for (int i = 0; i < chars.length; i++) {
      if (random.nextDouble() < mutationRate) {
        chars[i] = charset[random.nextInt(charset.length)];
      }
    }
    return chars.join();
  }

  List<String> population = List.generate(
    populationSize, 
    (_) => generateIndividual(targetString.length)
  );

  int generation = 0;
  bool targetFound = false;

  while (!targetFound && generation < 10000) {

    List<int> fitnesses = population.map((ind) => calculateFitness(ind)).toList();

    List<MapEntry<String, int>> populationWithFitness = [];
    for (int i = 0; i < population.length; i++) {
      populationWithFitness.add(MapEntry(population[i], fitnesses[i]));
    }
    populationWithFitness.sort((a, b) => b.value.compareTo(a.value));

    if (populationWithFitness[0].value == targetString.length) {
      targetFound = true;
      print("Target found in generation $generation: ${populationWithFitness[0].key}");
      break;
    }

    if (generation % 100 == 0) {
      print("Generation $generation - Best: ${populationWithFitness[0].key} (Fitness: ${populationWithFitness[0].value}/${targetString.length})");
    }

    List<String> newPopulation = [];

    for (int i = 0; i < eliteSize && i < populationWithFitness.length; i++) {
      newPopulation.add(populationWithFitness[i].key);
    }

    while (newPopulation.length < populationSize) {

      String parent1 = tournamentSelection(population, fitnesses);
      String parent2 = tournamentSelection(population, fitnesses);

      String offspring = crossover(parent1, parent2);
      offspring = mutate(offspring);

      newPopulation.add(offspring);
    }

    population = newPopulation;
    generation++;
  }

  if (!targetFound) {
    print("Target not found after $generation generations");
    print("Best individual: ${population[0]}");
  }

  print("\nFinal Statistics:");
  print("Total generations: $generation");
  print("Population size: $populationSize");
  print("Mutation rate: $mutationRate");
  print("Elite size: $eliteSize");
}

