import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String input, int numBuckets) {
  List<int> buckets = List.filled(numBuckets, 0);
  bool expectingHex = false;
  for (int i = 0; i < input.length; i++) {
    String ch = input[i];
    if (expectingHex) {
      int val;
      int code = ch.codeUnitAt(0);
      if (code >= 48 && code <= 57) { 
        val = code - 48;
      } else if (code >= 97 && code <= 102) { 
        val = code - 97 + 10;
      } else if (code >= 65 && code <= 70) { 
        val = code - 65 + 10;
      } else {
        val = 0;
      }
      int bucket = val % numBuckets;
      buckets[bucket]++;
      expectingHex = false;
    } else {
      switch (ch) {
        case 'i':
          expectingHex = true;
          break;
        case 'r':
          for (int j = 0; j < numBuckets; j++) {
            buckets[j] = 0;
          }
          break;
        case 'd':
          for (int j = 0; j < numBuckets; j++) {
            buckets[j] *= 2;
          }
          break;
        case 's':
          if (numBuckets > 0) {
            int last = buckets[numBuckets - 1];
            for (int j = numBuckets - 1; j > 0; j--) {
              buckets[j] = buckets[j - 1];
            }
            buckets[0] = last;
          }
          break;
        default:
          break;
      }
    }
  }
  return buckets;
}

