import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<List<int>> seatCoords, int minDist) {
  List<String> warnings = [];
  int n = seatCoords.length;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      int rowDiff = (seatCoords[i][0] - seatCoords[j][0]).abs();
      int colDiff = (seatCoords[i][1] - seatCoords[j][1]).abs();
      int manhattanDist = rowDiff + colDiff;
      if (rowDiff == 0 && colDiff == 1) {
        warnings.add('Seats $i and $j are side-by-side within ${colDiff} column');
      } else if (colDiff == 0 && rowDiff == 1) {
        warnings.add('Seats $i and $j are front-to-back within ${rowDiff} row');
      } else if (manhattanDist < minDist) {
        warnings.add('Seats $i and $j are too close: distance $manhattanDist');
      }
    }
  }
  return warnings;
}

