        buffer.write(dna[i]);
        i++;
      }
    }
    cleaned = buffer.toString();
  }
  int purines = 0;
  int pyrimidines = 0;
  for (int j = 0; j < cleaned.length; j++) {
    String c = cleaned[j];
    if (c == 'A' || c == 'G') {
      purines++;
    } else if (c == 'C' || c == 'T') {
      pyrimidines++;
    }
  }
  return purines == pyrimidines;
}

