import 'dart:convert';
enum Status {
  pending(0, "Pending approval"),
  approved(1, "Approved by admin"),
  rejected(2, "Rejected by admin");

  final int code;
  final String description;

  const Status(this.code, this.description);

  bool get isFinal => this == Status.approved || this == Status.rejected;

  @override
  String toString() => '$name (code: $code, desc: $description)';
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
