import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String grid) {
  if (grid.isEmpty) return 0;
  int totalDanger = 0;
  List<String> rows = grid.split(';');
  for (String row in rows) {
    List<String> cells = row.split(',');
    for (int i = 0; i < cells.length; i++) {
      String cell = cells[i];
      if (cell == 'W') continue;
      int? trapValue = int.tryParse(cell);
      if (trapValue != null) {
        totalDanger += trapValue;
      }
      if (i > 0 && cells[i - 1] == 'W') {
        totalDanger += 1;
      }
      if (i < cells.length - 1 && cells[i + 1] == 'W') {
        totalDanger += 1;
      }
    }
  }
  return totalDanger;
}

