import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String dnaSequence) {
  if (dnaSequence.length < 3) return 0;

  int maxRun = 0;
  int currentRun = 0;

  for (int i = 0; i + 2 < dnaSequence.length; i += 3) {
    String codon = dnaSequence.substring(i, i + 3);
    int gcCount = 0;
    for (int j = 0; j < 3; j++) {
      if (codon[j] == 'G' || codon[j] == 'C') {
        gcCount++;
      }
    }
    if (gcCount >= 2) {
      currentRun++;
      if (currentRun > maxRun) {
        maxRun = currentRun;
      }
    } else {
      currentRun = 0;
    }
  }

  return maxRun;
}

