import 'dart:async';
import 'dart:convert';
import 'dart:collection';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<String>> maze = [
    ['S', '.', '#', '.'],
    ['.', '#', '.', '.'],
    ['.', '.', '.', 'E'],
  ];

  int rows = maze.length;
  int cols = maze[0].length;

  List<List<int>> directions = [
    [-1, 0], 
    [1, 0],  
    [0, -1], 
    [0, 1],  
  ];

  int startRow = -1;
  int startCol = -1;
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (maze[i][j] == 'S') {
        startRow = i;
        startCol = j;
        break;
      }
    }
    if (startRow != -1) break;
  }

  if (startRow == -1) {
    print('No start found');
    return;
  }

  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));

  Queue<List<int>> queue = Queue();
  queue.add([startRow, startCol, 0]);
  visited[startRow][startCol] = true;

  int shortestPath = -1;

  while (queue.isNotEmpty) {
    List<int> current = queue.removeFirst();
    int row = current[0];
    int col = current[1];
    int steps = current[2];

    if (maze[row][col] == 'E') {
      shortestPath = steps;
      break;
    }

    for (List<int> dir in directions) {
      int newRow = row + dir[0];
      int newCol = col + dir[1];

      if (newRow >= 0 &&
          newRow < rows &&
          newCol >= 0 &&
          newCol < cols &&
          !visited[newRow][newCol] &&
          maze[newRow][newCol] != '#') {
        visited[newRow][newCol] = true;
        queue.add([newRow, newCol, steps + 1]);
      }
    }
  }

  if (shortestPath != -1) {
    print('Shortest path found: $shortestPath steps');
  } else {
    print('No path found to the end');
  }
}

