void fn0(List<String> args) {

  List<int> a = [];
  if (args.isEmpty) {
    a = [64, 34, 25, 12, 22, 11, 90, 0, -5, 34];
  } else {
    for (final arg in args) {
      for (final part in arg.split(',')) {
        final s = part.trim();
        if (s.isEmpty) continue;
        final v = int.tryParse(s);
        if (v == null) {
          print('Error: "$s" is not a valid integer.');
          return;
        }
        a.add(v);
      }
    }
  }

  print('Before: $a');

  final int n = a.length;
  bool swapped = false;
  for (int i = 0; i < n - 1; i++) {
    swapped = false;
    for (int j = 0; j < n - i - 1; j++) {
      if (a[j] > a[j + 1]) {
        final int temp = a[j];
        a[j] = a[j + 1];
        a[j + 1] = temp;
        swapped = true;
      }
    }
    if (!swapped) break; 
  }

  print('After:  $a');
}

