@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> readings) {
  if (readings.isEmpty) return 0.0;

  Map<String, double> binWeights = {
    "excellent": 1.0,
    "good": 0.75,
    "fair": 0.5,
    "weak": 0.25,
    "dead": 0.0,
  };

  Map<String, int> binCounts = {
    "excellent": 0,
    "good": 0,
    "fair": 0,
    "weak": 0,
    "dead": 0,
  };

  for (int r in readings) {
    if (r >= -50) {
      binCounts["excellent"] = binCounts["excellent"]! + 1;
    } else if (r >= -60) {
      binCounts["good"] = binCounts["good"]! + 1;
    } else if (r >= -70) {
      binCounts["fair"] = binCounts["fair"]! + 1;
    } else if (r >= -80) {
      binCounts["weak"] = binCounts["weak"]! + 1;
    } else {
      binCounts["dead"] = binCounts["dead"]! + 1;
    }
  }

  double totalScore = 0.0;
  for (String bin in binCounts.keys) {
    totalScore += binWeights[bin]! * binCounts[bin]!;
  }

  return totalScore / readings.length;
}

