@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String symbols, int divisor) {
  if (divisor == 0) return false;
  int totalUnits = 0;
  for (int i = 0; i < symbols.length; i++) {
    final c = symbols[i];
    if (c == '.') {
      totalUnits += 1;
    } else if (c == '-') {
      totalUnits += 3;
    } else {
      return false;
    }
  }
  if (totalUnits % divisor != 0) return false;
  int n = symbols.length;
  if (n < 2) return false;
  if (n == 2) return true;
  if (n % 2 == 0) return false;
  for (int i = 3; i * i <= n; i += 2) {
    if (n % i == 0) return false;
  }
  return true;
}

