import 'dart:async';
import 'dart:convert';
sealed class Shape {}

class Circle extends Shape {
  final double radius;
  Circle(this.radius);
}

class Rectangle extends Shape {
  final double width;
  final double height;
  Rectangle(this.width, this.height);
}

class Square extends Shape {
  final double side;
  Square(this.side);
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {
  final shapes = <Shape>[
    Circle(3),
    Rectangle(4, 5),
    Square(2),
    Circle(1.5),
    Rectangle(2, 8),
  ];

  for (final shape in shapes) {
    final description = switch (shape) {
      Circle(radius: var r) => 'Circle with radius $r, area = ${area(shape)}',
      Rectangle(width: var w, height: var h) =>
        'Rectangle ($w x $h), area = ${area(shape)}',
      Square(side: var s) => 'Square with side $s, area = ${area(shape)}',
    };
    print(description);
  }
}

double area(Shape shape) => switch (shape) {
      Circle(:final radius) => 3.14159 * radius * radius,
      Rectangle(:final width, :final height) => width * height,
      Square(:final side) => side * side,
    };

