void fn0() {

  Map<String, Map<String, dynamic>> userPreferences = {};

  void savePreference(String userId, String key, dynamic value) {
    userPreferences.putIfAbsent(userId, () => {});
    userPreferences[userId]![key] = value;
    print('Saved: User $userId - $key = $value');
  }

  dynamic getPreference(String userId, String key, [dynamic defaultValue]) {
    if (!userPreferences.containsKey(userId)) {
      return defaultValue;
    }
    return userPreferences[userId]![key] ?? defaultValue;
  }

  Map<String, dynamic> getAllPreferences(String userId) {
    return Map.from(userPreferences[userId] ?? {});
  }

  void deletePreference(String userId, String key) {
    if (userPreferences.containsKey(userId)) {
      userPreferences[userId]!.remove(key);
      print('Deleted: User $userId - $key');
    }
  }

  void clearUserPreferences(String userId) {
    userPreferences.remove(userId);
    print('Cleared all preferences for User $userId');
