Map<String, int> fn0(List<List<String>> bracket) {
  Map<String, int> scores = {};
  if (bracket.isEmpty || bracket[0].isEmpty) {
    return scores;
  }

  for (String team in bracket[0]) {
    scores[team] = 0;
  }

  for (int r = 1; r < bracket.length; r++) {
    for (int m = 0; m < bracket[r].length; m++) {
      String winner = bracket[r][m];
      String p1 = bracket[r - 1][2 * m];
      String p2 = bracket[r - 1][2 * m + 1];

      String loser = '';
      if (winner == p1) {
        loser = p2;
      } else if (winner == p2) {
        loser = p1;
      }

      scores[winner] = (scores[winner] ?? 0) + 10;

      if (winner.isNotEmpty && loser.isNotEmpty && 
          winner[0].toLowerCase() == loser[0].toLowerCase()) {
        scores[winner] = (scores[winner] ?? 0) + 5;
      }
    }
  }

  return scores;
}

