@pragma('vm:entry-point')
String fn0(String barcode) {
  final buffer = StringBuffer();
  for (int i = 0; i < barcode.length; i++) {
    int digit = barcode.codeUnitAt(i) ^ 48;
    int p0 = digit & 1;
    int p1 = (digit >> 1) & 1;
    int p2 = (digit >> 2) & 1;
    int p3 = (digit >> 3) & 1;
    int parity = (p0 + p1 + p2 + p3) % 2 == 0 ? 1 : 0;
    buffer.write('$p3$p2$p1$p0$parity');
  }
  return buffer.toString();
}

