@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {





  List<List<int>> adj = List.generate(7, (_) => []);
  adj[1] = [2, 3];
  adj[2] = [4, 5];
  adj[3] = [6];
  adj[4] = [];
  adj[5] = [];
  adj[6] = [];

  int n = 6; 

  List<int> parent = List.filled(n + 1, -1);
  List<int> depth = List.filled(n + 1, 0);
  List<int> size = List.filled(n + 1, 0);
  List<int> heavy = List.filled(n + 1, -1); 
  List<int> head = List.filled(n + 1, 0); 
  List<int> pos = List.filled(n + 1, 0); 
  int curPos = 0;

  void dfsSize(int v, int p, int d) {
    parent[v] = p;
    depth[v] = d;
    size[v] = 1;
    int maxChildSize = -1;
    int maxChild = -1;
    for (int child in adj[v]) {
      if (child != p) {
        dfsSize(child, v, d + 1);
        size[v] += size[child];
        if (size[child] > maxChildSize) {
          maxChildSize = size[child];
          maxChild = child;
        }
      }
    }
    heavy[v] = maxChild;
  }

  void dfsHLD(int v, int p, int h) {
    head[v] = h;
    pos[v] = curPos++;
    if (heavy[v] != -1) {
      dfsHLD(heavy[v], v, h); 
    }
    for (int child in adj[v]) {
      if (child != p && child != heavy[v]) {
        dfsHLD(child, v, child); 
      }
    }
  }

  dfsSize(1, -1, 0);

  dfsHLD(1, -1, 1);

  print('Node | Parent | Depth | Size | Heavy Child | Chain Head | Position');
  for (int i = 1; i <= n; i++) {
    print('$i | ${parent[i]} | ${depth[i]} | ${size[i]} | ${heavy[i]} | ${head[i]} | ${pos[i]}');
  }



}

