  List<String> tokens = moves.split(RegExp(r'\s+'));
  RegExp squarePattern = RegExp(r'[a-h][1-8]');
  for (var token in tokens) {
    if (token.isEmpty) continue;
    Iterable<Match> matches = squarePattern.allMatches(token);
    if (matches.isEmpty) continue;
    String square = matches.last.group(0)!;
    counts[square] = (counts[square] ?? 0) + 1;
  }
  return counts;
}

