import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String layout, int size) {
  if (size <= 0 || layout.isEmpty) {
    return false;
  }

  List<String> rows = layout.split('/');
  if (rows.length != size) {
    return false;
  }

  for (String row in rows) {
    if (row.isEmpty) {
      return false;
    }

    List<String> tokens = row.split(',');
    int moduleCount = 0;
    String lastColor = '';

    for (String token in tokens) {
      if (token.length < 2) {
        return false;
      }

      String color = token[0];
      if (color != 'B' && color != 'W') {
        return false;
      }

      String countText = token.substring(1);
      if (countText.startsWith('0')) {
        return false;
      }

      int? count = int.tryParse(countText);
      if (count == null || count <= 0) {
        return false;
      }

      if (color == lastColor) {
        return false;
      }

      moduleCount += count;
      lastColor = color;
    }

    if (moduleCount != size) {
      return false;
    }
  }

  return true;
}

