@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String input) {
  final trimmed = input.trim();
  if (trimmed.isEmpty) return 0.0;

  final tokens = trimmed.split(RegExp(r'\s+'));
  double totalScore = 0.0;
  int count = 0;

  for (final token in tokens) {
    if (token.length != 2) continue;
    final fileIndex = token[0].codeUnitAt(0) - 96;
    final rankIndex = token[1].codeUnitAt(0) - 48;

    if (fileIndex < 1 || fileIndex > 8 || rankIndex < 1 || rankIndex > 8) continue;

    final df = fileIndex <= 4 ? 4 - fileIndex : fileIndex - 5;
    final dr = rankIndex <= 4 ? 4 - rankIndex : rankIndex - 5;
    final maxDist = df > dr ? df : dr;

    double score;
    if (maxDist == 0) {
      score = 1.0;
    } else if (maxDist == 1) {
      score = 0.75;
    } else if (maxDist == 2) {
      score = 0.5;
    } else {
      score = 0.25;
    }

    totalScore += score;
    count++;
  }

  if (count == 0) return 0.0;
  return totalScore / count;
}

