  print('a + b = $sum');

  Complex diff = a - b;
  print('a - b = $diff');

  Complex prod = a * b;
  print('a * b = $prod');

  Complex quot = a / b;
  print('a / b = $quot');

  print('|a| = ${a.abs().toStringAsFixed(2)}');

  print('arg(a) = ${a.arg().toStringAsFixed(2)} radians');

  print('conj(a) = ${a.conjugate()}');
}

