import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String art, int k) {
  if (k <= 0) return 0.0;
  List<String> lines = art.split('\n');
  int n = lines.length;
  if (n == 0 || k > n) return 0.0;
  List<double> densities = lines.map((line) {
    if (line.isEmpty) return 0.0;
    int stars = line.split('').where((c) => c == '*').length;
    return stars / line.length;
  }).toList();
  double windowSum = 0.0;
  for (int i = 0; i < k; i++) {
    windowSum += densities[i];
  }
  double maxAvg = windowSum / k;
  for (int i = k; i < n; i++) {
    windowSum += densities[i] - densities[i - k];
    double avg = windowSum / k;
    if (avg > maxAvg) maxAvg = avg;
  }
  return maxAvg;
}

