import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> weights = [2, 1, 3, 2, 4, 5];

  List<int> values = [12, 10, 20, 15, 25, 30];

  int capacity = 10;

  int n = weights.length;



  List<List<int>> dp = List.generate(
    n + 1,
    (_) => List.filled(capacity + 1, 0),
  );

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {

      if (weights[i - 1] > w) {
        dp[i][w] = dp[i - 1][w];
      } else {

        int includeItem = values[i - 1] + dp[i - 1][w - weights[i - 1]];
        int excludeItem = dp[i - 1][w];
        dp[i][w] = includeItem > excludeItem ? includeItem : excludeItem;
      }
    }
  }

  List<int> selectedItems = [];
  int w = capacity;
  for (int i = n; i > 0 && w > 0; i--) {

    if (dp[i][w] != dp[i - 1][w]) {
      selectedItems.add(i - 1);
      w -= weights[i - 1];
    }
  }

  print('Knapsack Problem Solution:');
  print('==========================');
  print('Items available:');
  for (int i = 0; i < n; i++) {
    print('  Item ${i + 1}: weight = ${weights[i]}, value = ${values[i]}');
  }
  print('\nKnapsack capacity: $capacity');
  print('\nMaximum value achievable: ${dp[n][capacity]}');

  print('\nSelected items:');
  int totalWeight = 0;
  int totalValue = 0;
  selectedItems.reversed.forEach((index) {
    print('  Item ${index + 1}: weight = ${weights[index]}, value = ${values[index]}');
    totalWeight += weights[index];
    totalValue += values[index];
  });

  print('\nTotal weight used: $totalWeight / $capacity');
  print('Total value obtained: $totalValue');

  print('\nDP Table:');
  print('    ' + List.generate(capacity + 1, (i) => i.toString().padLeft(3)).join(' '));
  for (int i = 0; i <= n; i++) {
    String row = i.toString().padLeft(2) + ': ';
    for (int j = 0; j <= capacity; j++) {
      row += dp[i][j].toString().padLeft(3) + ' ';
    }
    print(row);
  }
}

