import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> rounds) {
  if (rounds.isEmpty) return 0.0;
  final sorted = List<List<int>>.from(rounds);
  sorted.sort((a, b) {
    int acesA = a.where((d) => d == 1).length;
    int acesB = b.where((d) => d == 1).length;
    if (acesA != acesB) return acesB.compareTo(acesA);
    int sixesA = a.where((d) => d == 6).length;
    int sixesB = b.where((d) => d == 6).length;
    if (sixesA != sixesB) return sixesB.compareTo(sixesA);
    int sumA = a.fold(0, (s, d) => s + d);
    int sumB = b.fold(0, (s, d) => s + d);
    return sumB.compareTo(sumA);
  });
  int topCount = (sorted.length + 1) ~/ 2;
  double total = 0;
  for (int i = 0; i < topCount; i++) {
    total += sorted[i].fold(0, (s, d) => s + d);
  }
  return total / topCount;
}

