import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final list = [33, 10, 55, 71, 29, 5, 5, 90, 1, -4, 33, 18];

  print('Before: $list');

  if (list.isNotEmpty) {
    final stackLow = <int>[];
    final stackHigh = <int>[];

    stackLow.add(0);
    stackHigh.add(list.length - 1);

    while (stackLow.isNotEmpty) {
      final low = stackLow.removeLast();
      final high = stackHigh.removeLast();

      if (low >= high) {
        continue; 
      }

      final pivot = list[high];
      var i = low - 1;
      for (var j = low; j < high; j++) {
        if (list[j] <= pivot) {
          i++;
          final tmp = list[i];
          list[i] = list[j];
          list[j] = tmp;
        }
      }

      final tmp = list[i + 1];
      list[i + 1] = list[high];
      list[high] = tmp;
      final p = i + 1;

      if (p - 1 > low) {
        stackLow.add(low);
        stackHigh.add(p - 1);
      }
      if (p + 1 < high) {
        stackLow.add(p + 1);
        stackHigh.add(high);
      }
    }
  }

  print('After:  $list');
}

