@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  String str1 = "kitten";
  String str2 = "sitting";

  int m = str1.length;
  int n = str2.length;

  List<List<int>> dp = List.generate(m + 1, (_) => List.filled(n + 1, 0));

  for (int i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (int j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (str1[i - 1] == str2[j - 1]) {

        dp[i][j] = dp[i - 1][j - 1];
      } else {

        int insert = dp[i][j - 1] + 1;
        int delete = dp[i - 1][j] + 1;
        int replace = dp[i - 1][j - 1] + 1;

        dp[i][j] = insert < delete ? insert : delete;
        dp[i][j] = dp[i][j] < replace ? dp[i][j] : replace;
      }
    }
  }

  print('Edit Distance between "$str1" and "$str2": ${dp[m][n]}');

  List<List<String>> testCases = [
    ["saturday", "sunday"],
    ["", "abc"],
    ["abc", ""],
    ["abc", "abc"],
    ["intention", "execution"],
    ["horse", "ros"],
  ];

  for (var testCase in testCases) {
    String s1 = testCase[0];
    String s2 = testCase[1];

    int len1 = s1.length;
    int len2 = s2.length;

    List<List<int>> matrix = List.generate(len1 + 1, (_) => List.filled(len2 + 1, 0));

    for (int i = 0; i <= len1; i++) {
      matrix[i][0] = i;
    }
    for (int j = 0; j <= len2; j++) {
      matrix[0][j] = j;
    }

    for (int i = 1; i <= len1; i++) {
      for (int j = 1; j <= len2; j++) {
        if (s1[i - 1] == s2[j - 1]) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          int insertOp = matrix[i][j - 1] + 1;
          int deleteOp = matrix[i - 1][j] + 1;
          int replaceOp = matrix[i - 1][j - 1] + 1;

          matrix[i][j] = insertOp < deleteOp ? insertOp : deleteOp;
          matrix[i][j] = matrix[i][j] < replaceOp ? matrix[i][j] : replaceOp;
        }
      }
    }

    print('Edit Distance between "$s1" and "$s2": ${matrix[len1][len2]}');
  }
}

