import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int find(List<int> parent, int i) {
    if (parent[i] != i) {
      parent[i] = find(parent, parent[i]);
    }
    return parent[i];
  }

  void unionSets(List<int> parent, List<int> rank, int x, int y) {
    int xroot = find(parent, x);
    int yroot = find(parent, y);
    if (xroot != yroot) {
      if (rank[xroot] < rank[yroot]) {
        parent[xroot] = yroot;
      } else if (rank[xroot] > rank[yroot]) {
        parent[yroot] = xroot;
      } else {
        parent[yroot] = xroot;
        rank[xroot]++;
      }
    }
  }

  int n = 5;
  List<int> parent = List.generate(n, (i) => i);
  List<int> rank = List.generate(n, (i) => 0);

  print('Initial sets:');
  for (int i = 0; i < n; i++) {
    print('Parent of $i: ${find(parent, i)}');
  }

  unionSets(parent, rank, 0, 1);
  unionSets(parent, rank, 2, 3);
  unionSets(parent, rank, 0, 4);
  unionSets(parent, rank, 2, 4);

  print('\nAfter unions:');
  for (int i = 0; i < n; i++) {
    print('Parent of $i: ${find(parent, i)}');
  }

  bool same13 = find(parent, 1) == find(parent, 3);
  print('\n1 and 3 in same set: $same13'); 

  bool same02 = find(parent, 0) == find(parent, 2);
  print('0 and 2 in same set: $same02'); 

  unionSets(parent, rank, 1, 3);
  print('\nAfter redundant union:');
  for (int i = 0; i < n; i++) {
    print('Parent of $i: ${find(parent, i)}');
  }
}

