import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<String> operations) {
  List<int> stack = [];
  int throughput = 0;
  for (var op in operations) {
    if (op.startsWith('LOAD:')) {
      int weight = int.parse(op.substring(5));
      stack.add(weight);
    } else if (op == 'SHIP') {
      if (stack.isNotEmpty) {
        throughput += stack.removeLast();
      }
    } else if (op == 'COMBINE') {
      if (stack.length >= 2) {
        int b = stack.removeLast();
        int a = stack.removeLast();
        stack.add(a + b);
      }
    } else if (op == 'CLEAR') {
      while (stack.isNotEmpty) {
        throughput += stack.removeLast();
      }
    }
  }
  return throughput;
}

