import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int width = 80;         
  const int height = 24;        
  const int siteCount = 10;     


  final rng = Random(0);
  final List<Point<double>> sites = List.generate(
    siteCount,
    (_) => Point<double>(
      rng.nextInt(width).toDouble(),
      rng.nextInt(height).toDouble(),
    ),
  );

  const String labels =
      '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
  if (siteCount > labels.length) {
    print('Error: Not enough label characters for $siteCount sites.');
    return;
  }

  for (int i = 0; i < siteCount; i++) {
    final p = sites[i];
    print('${labels[i]} => (${p.x.toInt()}, ${p.y.toInt()})');
  }
  print('');

  num distanceSquared(Point<double> p, double x, double y) {
    final dx = p.x - x;
    final dy = p.y - y;
    return dx * dx + dy * dy;
  }

  final buffer = StringBuffer();
  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      int closest = 0;
      num best = distanceSquared(sites[0], x.toDouble(), y.toDouble());
      bool tie = false;

      for (int s = 1; s < siteCount; s++) {
        final d = distanceSquared(sites[s], x.toDouble(), y.toDouble());
        if (d < best - 1e-9) {
          best = d;
          closest = s;
          tie = false;
        } else if ((d - best).abs() < 1e-9) {
          tie = true; 
        }
      }

      buffer.write(tie ? '.' : labels[closest]);
    }
    buffer.writeln();
  }

  print(buffer.toString());
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int FIXED_POINT_SHIFT = 16;
  const int FIXED_POINT_SCALE = 1 << FIXED_POINT_SHIFT; 
  const int FRACTIONAL_MASK = FIXED_POINT_SCALE - 1;

  int toFixed(double value) {
    return (value * FIXED_POINT_SCALE).round();
  }

  double fromFixed(int fixed) {
    return fixed / FIXED_POINT_SCALE;
  }

  int getIntegerPart(int fixed) {
    return fixed >> FIXED_POINT_SHIFT;
  }

  int getFractionalPart(int fixed) {
    return fixed & FRACTIONAL_MASK;
  }

  int fixedAdd(int a, int b) {
    return a + b;
  }

  int fixedSubtract(int a, int b) {
    return a - b;
  }

  int fixedMultiply(int a, int b) {

    int result = (a * b) >> FIXED_POINT_SHIFT;
    return result;
  }

  int fixedDivide(int a, int b) {
    if (b == 0) {
      throw ArgumentError('Division by zero');
    }

    int result = (a << FIXED_POINT_SHIFT) ~/ b;
    return result;
  }

  int fixedSqrt(int x) {
    if (x < 0) {
      throw ArgumentError('Cannot compute square root of negative number');
    }
    if (x == 0) return 0;

    int guess = x;
    int prev = 0;
    int one = toFixed(1.0);

    for (int i = 0; i < 20; i++) {
      if (guess == prev) break;
      prev = guess;

      int quotient = fixedDivide(x, guess);
      guess = (guess + quotient) >> 1;
    }

    return guess;
  }

  int fixedSin(int angle) {

    int twoPi = toFixed(6.283185307179586);
    int pi = toFixed(3.141592653589793);

    while (angle > pi) angle -= twoPi;
    while (angle < -pi) angle += twoPi;

    int x = angle;
    int x2 = fixedMultiply(x, x);
    int x3 = fixedMultiply(x2, x);
    int x5 = fixedMultiply(x3, x2);
    int x7 = fixedMultiply(x5, x2);

    int fact3 = toFixed(1.0 / 6.0);
    int fact5 = toFixed(1.0 / 120.0);
    int fact7 = toFixed(1.0 / 5040.0);

    int result = x;
    result = fixedSubtract(result, fixedMultiply(x3, fact3));
    result = fixedAdd(result, fixedMultiply(x5, fact5));
    result = fixedSubtract(result, fixedMultiply(x7, fact7));

    return result;
  }

  int fixedCos(int angle) {
    int halfPi = toFixed(1.5707963267948966);
    return fixedSin(fixedAdd(angle, halfPi));
  }

  print('Fixed-Point Math Demonstration');
  print('==============================');
  print('Using 16.16 fixed-point format\n');

  double a = 3.14159;
  double b = 2.71828;

  int fixedA = toFixed(a);
  int fixedB = toFixed(b);

  print('Original values:');
  print('  a = $a');
  print('  b = $b\n');

  print('Fixed-point representation:');
  print('  a (fixed) = $fixedA (0x${fixedA.toRadixString(16)})');
  print('  b (fixed) = $fixedB (0x${fixedB.toRadixString(16)})\n');

  int sum = fixedAdd(fixedA, fixedB);
  print('Addition: ${fromFixed(fixedA)} + ${fromFixed(fixedB)} = ${fromFixed(sum)}');
  print('  Expected: ${a + b}\n');

  int diff = fixedSubtract(fixedA, fixedB);
  print('Subtraction: ${fromFixed(fixedA)} - ${fromFixed(fixedB)} = ${fromFixed(diff)}');
  print('  Expected: ${a - b}\n');

  int product = fixedMultiply(fixedA, fixedB);
  print('Multiplication: ${fromFixed(fixedA)} × ${fromFixed(fixedB)} = ${fromFixed(product)}');
  print('  Expected: ${a * b}\n');

  int quotient = fixedDivide(fixedA, fixedB);
  print('Division: ${fromFixed(fixedA)} ÷ ${fromFixed(fixedB)} = ${fromFixed(quotient)}');
  print('  Expected: ${a / b}\n');

  double sqrtInput = 2.0;
  int fixedSqrtInput = toFixed(sqrtInput);
  int sqrtResult = fixedSqrt(fixedSqrtInput);
  print('Square root: √${fromFixed(fixedSqrtInput)} = ${fromFixed(sqrtResult)}');
  print('  Expected: ${1.4142135623730951}\n');

  print('Trigonometric functions:');
  List<double> angles = [0, 0.5236, 0.7854, 1.0472, 1.5708]; 

  for (double angle in angles) {
    int fixedAngle = toFixed(angle);
    int sinResult = fixedSin(fixedAngle);
    int cosResult = fixedCos(fixedAngle);

    print('  Angle: ${angle.toStringAsFixed(4)} rad');
    print('    sin = ${fromFixed(sinResult).toStringAsFixed(6)}');
    print('    cos = ${fromFixed(cosResult).toStringAsFixed(6)}');
  }

  print('\nPrecision Test:');
  print('================');
  double small = 0.00001;
  int fixedSmall = toFixed(small);
  print('Small value: $small');
  print('Fixed representation: $fixedSmall');
  print('Converted back: ${fromFixed(fixedSmall)}\n');

  print('Chain Operations:');
  print('=================');
  double x = 1.5;
  double y = 2.5;
  double z = 3.5;

  int fx = toFixed(x);
  int fy = toFixed(y);
  int fz = toFixed(z);

  int temp1 = fixedAdd(fx, fy);
  int result1 = fixedMultiply(temp1, fz);
  print('($x + $y) × $z = ${fromFixed(result1)}');
  print('  Expected: ${(x + y) * z}\n');

  int fx2 = fixedMultiply(fx, fx);
  int fy2 = fixedMultiply(fy, fy);
  int sumSquares = fixedAdd(fx2, fy2);
  print('$x² + $y² = ${fromFixed(sumSquares)}');
  print('  Expected: ${x * x + y * y}\n');

  int hypotenuse = fixedSqrt(sumSquares);
  print('√($x² + $y²) = ${fromFixed(hypotenuse)}');
  print('  Expected: ${2.9154759474226504}');
}

