import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<String> commands) {
  if (commands.isEmpty) return false;
  int state = 0;
  bool isShuffle = false;
  Set<String> playedTracks = <String>{};

  for (int i = 0; i < commands.length; i++) {
    String cmd = commands[i];
    if (state == 0) {
      if (cmd == "PLAY") {
        state = 1;
      } else {
        return false;
      }
    } else if (state == 1) {
      if (cmd.length == 7 && cmd.startsWith("TRACK_")) {
        String id = cmd.substring(6);
        if (id.codeUnitAt(0) >= 48 && id.codeUnitAt(0) <= 57) {
          if (isShuffle && playedTracks.contains(id)) {
            return false;
          }
          playedTracks.add(id);
          state = 2;
        } else {
          return false;
        }
      } else {
        return false;
      }
    } else if (state == 2) {
      if (cmd == "NEXT") {
        state = 1;
      } else if (cmd == "PREV") {
        if (isShuffle) return false;
        state = 1;
      } else if (cmd == "SHUFFLE_ON") {
        isShuffle = true;
      } else if (cmd == "SHUFFLE_OFF") {
        isShuffle = false;
      } else if (cmd == "PAUSE") {
        state = 3;
      } else {
        return false;
      }
    } else {
      return false;
    }
  }
  return state == 3;
}

