import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(int low, int high) {
  const morse = ['-----', '.----', '..---', '...--', '....-',
                 '.....', '-....', '--...', '---..', '----.'];
  const dashes = [5, 4, 3, 2, 1, 0, 1, 2, 3, 4];
  bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++) {
      if (n % i == 0) return false;
    }
    return true;
  }
  List<String> result = [];
  for (int num = low; num <= high; num++) {
    int n = num, totalDashes = 0;
    List<String> parts = [];
    if (n == 0) {
      totalDashes = 5;
      parts.add(morse[0]);
    } else {
      List<int> digs = [];
      while (n > 0) { digs.add(n % 10); n ~/= 10; }
      for (int d in digs.reversed) {
        totalDashes += dashes[d];
        parts.add(morse[d]);
      }
    }
    if (isPrime(totalDashes) && num % 5 != 0) {
      result.add(parts.join(' '));
    }
  }
  return result;
}

