import 'dart:async';
import 'dart:convert';
class KDNode {
  final List<double> point;
  KDNode? left, right;
  KDNode(this.point);
  @override
  String toString() => 'KDNode(${point.join(', ')})';
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  KDNode? buildKDTree(List<List<double>> pts, int depth) {
    if (pts.isEmpty) return null;
    int k = pts[0].length;
    int axis = depth % k;

    pts.sort((a, b) => a[axis].compareTo(b[axis]));
    int median = pts.length ~/ 2;
    var node = KDNode(pts[median]);
    node.left = buildKDTree(pts.sublist(0, median), depth + 1);
    node.right = buildKDTree(pts.sublist(median + 1), depth + 1);
    return node;
  }

  void printTree(KDNode? node, [int depth = 0]) {
    if (node == null) return;
    print('${'  ' * depth}${node.point}');
    printTree(node.left, depth + 1);
    printTree(node.right, depth + 1);
  }

  List<List<double>> samplePoints = [
    [2.0, 3.0],
    [5.0, 4.0],
    [9.0, 6.0],
    [4.0, 7.0],
    [8.0, 1.0],
    [7.0, 2.0],
  ];

  var root = buildKDTree(samplePoints, 0);
  print('Constructed k-d tree:');
  printTree(root);
}

