Map<String, int> fn0(String stream) {
  int pixels = 0, errors = 0, totalR = 0, totalG = 0, totalB = 0;
  int currentR = -1, currentG = -1, currentB = -1;
  String currentColor = "", buffer = "";

  void process() {
    if (buffer.isEmpty) return;
    if (currentColor == "r" || currentColor == "g" || currentColor == "b") {
      if (buffer.length > 10) {
        errors++;
        if (currentColor == "r") currentR = -1;
        else if (currentColor == "g") currentG = -1;
        else currentB = -1;
      } else {
        int val = int.parse(buffer);
        if (val > 255) {
          errors++;
          if (currentColor == "r") currentR = -1;
          else if (currentColor == "g") currentG = -1;
          else currentB = -1;
        } else {
          if (currentColor == "r") currentR = val;
          else if (currentColor == "g") currentG = val;
          else currentB = val;
        }
      }
    } else {
      errors++;
    }
    buffer = "";
    currentColor = "";
  }

  for (int i = 0; i <= stream.length; i++) {
    String ch = (i < stream.length) ? stream[i] : " ";
    int code = ch.codeUnitAt(0);
    if (code >= 48 && code <= 57) {
      buffer += ch;
    } else {
      process();
      if (ch == 'r' || ch == 'g' || ch == 'b') {
        currentColor = ch;
      } else if (ch == 'p') {
        if (currentR != -1 && currentG != -1 && currentB != -1) {
          pixels++; totalR += currentR; totalG += currentG; totalB += currentB;
        } else {
          errors++;
        }
        currentR = currentG = currentB = -1;
      } else if (ch == 'c') {
        currentR = currentG = currentB = -1;
      } else if (ch != ' ' && ch != '\n' && ch != '\r' && ch != '\t') {
        errors++;
        currentR = currentG = currentB = -1;
      }
    }
  }
  return {"pixels": pixels, "errors": errors, "totalR": totalR, "totalG": totalG, "totalB": totalB};
}

