import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<List<int>> grid, int threshold) {
  if (grid.isEmpty || grid[0].isEmpty) return '';
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<List<int>> pockets = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c] && grid[r][c] < threshold) {
        int size = 0;
        int minVal = grid[r][c];
        List<List<int>> queue = [[r, c]];
        visited[r][c] = true;
        int head = 0;
        while (head < queue.length) {
          List<int> curr = queue[head++];
          size++;
          if (grid[curr[0]][curr[1]] < minVal) {
            minVal = grid[curr[0]][curr[1]];
          }
          List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
          for (List<int> d in dirs) {
            int nr = curr[0] + d[0];
            int nc = curr[1] + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                !visited[nr][nc] && grid[nr][nc] < threshold) {
              visited[nr][nc] = true;
              queue.add([nr, nc]);
            }
          }
        }
        pockets.add([size, minVal]);
      }
    }
  }
  pockets.sort((a, b) {
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    return a[1].compareTo(b[1]);
  });
  return pockets.map((p) => '${p[0]}:${p[1]}').join(';');
}

