@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String input) {
  final result = <int>[];
  int state = 0; 
  int dollars = 0;
  bool sawDollarDigit = false;
  final frac = <int>[];
  void finish() {
    if ((state == 1 || state == 2) && sawDollarDigit) {
      int cents = dollars * 100 +
          (frac.isNotEmpty ? frac[0] : 0) * 10 +
          (frac.length > 1 ? frac[1] : 0);
      if (frac.length > 2 && frac[2] >= 5) cents++;
      result.add(cents);
    }
    state = 0;
    dollars = 0;
    sawDollarDigit = false;
    frac.clear();
  }
  for (int i = 0; i < input.length; i++) {
    final c = input.codeUnitAt(i);
    if (c == 32) {
      finish();
      continue;
    }
    final isDigit = c >= 48 && c <= 57;
    if (state == 0) {
      state = (c == 36) ? 1 : 3;
    } else if (state == 1) {
      if (isDigit) {
        dollars = dollars * 10 + (c - 48);
        sawDollarDigit = true;
      } else if (c == 46 && sawDollarDigit) {
        state = 2;
      } else {
        state = 3;
      }
    } else if (state == 2) {
      if (isDigit) {
        frac.add(c - 48);
      } else {
        state = 3;
      }
    }
  }
  finish();
  return result;
}

