import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String encoded) {
  if (encoded.isEmpty) return 0.0;
  List<String> mainParts = encoded.split('|');
  if (mainParts.length != 2) return -1.0;
  String binsPart = mainParts[0];
  String checksumPart = mainParts[1];
  int? checksum = int.tryParse(checksumPart);
  if (checksum == null || checksum <= 0) return -1.0;
  if (binsPart.isEmpty) return -1.0;
  List<String> bins = binsPart.split(',');
  int countSum = 0;
  double weightedSum = 0.0;
  for (String bin in bins) {
    List<String> parts = bin.split('x');
    if (parts.length != 2) return -1.0;
    int? strength = int.tryParse(parts[0]);
    int? count = int.tryParse(parts[1]);
    if (strength == null || count == null) return -1.0;
    if (strength > -30 || strength < -90) return -1.0;
    if (count <= 0) return -1.0;
    double quality = (-strength - 30) / 60.0;
    weightedSum += quality * count;
    countSum += count;
  }
  if (countSum != checksum) return -1.0;
  return weightedSum / countSum;
}

