int fn0(List<List<int>> schedule, int minute) {




  if (schedule.isEmpty) return -1;
  final int m = ((minute % 1440) + 1440) % 1440;
  final entries = schedule.map((e) => List<int>.from(e)).toList();
  entries.sort((a, b) {
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    if (a[1] != b[1]) return b[1].compareTo(a[1]);
    return a[2].compareTo(b[2]);
  });
  int targetStart = -1;
  for (final e in entries) {
    if (e[0] <= m && e[0] > targetStart) {
      targetStart = e[0];
    }
  }
  if (targetStart == -1) {

    targetStart = entries.last[0];
  }
  for (final e in entries) {
    if (e[0] == targetStart) return e[2];
  }
  return -1;
}

