    final c = editScript[pos];
    if (c == 'M') {
      if (i < word.length) i++;
      pos++;
    } else if (c == 'D') {
      if (i < word.length) {
        edits.add(i);
        i++;
      }
      pos++;
    } else if (c == 'I') {
      pos++;
      if (pos < editScript.length) {
        edits.add(i);
        pos++;
