bool fn0(List<List<int>> shelves, int roomW, int roomH) {
  for (int i = 0; i < shelves.length; i++) {
    int x = shelves[i][0];
    int y = shelves[i][1];
    int w = shelves[i][2];
    int h = shelves[i][3];
    if (w <= 0 || h <= 0) {
      return false;
    }
    if (x < 0 || y < 0 || x + w > roomW || y + h > roomH) {
      return false;
    }
    for (int j = 0; j < i; j++) {
      int x2 = shelves[j][0];
      int y2 = shelves[j][1];
      int w2 = shelves[j][2];
      int h2 = shelves[j][3];
      bool overlapX = x < x2 + w2 && x2 < x + w;
      bool overlapY = y < y2 + h2 && y2 < y + h;
      if (overlapX && overlapY) {
        return false;
      }
    }
  }
  return true;
}

