List<int> fn0(int epochDay, int intervalDays, int startDay, int endDay) {
  if (intervalDays <= 0 || startDay > endDay) return [];
  var firstPass = epochDay;
  if (firstPass < startDay) {
    final gap = startDay - epochDay;
    firstPass = epochDay + ((gap + intervalDays - 1) ~/ intervalDays) * intervalDays;
  }
  final passes = <int>[];
  for (var day = firstPass; day <= endDay; day += intervalDays) {
    passes.add(day);
  }
  return passes;
}

