List<int> fn0(List<String> symbols) {
  if (symbols.isEmpty) return [];
  List<String> dotStart = [];
  List<String> dashStart = [];
  for (String s in symbols) {
    if (s.isEmpty) continue;
    if (s[0] == '.') {
      dotStart.add(s);
    } else if (s[0] == '-') {
      dashStart.add(s);
    }
  }
  List<int> computeTimes(List<String> list) {
    List<int> times = [];
    for (String sym in list) {
      int total = 0;
      for (int i = 0; i < sym.length; i++) {
        total += (sym[i] == '.') ? 1 : 3;
        if (i < sym.length - 1) total += 1;
      }
      times.add(total);
    }
    return times;
  }
  List<int> dotTimes = computeTimes(dotStart);
  List<int> dashTimes = computeTimes(dashStart);
  return [...dotTimes, ...dashTimes];
}

