import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> shelfStocks, int threshold) {
  int totalPriority = 0;
  int index = 0;

  while (index < shelfStocks.length) {
    final current = shelfStocks[index];
    if (current < threshold) {
      final deficit = threshold - current;
      if (index + 1 < shelfStocks.length && shelfStocks[index + 1] < threshold) {
        final nextDeficit = threshold - shelfStocks[index + 1];
        totalPriority += (deficit + nextDeficit) * 2;
        index += 2;
      } else {
        totalPriority += deficit;
        index += 1;
      }
    } else {
      index += 1;
    }
  }

  return totalPriority;
}

