List<String> fn0(String telemetry) {
  final results = <String>[];
  var buffer = '';

  var state = 0;
  for (var i = 0; i < telemetry.length; i++) {
    final ch = telemetry[i];
    if (state == 0) {
      if (ch == 'T') { state = 1; buffer = 'T'; }
      else if (ch == 'P') { state = 2; buffer = 'P'; }
    } else if (state == 1) {
      if (ch == 'A') { results.add('${buffer}A'); buffer = ''; state = 0; }
      else if (ch == 'H') { buffer += 'H'; state = 3; }
      else if (ch == 'T') { buffer = 'T'; }
      else if (ch == 'P') { state = 2; buffer = 'P'; }
      else if (ch == 'X') { buffer = ''; state = 0; }
    } else if (state == 2) {
      if (ch == 'H') { buffer += 'H'; state = 3; }
      else if (ch == 'T') { state = 1; buffer = 'T'; }
      else if (ch == 'P') { buffer = 'P'; }
      else { buffer = ''; state = 0; } 
    } else { 
      if (ch == 'A') { results.add('${buffer}A'); buffer = ''; state = 0; }
      else if (ch == 'H') { buffer += 'H'; }
      else if (ch == 'T') { state = 1; buffer = 'T'; }
      else if (ch == 'P') { state = 2; buffer = 'P'; }
      else if (ch == 'X') { buffer = ''; state = 0; }
    }
  }
  return results;
}

