import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<List<int>> timetable, int maxTransfer) {
  if (timetable.isEmpty) {
    return true;
  }

  int columnCount = timetable[0].length;
  List<List<int>> normalized = [];

  for (int r = 0; r < timetable.length; r++) {
    if (timetable[r].length != columnCount) {
      return false;
    }

    List<int> row = [];
    for (int c = 0; c < timetable[r].length; c++) {
      int minute = timetable[r][c];

      if (c > 0) {
        while (minute < row[c - 1]) {
          minute += 60;
        }

        if (minute - row[c - 1] > maxTransfer) {
          return false;
        }
      }

      row.add(minute);
    }

    normalized.add(row);
  }

  for (int c = 0; c < columnCount; c++) {
    for (int r = 1; r < normalized.length; r++) {
      if (normalized[r][c] <= normalized[r - 1][c]) {
        return false;
      }
    }
  }

  return true;
}

