import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<String> rows, int columnCount) {
  if (rows.isEmpty || columnCount <= 0) return '';

  final int total = rows.length;
  final int cols = columnCount > total ? total : columnCount;
  if (cols <= 0) return '';

  final int base = total ~/ cols;
  final int rem = total % cols;

  final List<List<String>> columns = [];
  int start = 0;
  for (int i = 0; i < cols; i++) {
    final int len = base + (i < rem ? 1 : 0);
    columns.add(rows.sublist(start, start + len));
    start += len;
  }

  final List<int> widths = [];
  for (final List<String> col in columns) {
    int maxW = 0;
    for (final String row in col) {
      if (row.length > maxW) maxW = row.length;
    }
    widths.add(maxW);
  }

  final int maxRows = base + (rem > 0 ? 1 : 0);
  final List<String> lines = [];
  for (int r = 0; r < maxRows; r++) {
    final List<String> parts = [];
    for (int c = 0; c < cols; c++) {
      final List<String> col = columns[c];
      final String cell = r < col.length ? col[r].padRight(widths[c]) : ''.padRight(widths[c]);
      parts.add(cell);
    }
    lines.add(parts.join(' | '));
  }

  return lines.join('\n');
}

