int fn0(List<int> seats, int groupSize) {
  if (groupSize == 0) return 0;
  if (seats.length < groupSize) return -1;
  int currentOccupied = 0;
  for (int i = 0; i < groupSize; i++) {
    currentOccupied += seats[i];
