void fn0() {

  List<int> nums = [1, 2, 3];

  List<List<int>> result = [];

  void backtrack(List<int> current, List<bool> used) {
    if (current.length == nums.length) {
      result.add(List.from(current));
      return;
    }

    for (int i = 0; i < nums.length; i++) {
      if (!used[i]) {
        used[i] = true;
        current.add(nums[i]);
        backtrack(current, used);
        current.removeLast();
        used[i] = false;
      }
    }
  }

  List<bool> used = List<bool>.filled(nums.length, false);

  backtrack([], used);

  for (var perm in result) {
    print(perm);
  }
}

