import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  Iterable<int> fibonacci(int n) sync* {
    int a = 0, b = 1;
    for (int i = 0; i < n; i++) {
      yield a;
      int next = a + b;
      a = b;
      b = next;
    }
  }

  Iterable<int> squares(int n) sync* {
    for (int i = 1; i <= n; i++) {
      yield i * i;
    }
  }

  print('First 10 Fibonacci numbers:');
  for (var num in fibonacci(10)) {
    print(num);
  }

  print('\nSquares up to 5:');
  for (var sq in squares(5)) {
    print(sq);
  }
}

