bool fn0(List<String> dict, String query) {
  for (int i = 0; i < query.length; i++) {
    for (int c = 97; c <= 122; c++) {
      if (c == query.codeUnitAt(i)) continue;
      String fn0 = query.substring(0, i) + String.fromCharCode(c) + query.substring(i + 1);
      int lo = 0, hi = dict.length - 1;
      while (lo <= hi) {
        int mid = (lo + hi) ~/ 2;
        int cmp = dict[mid].compareTo(fn0);
        if (cmp == 0) return true;
        if (cmp < 0) lo = mid + 1; else hi = mid - 1;
      }
    }
  }
  return false;
}

