String fn0(List<int> durs, int limit) {
  String best = "";
  int bestScore = -1;
  void bt(int start, List<int> curr, int sum) {
    if (sum > limit) return;
    int score = curr.length * 1000 + sum;
    if (score > bestScore) {
      bestScore = score;
      best = curr.join(',');
    }
    for (int i = start; i < durs.length; i++) {
      curr.add(durs[i]);
      bt(i + 1, curr, sum + durs[i]);
      curr.removeLast();
    }
  }
  bt(0, [], 0);
  return best;
}

