import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> maze, int width, int height) {
  if (width <= 0 || height <= 0 || maze.isEmpty) return 0;
  const int NORTH = 1;
  const int EAST = 2;
  const int SOUTH = 4;
  const int WEST = 8;
  final int totalCells = width * height;
  final int visitedWords = (totalCells + 63) >> 6;
  final List<int> visited = List<int>.filled(visitedWords, 0);
  final List<int> stack = [0];
  visited[0] = 1;
  int reachable = 0;
  while (stack.isNotEmpty) {
    final int cell = stack.removeLast();
    reachable++;
    final int walls = maze[cell];
    final int x = cell % width;
    final int y = cell ~/ width;
    if ((walls & NORTH) == 0 && y > 0) {
      final int neighbor = cell - width;
      final int word = neighbor >> 6;
      final int bit = neighbor & 63;
      if ((visited[word] & (1 << bit)) == 0) {
        visited[word] |= (1 << bit);
        stack.add(neighbor);
      }
    }
    if ((walls & EAST) == 0 && x < width - 1) {
      final int neighbor = cell + 1;
      final int word = neighbor >> 6;
      final int bit = neighbor & 63;
      if ((visited[word] & (1 << bit)) == 0) {
        visited[word] |= (1 << bit);
        stack.add(neighbor);
      }
    }
    if ((walls & SOUTH) == 0 && y < height - 1) {
      final int neighbor = cell + width;
      final int word = neighbor >> 6;
      final int bit = neighbor & 63;
      if ((visited[word] & (1 << bit)) == 0) {
        visited[word] |= (1 << bit);
        stack.add(neighbor);
      }
    }
    if ((walls & WEST) == 0 && x > 0) {
      final int neighbor = cell - 1;
      final int word = neighbor >> 6;
      final int bit = neighbor & 63;
      if ((visited[word] & (1 << bit)) == 0) {
        visited[word] |= (1 << bit);
        stack.add(neighbor);
      }
    }
  }
  return reachable;
}

