Map<String, int> fn0(String ledger) {
  int balance = 0;
  int deposits = 0;
  int withdrawals = 0;
  if (ledger.isEmpty) return {'balance': 0, 'deposits': 0, 'withdrawals': 0};
  List<String> tokens = ledger.split(' ');
  for (String t in tokens) {
    if (t.startsWith('+')) {
      balance += int.parse(t.substring(1));
      deposits += 1;
    } else if (t.startsWith('-')) {
      balance -= int.parse(t.substring(1));
      withdrawals += 1;
    }
  }
  return {'balance': balance, 'deposits': deposits, 'withdrawals': withdrawals};
}

