String fn0(String schedule, int timeMinutes) {
  String currentMode = 'C';
  double currentTemp = 24.0;
  if (schedule.isEmpty) return '$currentMode:${currentTemp.toStringAsFixed(1)}';
  var events = schedule.split(';');
  for (var event in events) {
    if (event.isEmpty) continue;
    var parts = event.split(',');
    var modeTime = parts[0]; 
    var tempPart = parts[1]; 
    String modeChar = modeTime[0];
    String timeStr = modeTime.substring(2); 
    var timeParts = timeStr.split(':');
    int eventTime = int.parse(timeParts[0]) * 60 + int.parse(timeParts[1]);
    if (eventTime <= timeMinutes) {
      currentMode = modeChar;
      currentTemp = double.parse(tempPart.substring(2));
    } else {
      break;
    }
  }
  return '$currentMode:${currentTemp.toStringAsFixed(1)}';
}

