import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(int totalZones, List<int> irrigationDays, int decayDays, int windowStart, int windowEnd) {
  if (totalZones <= 0 || decayDays <= 0 || windowStart > windowEnd) return <int>{};
  final Map<int, int> lastWater = <int, int>{};
  for (int i = 0; i < irrigationDays.length; i++) {
    final int zone = i % totalZones;
    final int day = irrigationDays[i];
    final int? prev = lastWater[zone];
    if (prev == null || day > prev) {
      lastWater[zone] = day;
    }
  }
  final Map<int, int> becomeDryCount = <int, int>{};
  for (int zone = 0; zone < totalZones; zone++) {
    final int? w = lastWater[zone];
    if (w != null) {
      final int dryDay = w + decayDays;
      becomeDryCount[dryDay] = (becomeDryCount[dryDay] ?? 0) + 1;
    }
  }
  final Set<int> irrigationDaySet = irrigationDays.toSet();
  final int threshold = (totalZones + 1) ~/ 2;
  final Set<int> result = <int>{};
  for (int d = windowStart; d <= windowEnd; d++) {
    final int count = becomeDryCount[d] ?? 0;
    if (count >= threshold && !irrigationDaySet.contains(d)) {
      result.add(d);
    }
  }
  return result;
}

