@pragma('vm:entry-point')
double fn0(List<double> weights, int windowSize) {
  if (weights.isEmpty || windowSize <= 0 || windowSize > weights.length) return 0.0;
  double currentSum = 0.0;
  for (int i = 0; i < windowSize; i++) {
    currentSum += weights[i];
  }
  double maxSum = currentSum;
  for (int i = windowSize; i < weights.length; i++) {
    currentSum += weights[i] - weights[i - windowSize];
    if (currentSum > maxSum) {
      maxSum = currentSum;
    }
  }
  return maxSum / windowSize;
}

