import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String input) {
  final List<int> result = [];
  final lines = input.split('\n');
  for (final line in lines) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) continue;
    final parts = trimmed.split(':');
    if (parts.length != 2) continue;
    final valueStr = parts[1].trim();
    String unit;
    String numberStr;
    if (valueStr.endsWith('cm')) {
      unit = 'cm';
      numberStr = valueStr.substring(0, valueStr.length - 2).trim();
    } else if (valueStr.endsWith('m')) {
      unit = 'm';
      numberStr = valueStr.substring(0, valueStr.length - 1).trim();
    } else {
      continue;
    }
    final height = int.tryParse(numberStr);
    if (height == null) continue;
    if (unit == 'm') {
      result.add(height * 100);
    } else {
      result.add(height);
    }
  }
  return result;
}

