List<int> fn0(int square) {
  if (square < 0 || square > 63) return [];
  List<int> attacks = [];
  int row = square ~/ 8;
  int col = square % 8;
  for (int i = 1;; i++) {
    int nr = row + i;
    int nc = col + i;
    if (nr > 7 || nc > 7) break;
    attacks.add(nr * 8 + nc);
  }
  for (int i = 1;; i++) {
    int nr = row + i;
    int nc = col - i;
    if (nr > 7 || nc < 0) break;
    attacks.add(nr * 8 + nc);
  }
  for (int i = 1;; i++) {
    int nr = row - i;
    int nc = col + i;
    if (nr < 0 || nc > 7) break;
    attacks.add(nr * 8 + nc);
  }
  for (int i = 1;; i++) {
    int nr = row - i;
    int nc = col - i;
    if (nr < 0 || nc < 0) break;
    attacks.add(nr * 8 + nc);
  }
  return attacks;
}

