import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<double>> points = [
    [1.0, 2.0],
    [2.0, 2.0],
    [2.0, 3.0],
    [8.0, 8.0],
    [8.5, 8.1],
    [7.9, 8.2],
    [100.0, 100.0], 
  ];

  double eps = 1.5; 
  int minPts = 3;   

  int n = points.length;
  List<int> labels = List.filled(n, 0); 
  int clusterId = 0;

  List<int> regionQuery(int idx) {
    List<int> neighbors = [];
    for (int i = 0; i < n; i++) {
      double dx = points[idx][0] - points[i][0];
      double dy = points[idx][1] - points[i][1];
      double dist = sqrt(dx * dx + dy * dy);
      if (dist <= eps) {
        neighbors.add(i);
      }
    }
    return neighbors;
  }

  void expandCluster(int idx, List<int> neighbors, int cid) {
    labels[idx] = cid;
    List<int> seeds = List<int>.from(neighbors);
    for (int i = 0; i < seeds.length; i++) {
      int current = seeds[i];
      if (labels[current] == -1) {
        labels[current] = cid; 
      }
      if (labels[current] != 0) {
        continue; 
      }
      labels[current] = cid;
      List<int> result = regionQuery(current);
      if (result.length >= minPts) {
        for (int r in result) {
          if (!seeds.contains(r)) {
            seeds.add(r);
          }
        }
      }
    }
  }

  for (int i = 0; i < n; i++) {
    if (labels[i] != 0) {
      continue; 
    }
    List<int> neighbors = regionQuery(i);
    if (neighbors.length < minPts) {
      labels[i] = -1; 
    } else {
      clusterId++;
      expandCluster(i, neighbors, clusterId);
    }
  }

  Map<int, List<int>> clusters = {};
  for (int i = 0; i < n; i++) {
    clusters.putIfAbsent(labels[i], () => []).add(i);
  }

  clusters.forEach((label, idxs) {
    if (label == -1) {
      print('Noise:');
    } else {
      print('Cluster $label:');
    }
    for (int idx in idxs) {
      print('  Point $idx -> ${points[idx]}');
    }
  });
}

