import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> codes) {
  int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
      sum += n % 10;
      n ~/= 10;
    }
    return sum;
  }
  bool isPerfectSquare(int n) {
    if (n < 0) return false;
    for (int i = 0; i * i <= n; i++) {
      if (i * i == n) return true;
    }
    return false;
  }
  List<String> sorted = List<String>.from(codes);
  sorted.sort((a, b) {
    List<String> pA = a.split('-');
    List<String> pB = b.split('-');
    String secA = pA[0], secB = pB[0];
    int shelfA = int.parse(pA[1]), shelfB = int.parse(pB[1]);
    int posA = int.parse(pA[2]), posB = int.parse(pB[2]);
    int cmp = secA.compareTo(secB);
    if (cmp != 0) return cmp;
    bool sqA = isPerfectSquare(shelfA);
    bool sqB = isPerfectSquare(shelfB);
    if (sqA && !sqB) return -1;
    if (!sqA && sqB) return 1;
    cmp = shelfA.compareTo(shelfB);
    if (cmp != 0) return cmp;
