@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String gridSpec) {
  final result = <int>[];
  if (gridSpec.isEmpty) return result;
  for (final row in gridSpec.split(';')) {
    if (row.isEmpty) continue;
    for (final cell in row.split('|')) {
      var count = 0;
      var mask = 0;
      for (var i = 0; i < cell.length; i++) {
        final ch = cell[i];
        var bit = 0;
        if (ch == 'N') bit = 1;
        else if (ch == 'E') bit = 2;
        else if (ch == 'S') bit = 4;
        else if (ch == 'W') bit = 8;
        if (bit != 0 && (mask & bit) == 0) {
          mask |= bit;
          count++;
        }
      }
      result.add(count);
    }
  }
  return result;
}

