import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<List<int>> grid, int startRow, int startCol, int threshold) {
  if (grid.isEmpty || grid[0].isEmpty) return {};
  int rows = grid.length;
  int cols = grid[0].length;
  if (startRow < 0 || startRow >= rows || startCol < 0 || startCol >= cols) return {};
  Set<int> visited = {};
  void dfs(int r, int c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) return;
    int idx = r * cols + c;
    if (visited.contains(idx)) return;
    if (grid[r][c] > threshold) return;
    visited.add(idx);
    dfs(r - 1, c);
    dfs(r + 1, c);
    dfs(r, c - 1);
    dfs(r, c + 1);
  }
  dfs(startRow, startCol);
  return visited;
}

