import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String recipe, double factor) {
  List<String> result = [];
  String numStr = '', rest = '';
  bool inNum = true;
  for (int i = 0; i <= recipe.length; i++) {
    String c = i < recipe.length ? recipe[i] : ';';
    if (c == ';') {
      if (numStr.isNotEmpty) {
        double q = double.parse(numStr) * factor;
        result.add('${q == q.roundToDouble() ? q.toInt() : q} $rest');
      }
      numStr = ''; rest = ''; inNum = true;
    } else if (inNum && c == ' ') {
      inNum = false;
    } else if (inNum) {
      numStr += c;
    } else {
      rest += c;
    }
  }
  return result;
}

