import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  if (args.length != 1) {
    print('Usage: dart run <script.dart> <n>');
    return;
  }

  final n = int.tryParse(args[0]);
  if (n == null || n < 0) {
    print('Please provide a non-negative integer.');
    return;
  }

  final memo = <int, int>{0: 0, 1: 1};

  int fib(int k) {
    if (memo.containsKey(k)) {
      return memo[k]!;
    }
    final value = fib(k - 1) + fib(k - 2);
    memo[k] = value;
    return value;
  }

  print('Fibonacci($n) = ${fib(n)}');
}

