import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {


  int modPow(int base, int exp, int mod) {
    int result = 1;
    base = base % mod;
    while (exp > 0) {
      if (exp & 1 == 1) {
        result = (result * base) % mod;
      }
      exp = exp >> 1;
      base = (base * base) % mod;
    }
    return result;
  }

  bool millerRabinTest(int n, int witness) {
    if (n == 2 || n == 3) return true;
    if (n < 2 || n % 2 == 0) return false;

    int d = n - 1;
    int r = 0;
    while (d % 2 == 0) {
      d ~/= 2;
      r++;
    }

    int x = modPow(witness, d, n);

    if (x == 1 || x == n - 1) return true;

    for (int i = 0; i < r - 1; i++) {
      x = (x * x) % n;
      if (x == n - 1) return true;
    }

    return false;
  }

  bool isPrime(int n, int k) {
    if (n == 2 || n == 3) return true;
    if (n < 2 || n % 2 == 0) return false;

    List<int> witnesses;
    if (n < 2047) {
      witnesses = [2];
    } else if (n < 1373653) {
      witnesses = [2, 3];
    } else if (n < 9080191) {
      witnesses = [31, 73];
    } else if (n < 25326001) {
      witnesses = [2, 3, 5];
    } else if (n < 3215031751) {
      witnesses = [2, 3, 5, 7];
    } else {

      Random rand = Random(0);
      witnesses = [];
      for (int i = 0; i < k; i++) {
        witnesses.add(2 + rand.nextInt(n - 3));
      }
    }

    for (int witness in witnesses) {
      if (!millerRabinTest(n, witness)) {
        return false;
      }
    }

    return true;
  }

