import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<List<int>> passes, int k) {
  if (k == 0) return true;
  if (passes.isEmpty) return false;
  int maxEnd = 0;
  for (var p in passes) {
    if (p[1] > maxEnd) maxEnd = p[1];
  }
  List<List<int>> ends = List.generate(maxEnd + 1, (_) => []);
  for (var p in passes) {
    ends[p[1]].add(p[0]);
  }
  List<int> dp = List.filled(maxEnd + 1, 0);
  for (int t = 0; t <= maxEnd; t++) {
    dp[t] = t > 0 ? dp[t - 1] : 0;
    for (int s in ends[t]) {
      int prev = s > 0 ? dp[s - 1] : 0;
      dp[t] = dp[t] > 1 + prev ? dp[t] : 1 + prev;
    }
  }
  return dp[maxEnd] >= k;
}

