import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  Map<int, List<int>> graph = {
    0: [2, 3],
    1: [3, 4],
    2: [3],
    3: [],
    4: [3],
    5: [0, 1]
  };

  print("Graph adjacency list:");
  graph.forEach((vertex, edges) {
    print("$vertex -> $edges");
  });

  Map<int, int> inDegree = {};
  List<int> topologicalOrder = [];
  List<int> queue = [];

  for (int vertex in graph.keys) {
    inDegree[vertex] = 0;
  }

  for (var edges in graph.values) {
    for (int vertex in edges) {
      inDegree[vertex] = (inDegree[vertex] ?? 0) + 1;
    }
  }

  for (var entry in inDegree.entries) {
    if (entry.value == 0) {
      queue.add(entry.key);
    }
  }

  while (queue.isNotEmpty) {
    int current = queue.removeAt(0);
    topologicalOrder.add(current);

    for (int neighbor in graph[current] ?? []) {
      inDegree[neighbor] = inDegree[neighbor]! - 1;
      if (inDegree[neighbor] == 0) {
        queue.add(neighbor);
      }
    }
  }

  if (topologicalOrder.length != graph.length) {
    print("\nError: Graph contains a cycle! Topological sort not possible.");
  } else {
    print("\nTopological Sort (Kahn's Algorithm): $topologicalOrder");
  }

  List<int> dfsTopologicalOrder = [];
  Set<int> visited = {};
  Set<int> recursionStack = {};
  bool hasCycle = false;

  void dfs(int vertex) {
    visited.add(vertex);
    recursionStack.add(vertex);

    for (int neighbor in graph[vertex] ?? []) {
      if (!visited.contains(neighbor)) {
        dfs(neighbor);
      } else if (recursionStack.contains(neighbor)) {
        hasCycle = true;
      }
    }

    recursionStack.remove(vertex);
    dfsTopologicalOrder.insert(0, vertex);
  }

  for (int vertex in graph.keys) {
    if (!visited.contains(vertex)) {
      dfs(vertex);
    }
  }

  if (hasCycle) {
    print("DFS detected a cycle in the graph!");
  } else {
    print("Topological Sort (DFS-based): $dfsTopologicalOrder");
  }

  print("\n--- Testing with a different DAG ---");
  Map<int, List<int>> dag2 = {
    0: [1, 2],
    1: [3],
    2: [3, 4],
    3: [4],
    4: []
  };

  print("Graph adjacency list:");
  dag2.forEach((vertex, edges) {
    print("$vertex -> $edges");
  });

  Map<int, int> inDegree2 = {};
  List<int> topologicalOrder2 = [];
  List<int> queue2 = [];

  for (int vertex in dag2.keys) {
    inDegree2[vertex] = 0;
  }

  for (var edges in dag2.values) {
    for (int vertex in edges) {
      inDegree2[vertex] = (inDegree2[vertex] ?? 0) + 1;
    }
  }

  for (var entry in inDegree2.entries) {
    if (entry.value == 0) {
      queue2.add(entry.key);
    }
  }

  while (queue2.isNotEmpty) {
    int current = queue2.removeAt(0);
    topologicalOrder2.add(current);

    for (int neighbor in dag2[current] ?? []) {
      inDegree2[neighbor] = inDegree2[neighbor]! - 1;
      if (inDegree2[neighbor] == 0) {
        queue2.add(neighbor);
      }
    }
  }

  print("Topological Sort Result: $topologicalOrder2");

  print("\n--- Testing with a cyclic graph ---");
  Map<int, List<int>> cyclicGraph = {
    0: [1],
    1: [2],
    2: [0, 3],
    3: []
  };

  print("Graph adjacency list:");
  cyclicGraph.forEach((vertex, edges) {
    print("$vertex -> $edges");
  });

  Map<int, int> inDegree3 = {};
  List<int> topologicalOrder3 = [];
  List<int> queue3 = [];

  for (int vertex in cyclicGraph.keys) {
    inDegree3[vertex] = 0;
  }

  for (var edges in cyclicGraph.values) {
    for (int vertex in edges) {
      inDegree3[vertex] = (inDegree3[vertex] ?? 0) + 1;
    }
  }

  for (var entry in inDegree3.entries) {
    if (entry.value == 0) {
      queue3.add(entry.key);
    }
  }

  while (queue3.isNotEmpty) {
    int current = queue3.removeAt(0);
    topologicalOrder3.add(current);

    for (int neighbor in cyclicGraph[current] ?? []) {
      inDegree3[neighbor] = inDegree3[neighbor]! - 1;
      if (inDegree3[neighbor] == 0) {
        queue3.add(neighbor);
      }
    }
  }

  if (topologicalOrder3.length != cyclicGraph.length) {
    print("Cycle detected! Only partial order found: $topologicalOrder3");
  } else {
    print("Topological Sort Result: $topologicalOrder3");
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final random = Random(0);
  final targetString = "HELLO WORLD";
  final populationSize = 100;
  final mutationRate = 0.01;
  final eliteSize = 20;
  final maxGenerations = 1000;

  final charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";

  String generateIndividual(int length) {
    return List.generate(length, (_) => charset[random.nextInt(charset.length)]).join();
  }

  int calculateFitness(String individual) {
    int fitness = 0;
    for (int i = 0; i < individual.length; i++) {
      if (i < targetString.length && individual[i] == targetString[i]) {
        fitness++;
      }
    }
    return fitness;
  }

  String tournamentSelection(List<Map<String, dynamic>> population) {
    final tournamentSize = 5;
    List<Map<String, dynamic>> tournament = [];

    for (int i = 0; i < tournamentSize; i++) {
      tournament.add(population[random.nextInt(population.length)]);
    }

    tournament.sort((a, b) => b['fitness'].compareTo(a['fitness']));
    return tournament[0]['individual'];
  }

  String crossover(String parent1, String parent2) {
    final crossoverPoint = random.nextInt(parent1.length);
    return parent1.substring(0, crossoverPoint) + 
           parent2.substring(crossoverPoint);
  }

  String mutate(String individual) {
    List<String> chars = individual.split('');
    for (int i = 0; i < chars.length; i++) {
      if (random.nextDouble() < mutationRate) {
        chars[i] = charset[random.nextInt(charset.length)];
      }
    }
    return chars.join();
  }

  List<Map<String, dynamic>> population = [];
  for (int i = 0; i < populationSize; i++) {
    String individual = generateIndividual(targetString.length);
    population.add({
      'individual': individual,
      'fitness': calculateFitness(individual)
    });
  }

  int generation = 0;
  bool solutionFound = false;

  while (generation < maxGenerations && !solutionFound) {

    population.sort((a, b) => b['fitness'].compareTo(a['fitness']));

    if (population[0]['fitness'] == targetString.length) {
      solutionFound = true;
      print('Solution found in generation $generation!');
      print('Best individual: ${population[0]['individual']}');
      break;
    }

    if (generation % 10 == 0) {
      print('Generation $generation:');
      print('  Best fitness: ${population[0]['fitness']}/${targetString.length}');
      print('  Best individual: ${population[0]['individual']}');
      print('  Average fitness: ${population.map((p) => p['fitness']).reduce((a, b) => a + b) / population.length}');
    }

    List<Map<String, dynamic>> newPopulation = [];

    for (int i = 0; i < eliteSize && i < population.length; i++) {
      newPopulation.add(population[i]);
    }

    while (newPopulation.length < populationSize) {

      String parent1 = tournamentSelection(population);
      String parent2 = tournamentSelection(population);

      String child = crossover(parent1, parent2);

      child = mutate(child);

      newPopulation.add({
        'individual': child,
        'fitness': calculateFitness(child)
      });
    }

    population = newPopulation;
    generation++;
  }

  if (!solutionFound) {
    print('\nMax generations reached without finding exact solution.');
    population.sort((a, b) => b['fitness'].compareTo(a['fitness']));
    print('Best result: ${population[0]['individual']}');
    print('Fitness: ${population[0]['fitness']}/${targetString.length}');
  }

  print('\n--- Final Statistics ---');
  print('Total generations: $generation');
  print('Population size: $populationSize');
  print('Mutation rate: $mutationRate');
  print('Elite size: $eliteSize');

  print('\nTop 5 individuals:');
  for (int i = 0; i < 5 && i < population.length; i++) {
    print('  ${i + 1}. ${population[i]['individual']} (fitness: ${population[i]['fitness']})');
  }
}

