void fn0() {

  List<int> numbers = [64, 34, 25, 12, 22, 11, 90, 88, 45, 50, 43, 23];

  print('Original array: $numbers');

  int n = numbers.length;

  for (int i = 0; i < n - 1; i++) {

    bool swapped = false;

    for (int j = 0; j < n - i - 1; j++) {

      if (numbers[j] > numbers[j + 1]) {

        int temp = numbers[j];
        numbers[j] = numbers[j + 1];
        numbers[j + 1] = temp;
        swapped = true;
      }
    }

    if (!swapped) {
      break;
    }
  }

  print('Sorted array: $numbers');

  bool isSorted = true;
  for (int i = 0; i < numbers.length - 1; i++) {
    if (numbers[i] > numbers[i + 1]) {
      isSorted = false;
      break;
    }
  }

  print('Array is correctly sorted: $isSorted');
}

