@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> encodedLogs) {
  List<String> result = [];
  for (String log in encodedLogs) {
    if (log.isEmpty) continue;
    String decoded = '';
    int i = 0;
    while (i < log.length) {
      String letter = log[i];
      i++;
      String countStr = '';
      while (i < log.length && log[i].codeUnitAt(0) >= 48 && log[i].codeUnitAt(0) <= 57) {
        countStr += log[i];
        i++;
      }
      int count = int.parse(countStr);
      for (int j = 0; j < count; j++) {
        decoded += letter;
      }
    }
    int checksum = 0;
    for (int k = 0; k < decoded.length; k++) {
      if (decoded[k] == 'C') {
        checksum += 1;
      } else if (decoded[k] == 'D') {
        checksum -= 1;
      }
    }
    if (checksum > 0) {
      result.add(decoded);
    }
  }
  return result;
}

