import 'dart:async';
import 'dart:convert';
enum Weather { sunny, rainy, snowy }

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  dynamic value = 42;
  var description = switch (value) {
    int v                   => 'int: $v',
    double v                => 'double: $v',
    String s when s.length > 5 => 'long string: $s',
    String s                => 'short string: $s',
    _                       => 'something else ($value)',
  };
  print('value=$value -> $description\n');

  var record = (7, 8);
  var sum = switch (record) {
    (int a, int b) => a + b,
    _              => 0,
  };
  print('record $record => sum = $sum\n');

  Weather today = Weather.rainy;
  var advice = switch (today) {
    Weather.sunny => 'Enjoy the sunshine!',
    Weather.rainy => 'Carry an umbrella.',
    Weather.snowy => 'Bundle up and stay warm.',
  };
  print('weather=$today -> $advice\n');

  var list = [1, 2, 3, 4];
  var listInfo = switch (list) {
    []                           => 'empty list',
    [int single]                 => 'one element: $single',
    [int first, ...var rest]     => 'first=$first, rest=${rest.join(", ")}',
  };
  print('list $list -> $listInfo\n');

  Map<String, int> point = {'x': 3, 'y': 4};
  var pointInfo = switch (point) {
    {'x': int x, 'y': int y} => 'point at ($x, $y)',
    _                        => 'not a 2-D point',
  };
  print('map $point -> $pointInfo');
}

