void fn0(List<String> args) {


  final int n = args.isNotEmpty ? int.tryParse(args[0]) ?? 4 : 4;
  final int k = args.length > 1 ? int.tryParse(args[1]) ?? 2 : 2;

  if (n < 0 || k < 0 || k > n) {
    print('Invalid input: ensure 0 ≤ k ≤ n and both are non-negative.');
    return;
  }

  void generate(int start, int remaining, List<int> current) {
    if (remaining == 0) {
      print(current);
      return;
    }

    for (int i = start; i <= n - remaining + 1; i++) {
      current.add(i);
      generate(i + 1, remaining - 1, current);
      current.removeLast(); 
    }
  }

  print('All $k-combinations of the set {1, 2, …, $n}:');
  generate(1, k, <int>[]);
}

