import 'dart:async';
import 'dart:convert';
class Notification {
  final int id;
  final String message;
  bool isRead;

  Notification(this.id, this.message, {this.isRead = false});

  @override
  String toString() {
    return 'Notification #$id: $message (Read: $isRead)';
  }
}

class NotificationsCenter {
  final List<Notification> _notifications = [];

  void addNotification(String message) {
    final id = _notifications.length + 1;
    _notifications.add(Notification(id, message));
    print('Added new notification: $message');
  }

  void markAsRead(int id) {
    for (var notification in _notifications) {
      if (notification.id == id) {
        notification.isRead = true;
        print('Marked notification #$id as read.');
        return;
      }
    }
    print('Notification #$id not found.');
  }

  List<Notification> getUnreadNotifications() {
    return _notifications.where((n) => !n.isRead).toList();
  }

  void displayAllNotifications() {
    print('All Notifications:');
    for (var notification in _notifications) {
      print(notification);
    }
  }

  void displayUnreadNotifications() {
    final unread = getUnreadNotifications();
    print('Unread Notifications (${unread.length}):');
    for (var notification in unread) {
      print(notification);
    }
  }
}

