import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> phaseNames, List<int> durations, List<int> queries) {
  int n = phaseNames.length;
  int cycleLength = 0;
  List<int> prefixSums = List<int>.filled(n, 0);
  for (int i = 0; i < n; i++) {
    prefixSums[i] = cycleLength;
    cycleLength += durations[i];
  }
  Map<String, int> counts = {};
  for (var name in phaseNames) {
    counts[name] = 0;
  }
  for (var t in queries) {
    int timeInCycle = t % cycleLength;
    int lo = 0;
    int hi = n - 1;
    while (lo < hi) {
      int mid = (lo + hi + 1) ~/ 2;
      if (prefixSums[mid] <= timeInCycle) {
        lo = mid;
      } else {
        hi = mid - 1;
      }
    }
    counts[phaseNames[lo]] = counts[phaseNames[lo]]! + 1;
  }
  return counts;
}

