import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<int> signalStrengths) {
  if (signalStrengths.isEmpty) return [];

  int computeGcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  List<int> absValues = signalStrengths.map((s) => s.abs()).toList();

  int gcdVal = absValues[0];
  for (int i = 1; i < absValues.length; i++) {
    gcdVal = computeGcd(gcdVal, absValues[i]);
  }

  int minAbs = absValues[0];
  for (int v in absValues) {
    if (v < minAbs) minAbs = v;
  }

  int binStart = (minAbs ~/ gcdVal) * gcdVal;

  List<String> result = [];
  for (int s in signalStrengths) {
    int absS = s.abs();
    int binIndex = (absS - binStart) ~/ gcdVal;
    int lower = binStart + binIndex * gcdVal;
    int upper = lower + gcdVal - 1;
    result.add("-$lower to -$upper dBm");
  }

  return result;
}

