import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> seatsPerRow) {
  int total = 0;
  int maxSeat = 0;
  for (int s in seatsPerRow) {
    total += s;
    if (s > maxSeat) maxSeat = s;
  }
  if (total == 0) return 0.0;

  int countUpTo(int value) {
    int count = 0;
    for (int s in seatsPerRow) {
      count += s < value ? s : value;
    }
    return count;
  }

  double kthScore(int k) {
    int lo = 1;
    int hi = maxSeat;
    while (lo < hi) {
      int mid = (lo + hi) ~/ 2;
      if (countUpTo(mid) >= k + 1) {
        hi = mid;
      } else {
        lo = mid + 1;
      }
    }
    return lo * 0.5;
  }

  if (total % 2 == 1) {
    return kthScore(total ~/ 2);
  } else {
    double a = kthScore(total ~/ 2 - 1);
    double b = kthScore(total ~/ 2);
    return (a + b) / 2.0;
  }
}

