void fn0() {

  List<int> prices = [1, 5, 8, 9, 10, 17, 17, 20, 24, 30];
  int n = prices.length;

  List<int> dp = List.filled(n + 1, 0);

  for (int length = 1; length <= n; length++) {
    int maxRevenue = 0;
    for (int cut = 1; cut <= length; cut++) {
      int currentRevenue = prices[cut - 1] + dp[length - cut];
      if (currentRevenue > maxRevenue) {
        maxRevenue = currentRevenue;
      }
    }
    dp[length] = maxRevenue;
  }

  print('Maximum revenue for rod of length $n: ${dp[n]}');
}

