import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> sortedRanks) {
  final int n = sortedRanks.length;
  final List<int> prefix = List<int>.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + sortedRanks[i];
  }
  final int total = prefix[n];

  int low = 0;
  int high = n;
  while (low < high) {
    final int mid = (low + high + 1) ~/ 2;
    if (2 * prefix[mid] <= total) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }

  int bestCut = low;
  int bestDiff = (2 * prefix[bestCut] - total).abs();
  if (low + 1 <= n) {
    final int nextDiff = (2 * prefix[low + 1] - total).abs();
    if (nextDiff < bestDiff) {
      bestCut = low + 1;
      bestDiff = nextDiff;
    }
  }

  final int leftSum = prefix[bestCut];
  final int rightSum = total - leftSum;
  return <String, int>{
    'cutIndex': bestCut,
    'leftSum': leftSum,
    'rightSum': rightSum,
    'difference': bestDiff,
  };
}

