Map<String, int> fn0(List<int> pricesInCents, int denomination) {
  int roundedUp = 0;
  int roundedDown = 0;
  int unchanged = 0;
  int totalAdjustment = 0;
  int g = 0;

  for (int price in pricesInCents) {
    int a = g;
    int b = price;
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    g = a;

    int rem = price % denomination;
    if (rem == 0) {
      unchanged++;
    } else if (2 * rem < denomination) {
      roundedDown++;
      totalAdjustment -= rem;
    } else {
      roundedUp++;
      totalAdjustment += denomination - rem;
    }
  }

  return {
    'rounded_up': roundedUp,
    'rounded_down': roundedDown,
    'unchanged': unchanged,
    'total_adjustment': totalAdjustment,
    'gcd': g,
  };
}

