@pragma('vm:entry-point')
double fn0(String morse) {
  double compute(int lo, int hi) {
    int len = hi - lo;
    if (len == 0) return 0.0;
    if (len == 1) return morse[lo] == '.' ? 0.5 : 1.0;
    int mid = lo + len ~/ 2;
    double left = compute(lo, mid);
    double right = compute(mid, hi);
    double transition = 0.0;
    if (morse[mid - 1] == '.' && morse[mid] == '-') {
      transition = 0.25;
    }
    return left * 0.5 + right * 0.5 + transition;
  }
  return compute(0, morse.length);
}

