void fn0() {

  void dfs(int u, List<List<int>> adj, List<int> disc, List<int> low, List<int> parent, int time, List<List<int>> bridges) {
    disc[u] = low[u] = time++;
    for (int v in adj[u]) {
      if (disc[v] == -1) { 
        parent[v] = u;
        dfs(v, adj, disc, low, parent, time, bridges);
        low[u] = low[u] < low[v] ? low[u] : low[v];
        if (low[v] > disc[u]) {
          bridges.add([u, v]);
        }
      } else if (v != parent[u]) {
        low[u] = low[u] < disc[v] ? low[u] : disc[v];
      }
    }
  }



  int vertices = 5;
  List<List<int>> adj = List.generate(vertices, (_) => <int>[]);

  void addEdge(int u, int v) {
    adj[u].add(v);
    adj[v].add(u);
  }

  addEdge(0, 1);
  addEdge(0, 2);
  addEdge(1, 2);
  addEdge(1, 3);
  addEdge(3, 4);

  List<int> disc = List.filled(vertices, -1);
  List<int> low = List.filled(vertices, -1);
  List<int> parent = List.filled(vertices, -1);

  List<List<int>> bridges = [];

  int time = 0;
  dfs(0, adj, disc, low, parent, time, bridges);



  print('Bridges in the graph:');
  for (var bridge in bridges) {
    print('${bridge[0]} - ${bridge[1]}');
  }
}

