bool fn0(List<int> departures, int maxGap) {



  if (maxGap <= 0) return false;
  final valid = <int>{};
  for (final m in departures) {
    if (m >= 0 && m < 1440) {
      valid.add(m);
    }
  }
  if (valid.isEmpty) return false;
  final sorted = valid.toList()..sort();
  for (var i = 1; i < sorted.length; i++) {
    if (sorted[i] - sorted[i - 1] > maxGap) {
      return false;
    }
  }
  final wrapGap = sorted.first + 1440 - sorted.last;
  return wrapGap <= maxGap;
}

