@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  String? greeting = 'Hello, Dart!';
  checkGreeting(greeting);

  greeting = null;
  checkGreeting(greeting);

  (String?, int?)? record = ('Dart', 3);
  checkRecord(record);

  record = null;
  checkRecord(record);

  record = (null, null);
  checkRecord(record);
}

void checkGreeting(String? greeting) {
  switch (greeting) {
    case null:
      print('Greeting is null.');
    case var g? when g.startsWith('Hello'):  
      print('Greeting starts with Hello: $g');
    case var g:
      print('Other greeting: $g');
  }
}

void checkRecord((String?, int?)? record) {
  switch (record) {
    case null:
      print('Record is null.');
    case (var name?, var version?) when version != null:
      print('Record with non-null name and version: $name, $version');
    case (null, var version):
      print('Record with null name and version: $version');
    case (var name, null):
      print('Record with name and null version: $name');
    default:
      print('Unhandled record case.');
  }
}

