List<String> fn0(List<String> squares) {
  Map<String, int> fileCount = {};
  List<String> valid = [];
  for (String sq in squares) {
    if (sq.length != 2) continue;
    String file = sq[0];
    String rank = sq[1];
    if (file.codeUnitAt(0) < 97 || file.codeUnitAt(0) > 104) continue;
    if (rank.codeUnitAt(0) < 49 || rank.codeUnitAt(0) > 56) continue;
    valid.add(sq);
    fileCount[file] = (fileCount[file] ?? 0) + 1;
  }
  Map<int, List<String>> freqToFiles = {};
  fileCount.forEach((f, c) {
    freqToFiles.putIfAbsent(c, () => []).add(f);
  });
  List<String> result = [];
  List<int> freqs = freqToFiles.keys.toList()..sort((a, b) => b.compareTo(a));
  for (int fr in freqs) {
    List<String> files = freqToFiles[fr]!..sort();
    for (String f in files) {
      List<String> sqs = [];
      for (String v in valid) {
        if (v[0] == f) sqs.add(v);
      }
      sqs.sort();
      result.add('$f:$fr ${sqs.join(" ")}');
    }
  }
  return result;
}

