import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> pixels) {
  int totalSetBits = 0;
  int visibleCount = 0;

  for (int p in pixels) {
    int p32 = p & 0xFFFFFFFF;
    int a = (p32 >> 24) & 0xFF;
    if (a == 0) continue;

    int r = (p32 >> 16) & 0xFF;
    int g = (p32 >> 8) & 0xFF;
    int b = p32 & 0xFF;

    int ta = ((a << 3) | (a >> 5)) & 0xFF;
    int tr = (r ^ 0xAA) & 0xFF;
    int tg = ((g >> 4) | (g << 4)) & 0xFF;
    int tb = (~b) & 0xFF;

    int transformed = (ta << 24) | (tr << 16) | (tg << 8) | tb;
    totalSetBits += _swarPopcount(transformed);
    visibleCount++;
  }

  if (visibleCount == 0) {
    return 0.0;
  }

  return totalSetBits / (visibleCount * 32.0);
}

int _swarPopcount(int n) {
  n = n & 0xFFFFFFFF;
  n = n - ((n >> 1) & 0x55555555);
  n = (n & 0x33333333) + ((n >> 2) & 0x33333333);
  n = (n + (n >> 4)) & 0x0F0F0F0F;
  n = n + (n >> 8);
  n = n + (n >> 16);
  return n & 0x3F;
}

