import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(
  List<Map<String, double>> dailyLogs,
  int minPlans,
  int maxBaseQuarterUnits,
) {
  if (dailyLogs.isEmpty) return false;

  Map<String, double> totals = {};
  for (var log in dailyLogs) {
    for (var entry in log.entries) {
      totals[entry.key] = (totals[entry.key] ?? 0.0) + entry.value;
    }
  }

  List<int> units = [];
  for (var amount in totals.values) {
    int qUnits = (amount * 4.0).round();
    if (qUnits > 0) {
      units.add(qUnits);
    }
  }

  if (units.length < 2) return false;

  int gcd = units[0];
  for (int i = 1; i < units.length; i++) {
    gcd = _gcd(gcd, units[i]);
    if (gcd == 1) break;
  }

  if (gcd < minPlans) return false;

  for (int u in units) {
    if ((u ~/ gcd) > maxBaseQuarterUnits) {
      return false;
    }
  }

  return true;
}

int _gcd(int a, int b) {
  while (b != 0) {
    int temp = a % b;
    a = b;
    b = temp;
  }
  return a;
}

