import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  bool isMatch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    List<List<bool>> dp = List.generate(n + 1, (_) => List.filled(m + 1, false));
    dp[0][0] = true;

    for (int j = 1; j <= m; j++) {
      if (pattern[j - 1] == '*') {
        dp[0][j] = dp[0][j - 1];
      }
    }

    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= m; j++) {
        if (pattern[j - 1] == '?' || pattern[j - 1] == text[i - 1]) {
          dp[i][j] = dp[i - 1][j - 1];
        } else if (pattern[j - 1] == '*') {
          dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
        }
      }
    }

    return dp[n][m];
  }

  List<Map<String, String>> tests = [
    {'text': 'abcdef', 'pattern': 'a*d*f'},
    {'text': 'abcdef', 'pattern': 'a?c*'},
    {'text': 'abcdef', 'pattern': 'a*f?'},
    {'text': 'abcdef', 'pattern': 'a*e?'},
    {'text': 'abcdef', 'pattern': '*'},
    {'text': 'abcdef', 'pattern': 'a?b?c?d?e?f?'},
    {'text': 'abcdef', 'pattern': 'a*c?'},
    {'text': 'abcdef', 'pattern': 'a*d?g'},
    {'text': '', 'pattern': '*'},
    {'text': '', 'pattern': '?'},
