import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> amounts, List<int> categories) {
  if (amounts.isEmpty || categories.isEmpty) return false;
  if (amounts.length != categories.length) return false;

  Map<int, List<int>> groups = {};
  for (int i = 0; i < amounts.length; i++) {
    if (amounts[i] <= 0) return false;
    groups.putIfAbsent(categories[i], () => []).add(amounts[i]);
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  int lcmAll = 1;
  int totalSum = 0;

  for (var entry in groups.entries) {
    int g = entry.value[0];
    for (int i = 1; i < entry.value.length; i++) {
      g = gcd(g, entry.value[i]);
    }
    lcmAll = (lcmAll * g) ~/ gcd(lcmAll, g);
    for (var v in entry.value) {
      totalSum += v;
    }
  }

  return totalSum % lcmAll == 0;
}

