@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<String> events) {
  int balance = 0;
  List<int> history = [];

  for (String event in events) {
    if (event.startsWith('ADD:')) {
      int change = int.parse(event.substring(4));
      history.add(balance);
      balance += change;

      if (balance < 0) {
        return false;
      }
    } else if (event == 'ROUND') {
      history.add(balance);

      int remainder = balance % 5;
      if (remainder >= 3) {
        balance += 5 - remainder;
      } else {
        balance -= remainder;
      }

      if ((balance - history.last).abs() > 2) {
        return false;
      }
    } else if (event == 'UNDO') {
      if (history.isEmpty) {
        return false;
      }

      balance = history.removeLast();
    } else {
      return false;
    }
  }

  return balance % 5 == 0;
}

