import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> prices = [1, 5, 8, 9, 10, 17, 17, 20];
  int n = prices.length;

  List<int> dp = List.filled(n + 1, 0);

  for (int i = 1; i <= n; i++) {
    int maxVal = -1;
    for (int j = 0; j < i; j++) {
      maxVal = maxVal > (prices[j] + dp[i - j - 1])
          ? maxVal
          : (prices[j] + dp[i - j - 1]);
    }
    dp[i] = maxVal;
  }

  print('Rod lengths: 1 to $n');
  print('Prices: $prices');
  print('Maximum obtainable value for rod of length $n: ${dp[n]}');
  print('DP Table: ${dp.sublist(1)}');
}

