import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> bucketCounts, int targetSum) {
  Set<int> result = {};
  if (bucketCounts.isEmpty || targetSum <= 0) return result;

  int left = 0;
  int currentSum = 0;

  for (int right = 0; right < bucketCounts.length; right++) {
    currentSum += bucketCounts[right];

    while (currentSum > targetSum && left <= right) {
      currentSum -= bucketCounts[left];
      left++;
    }

    if (currentSum == targetSum) {
      result.add(right - left + 1);
      currentSum -= bucketCounts[left];
      left++;
    }
  }

  return result;
}

