@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String encoded, int shift) {



  final counts = <int, int>{};
  const suits = 'CDHS';
  String unshift(String ch) {
    final code = ch.codeUnitAt(0) - 65;
    final orig = ((code - shift) % 26 + 26) % 26;
    return String.fromCharCode(65 + orig);
  }
  var i = 0;
  while (i < encoded.length) {
    var count = 0;
    while (i < encoded.length &&
        encoded.codeUnitAt(i) >= 48 &&
        encoded.codeUnitAt(i) <= 57) {
      count = count * 10 + (encoded.codeUnitAt(i) - 48);
      i++;
    }
    if (i + 1 >= encoded.length) break;
    final rankCh = unshift(encoded[i]);
    final suitCh = unshift(encoded[i + 1]);
    i += 2;
    final rankIdx = rankCh.codeUnitAt(0) - 65;
    final suitIdx = suits.indexOf(suitCh);
    if (rankIdx < 0 || rankIdx > 12 || suitIdx < 0) continue;
    final cardIdx = suitIdx * 13 + rankIdx;
    counts[cardIdx] = (counts[cardIdx] ?? 0) + count;
  }
  final result = <int>{};
  counts.forEach((card, c) {
    if (c >= 2) result.add(card);
  });
  return result;
}

