import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> readings) {
  if (readings.isEmpty) return {"maxLength": 0, "endingHeight": 0};
  Map<int, int> dp = {};
  int maxLen = 0;
  int bestHeight = readings[0];
  for (int h in readings) {
    int bestPrev = 0;
    for (int prevH in [h - 1, h, h + 1]) {
      if (dp.containsKey(prevH)) {
        int val = dp[prevH]!;
        if (val > bestPrev) bestPrev = val;
      }
    }
    int curLen = bestPrev + 1;
    dp[h] = curLen;
    if (curLen > maxLen) {
      maxLen = curLen;
      bestHeight = h;
    }
  }
  return {"maxLength": maxLen, "endingHeight": bestHeight};
}

