import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final Map<int, List<int>> graph = {
    0: [1],
    1: [2, 3],
    2: [0],
    3: [4],
    4: [],
  };

  final Set<int> visited = {};
  final List<int> order = [];

  void dfs1(int u) {
    visited.add(u);
    for (final v in graph[u] ?? []) {
      if (!visited.contains(v)) {
        dfs1(v);
      }
    }
    order.add(u);
  }

  for (final node in graph.keys) {
    if (!visited.contains(node)) {
      dfs1(node);
    }
  }

  final Map<int, List<int>> reversed = {};
  for (final u in graph.keys) {
    reversed[u] = [];
  }
  for (final u in graph.keys) {
    for (final v in graph[u] ?? []) {
      reversed[v] ??= [];
      reversed[v]!.add(u);
    }
  }

  visited.clear();
  final List<List<int>> sccs = [];

  void dfs2(int u, List<int> component) {
    visited.add(u);
    component.add(u);
    for (final v in reversed[u] ?? []) {
      if (!visited.contains(v)) {
        dfs2(v, component);
      }
    }
  }

  for (final u in order.reversed) {
    if (!visited.contains(u)) {
      final List<int> component = [];
      dfs2(u, component);
      sccs.add(component);
    }
  }

  print('Strongly Connected Components:');
  for (final component in sccs) {
    print(component);
  }
}

