import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(String dna, int startDay, int endDay) {
  final Map<String, int> result = {'A': 0, 'T': 0, 'C': 0, 'G': 0};
  if (startDay >= endDay || dna.isEmpty) return result;

  int countMultiples(int n, int k) {
    if (n <= 0) return 0;
    return (n - 1) ~/ k + 1;
  }

  for (int i = 0; i < dna.length; i++) {
    final String base = dna[i];
    if (!result.containsKey(base)) continue;
    final int cycle = (i % 4) + 2;
    final int ticks = countMultiples(endDay, cycle) - countMultiples(startDay, cycle);
    result[base] = result[base]! + ticks;
  }

  return result;
}

