import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String row, List<int> parties) {
  List<String> results = [];
  List<String> seats = row.split('');
  int n = seats.length;

  void backtrack(int partyIndex) {
    if (partyIndex == parties.length) {
      results.add(seats.join(''));
      return;
    }
    int size = parties[partyIndex];
    String label = String.fromCharCode(65 + partyIndex);
    for (int start = 0; start <= n - size; start++) {
      bool ok = true;
      for (int i = start; i < start + size; i++) {
        if (seats[i] != '.') {
          ok = false;
          break;
        }
      }
      if (!ok) continue;
      if (start > 0) {
        int c = seats[start - 1].codeUnitAt(0);
        if (c >= 65 && c <= 90) continue;
      }
      if (start + size < n) {
        int c = seats[start + size].codeUnitAt(0);
        if (c >= 65 && c <= 90) continue;
      }
      for (int i = start; i < start + size; i++) {
        seats[i] = label;
      }
      backtrack(partyIndex + 1);
      for (int i = start; i < start + size; i++) {
        seats[i] = '.';
      }
    }
  }

  backtrack(0);
  results.sort();
  return results;
}

