int fn0(List<int> x1, List<int> y1, List<int> x2, List<int> y2, Map<String, int> severityScores) {
  int totalScore = 0;
  int n = x1.length;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      int overlapX1 = x1[i] > x1[j] ? x1[i] : x1[j];
      int overlapY1 = y1[i] > y1[j] ? y1[i] : y1[j];
      int overlapX2 = x2[i] < x2[j] ? x2[i] : x2[j];
      int overlapY2 = y2[i] < y2[j] ? y2[i] : y2[j];
      if (overlapX1 < overlapX2 && overlapY1 < overlapY2) {
        totalScore += (severityScores['INFO'] ?? 0) + (severityScores['WARN'] ?? 0) + (severityScores['ERROR'] ?? 0);
      }
    }
  }
  return totalScore;
}

