import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String log) {
  if (log.isEmpty) return false;
  List<String> entries = log.split(';');
  List<double> heights = [];
  for (int i = 0; i < entries.length; i++) {
    List<String> parts = entries[i].split(':');
    if (parts.length != 2) return false;
    int? seq = int.tryParse(parts[0]);
    if (seq == null || seq != i + 1) return false;
    double? h = double.tryParse(parts[1]);
    if (h == null) return false;
    heights.add(h);
  }
  if (heights.length < 2) return true;
  for (int i = 0; i < heights.length - 1; i++) {
    if (heights[i] == heights[i + 1]) return false;
  }
  if (heights.length < 3) return true;
  for (int i = 0; i < heights.length - 2; i++) {
    bool rising = heights[i] < heights[i + 1] && heights[i + 1] < heights[i + 2];
    bool falling = heights[i] > heights[i + 1] && heights[i + 1] > heights[i + 2];
    if (rising || falling) return false;
  }
  return true;
}

