bool fn0(List<int> deck, int k, int lo, int hi) {
  if (k < 2 || deck.length < k || lo > hi) return false;
  int n = deck.length;
  int halfK = k ~/ 2;
  bool oddK = k % 2 == 1;

  int init = 0;
  int left = 0;
  int right = k - 1;
  for (int i = 0; i < halfK; i++) {
    int s = deck[left + i] + deck[right - i];
    if (s >= lo && s <= hi) init++;
  }
  if (init == halfK) return true;

  for (int start = 1; start <= n - k; start++) {
    int oldLeft = start - 1;
    int oldRight = start + k - 2;
    int newLeft = start + halfK - 1;
    int newRight = start + k - halfK;

    int oldPairSum = deck[oldLeft] + deck[oldRight];
    if (oldPairSum >= lo && oldPairSum <= hi) init--;

    int newPairSum = deck[newLeft] + deck[newRight];
    if (newPairSum >= lo && newPairSum <= hi) init++;

    if (oddK) {
      int oldMidIdx = oldLeft + halfK;
      int newMidIdx = start + halfK;
      if (oldMidIdx == newMidIdx) {

      } else {
        int oldMidPair = deck[oldMidIdx] + deck[oldRight - (oldMidIdx - oldLeft)];
        int newMidPair = deck[newMidIdx] + deck[oldRight - (newMidIdx - oldLeft)];
        if (oldMidPair >= lo && oldMidPair <= hi) init++;
        if (newMidPair >= lo && newMidPair <= hi) init--;
      }
    }

    if (init == halfK) return true;
  }
  return false;
}

