List<String> fn0(List<List<int>> ledgerZones, List<int> queryZone) {
  List<String> results = [];
  int qMinX = queryZone[0], qMinY = queryZone[1], qMaxX = queryZone[2], qMaxY = queryZone[3];
  for (List<int> z in ledgerZones) {
    int w = (z[3] < qMaxX ? z[3] : qMaxX) - (z[1] > qMinX ? z[1] : qMinX);
    int h = (z[4] < qMaxY ? z[4] : qMaxY) - (z[2] > qMinY ? z[2] : qMinY);
    if (w > 0 && h > 0) results.add("${z[0]}:${w * h}");
  }
  results.sort((a, b) {
    int sepA = a.indexOf(':'), sepB = b.indexOf(':');
    int areaA = int.parse(a.substring(sepA + 1)), areaB = int.parse(b.substring(sepB + 1));
    if (areaA != areaB) return areaB.compareTo(areaA);
    return int.parse(a.substring(0, sepA)).compareTo(int.parse(b.substring(0, sepB)));
  });
  return results;
}

