import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<String> playlist) {
  if (playlist.isEmpty) return 'None';

  Map<String, int> artistCounts = {};
  for (String track in playlist) {
    int separatorIndex = track.indexOf(' - ');
    String artist = separatorIndex >= 0 ? track.substring(0, separatorIndex) : 'Unknown';
    if (artist.isEmpty) artist = 'Unknown';
    artistCounts[artist] = (artistCounts[artist] ?? 0) + 1;
  }

  String topArtist = '';
  int maxCount = 0;

  for (var entry in artistCounts.entries) {
    if (entry.value > maxCount) {
      maxCount = entry.value;
      topArtist = entry.key;
    } else if (entry.value == maxCount && entry.key.compareTo(topArtist) < 0) {
      topArtist = entry.key;
    }
  }

  return topArtist.isEmpty ? 'None' : topArtist;
}

