import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(int participants) {
  if (participants < 1) {
    return <String, int>{
      'rounds': 0, 'totalMatches': 0, 'byes': 0,
      'bracketSize': 0, 'firstRoundMatches': 0, 'isPowerOfTwo': 0,
    };
  }
  int bracketSize = 1;
  int rounds = 0;
  while (bracketSize < participants) {
    bracketSize *= 2;
    rounds += 1;
  }
  int byes = bracketSize - participants;
  int firstRoundMatches = (byes == 0)
      ? bracketSize ~/ 2
      : (participants - byes) ~/ 2;
  return <String, int>{
    'rounds': rounds,
    'totalMatches': participants - 1,
    'byes': byes,
    'bracketSize': bracketSize,
    'firstRoundMatches': firstRoundMatches,
    'isPowerOfTwo': (byes == 0) ? 1 : 0,
  };
}

