@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> log) {




  final schedule = <int>[];
  final history = <List<int>>[]; 
  var ignored = 0;
  for (final entry in log) {
    if (entry.startsWith('ADD ')) {
      final m = int.parse(entry.substring(4));
      schedule.add(m);
      history.add([0, m]);
    } else if (entry == 'CANCEL') {
      if (schedule.isEmpty) {
        ignored++;
      } else {
        final m = schedule.removeLast();
        history.add([1, m]);
      }
    } else if (entry == 'UNDO') {
      if (history.isEmpty) {
        ignored++;
      } else {
        final op = history.removeLast();
        if (op[0] == 0) {
          schedule.removeLast();
        } else {
          schedule.add(op[1]);
        }
      }
    } else {
      ignored++;
    }
  }
  var sum = 0;
  var minVal = -1;
  var maxVal = -1;
  for (final m in schedule) {
    sum += m;
    if (minVal == -1 || m < minVal) minVal = m;
    if (maxVal == -1 || m > maxVal) maxVal = m;
  }
  return {
    'count': schedule.length,
    'sum': sum,
    'min': minVal,
    'max': maxVal,
    'ignored': ignored,
  };
}

