@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<double> phaseDurations, double greenSecondsNeeded) {
  if (greenSecondsNeeded <= 0.0) return 0.0;
  double cycleLength = 0.0;
  List<double> greenSegments = [];
  for (int i = 0; i < phaseDurations.length; i++) {
    cycleLength += phaseDurations[i];
    if (i % 2 == 0) greenSegments.add(phaseDurations[i]);
  }
  double greenPerCycle = 0.0;
  for (int i = 0; i < greenSegments.length; i++) {
    greenPerCycle += greenSegments[i];
  }
  double low = 0.0;
  double high = ((greenSecondsNeeded / greenPerCycle) + 1.0) * cycleLength;
  for (int iter = 0; iter < 60; iter++) {
    double mid = (low + high) / 2.0;
    double totalGreen = 0.0;
    double remaining = mid;
    int phaseIdx = 0;
    while (remaining > 0.0) {
      double phaseLen = phaseDurations[phaseIdx % phaseDurations.length];
      double consume = remaining < phaseLen ? remaining : phaseLen;
      if (phaseIdx % 2 == 0) {
        totalGreen += consume;
      }
      remaining -= consume;
      phaseIdx++;
    }
    if (totalGreen >= greenSecondsNeeded) {
      high = mid;
    } else {
      low = mid;
    }
  }
  return high;
}

