import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> parents, List<int> amounts) {
  int n = parents.length;
  Map<String, int> result = {};
  Map<int, List<int>> children = {};
  List<int> roots = [];
  for (int i = 0; i < n; i++) {
    if (parents[i] == -1) {
      roots.add(i);
    } else {
      children.putIfAbsent(parents[i], () => <int>[]).add(i);
    }
  }
  int dfs(int node) {
    int total = amounts[node];
    for (int child in (children[node] ?? <int>[])) {
      total += dfs(child);
    }
    result['acct_$node'] = total;
    return total;
  }
  for (int root in roots) {
    dfs(root);
  }
  return result;
}

