Map<String, int> fn0(Map<String, int> mainStock, int levels) {
  if (levels <= 0 || mainStock.isEmpty) return {};
  if (levels == 1) return Map<String, int>.from(mainStock);
  Map<String, int> result = {};
  mainStock.forEach((key, value) {
    result[key] = value * levels;
  });
  Map<String, int> sub = fn0(mainStock, levels - 1);
  sub.forEach((k, v) {
    result[k] = (result[k] ?? 0) + v;
  });
  return result;
}

