int fn0(String encodedEdits) {
  if (encodedEdits.isEmpty) return 0;
  int checksum = 0;
  int index = 0;
  int pos = 0;
  while (index < encodedEdits.length) {
    String type = encodedEdits[index];
    if (!'DIS'.contains(type)) return -1;
    index++;
    int count = 0;
    while (index < encodedEdits.length) {
      int code = encodedEdits[index].codeUnitAt(0);
      if (code < 48 || code > 57) break;
      count = count * 10 + (code - 48);
      index++;
    }
    if (count == 0) count = 1;
    int typeVal = type == 'D' ? 4 : (type == 'I' ? 5 : 6);
    checksum += typeVal * count * (pos + 1);
    pos += count;
  }
  return checksum;
}

