import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {


  bool matchWildcard(String pattern, String text) {
    int m = pattern.length;
    int n = text.length;

    List<List<bool>> dp = List.generate(
      m + 1,
      (_) => List.filled(n + 1, false),
    );

    dp[0][0] = true;

    for (int i = 1; i <= m; i++) {
      if (pattern[i - 1] == '*') {
        dp[i][0] = dp[i - 1][0];
      }
    }

    for (int i = 1; i <= m; i++) {
      for (int j = 1; j <= n; j++) {
        if (pattern[i - 1] == '*') {

          dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
        } else if (pattern[i - 1] == '?' || pattern[i - 1] == text[j - 1]) {

          dp[i][j] = dp[i - 1][j - 1];
        }
      }
    }

    return dp[m][n];
  }

  List<Map<String, dynamic>> testCases = [
    {'pattern': 'a*b', 'text': 'axxxb', 'expected': true},
    {'pattern': 'a*b', 'text': 'ab', 'expected': true},
    {'pattern': 'a?b', 'text': 'axb', 'expected': true},
    {'pattern': 'a?b', 'text': 'ab', 'expected': false},
    {'pattern': '*', 'text': 'anything', 'expected': true},
    {'pattern': 'a*', 'text': 'abc', 'expected': true},
    {'pattern': '*b', 'text': 'xyzb', 'expected': true},
    {'pattern': 'a?c', 'text': 'abc', 'expected': true},
    {'pattern': 'a*c', 'text': 'ac', 'expected': true},
    {'pattern': 'a*c', 'text': 'abbc', 'expected': true},
    {'pattern': 'a*c', 'text': 'abd', 'expected': false},
    {'pattern': '?*', 'text': 'x', 'expected': true},
    {'pattern': '?*', 'text': '', 'expected': false},
    {'pattern': 'h*llo', 'text': 'hello', 'expected': true},
    {'pattern': 'h*llo', 'text': 'heeeello', 'expected': true},
    {'pattern': 'h?llo', 'text': 'hello', 'expected': true},
    {'pattern': 'h?llo', 'text': 'hallo', 'expected': true},
    {'pattern': 'h?llo', 'text': 'hllo', 'expected': false},
    {'pattern': '*world*', 'text': 'hello world!', 'expected': true},
    {'pattern': '*.txt', 'text': 'file.txt', 'expected': true},
    {'pattern': '*.txt', 'text': 'file.doc', 'expected': false},
    {'pattern': 'test*.txt', 'text': 'test123.txt', 'expected': true},
    {'pattern': 'a*b*c', 'text': 'abc', 'expected': true},
    {'pattern': 'a*b*c', 'text': 'aXbYc', 'expected': true},
    {'pattern': 'a*b*c', 'text': 'aXbYcZ', 'expected': false},
  ];

  print('Wildcard Pattern Matching Tests');
  print('================================');
  print('Wildcards: * (matches 0 or more chars), ? (matches exactly 1 char)\n');

  int passed = 0;
  int failed = 0;

  for (var test in testCases) {
    String pattern = test['pattern'];
    String text = test['text'];
    bool expected = test['expected'];
    bool result = matchWildcard(pattern, text);

    String status = result == expected ? '✓ PASS' : '✗ FAIL';
    if (result == expected) {
      passed++;
    } else {
      failed++;
    }

    print('$status: Pattern "$pattern" ${result ? 'matches' : 'does not match'} "$text"');
    if (result != expected) {
      print('       Expected: $expected, Got: $result');
    }
  }

  print('\n================================');
  print('Test Results: $passed passed, $failed failed');

  print('\n================================');
  print('File Pattern Examples:');

  List<String> files = [
    'document.txt',
    'image.png',
    'data.csv',
    'report_2023.txt',
    'backup.tar.gz',
    'test_file.txt',
    'README.md',
  ];

  String searchPattern = '*.txt';
  print('\nSearching for pattern: "$searchPattern"');
  print('Matching files:');
  for (String file in files) {
    if (matchWildcard(searchPattern, file)) {
      print('  - $file');
    }
  }

  searchPattern = '*test*';
  print('\nSearching for pattern: "$searchPattern"');
  print('Matching files:');
  for (String file in files) {
    if (matchWildcard(searchPattern, file)) {
      print('  - $file');
    }
  }

  searchPattern = '????.???';
  print('\nSearching for pattern: "$searchPattern" (4 chars + . + 3 chars)');
  print('Matching files:');
  for (String file in files) {
    if (matchWildcard(searchPattern, file)) {
      print('  - $file');
    }
  }
}

