import 'dart:ffi' as ffi;
import 'dart:io' show Platform;
import 'dart:math' as math;

typedef SinFunc = ffi.Double Function(ffi.Double);
typedef Sin = double Function(double);

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  ffi.DynamicLibrary dylib;
  if (Platform.isLinux) {
    dylib = ffi.DynamicLibrary.open('libm.so.6');
  } else if (Platform.isMacOS) {
    dylib = ffi.DynamicLibrary.open('libSystem.dylib');
  } else if (Platform.isWindows) {
    dylib = ffi.DynamicLibrary.open('msvcrt.dll');
  } else {
    print('Unsupported platform');
    return;
  }

  final sinPointer = dylib.lookup<ffi.NativeFunction<SinFunc>>('sin');
  final sin = sinPointer.asFunction<Sin>();

  final input = math.pi / 2;
  final result = sin(input);
  print('Native sin($input) = $result'); 

  print('Dart sin($input) = ${math.sin(input)}');
}

