import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<int> moisture, int gridWidth, List<String> commands) {
  List<int> grid = List<int>.from(moisture);
  List<String> logs = [];
  List<String> undoStack = [];
  for (String cmd in commands) {
    List<String> parts = cmd.split(' ');
    String action = parts[0];
    if (action == 'S') {
      logs.add(grid.join('|'));
    } else if (action == 'U') {
      if (undoStack.isNotEmpty) {
        String entry = undoStack.removeLast();
        int spaceIdx = entry.indexOf(' ');
        int idx = int.parse(entry.substring(0, spaceIdx));
        int delta = int.parse(entry.substring(spaceIdx + 1));
        grid[idx] -= delta;
      }
    } else if (action == 'W') {
      int r = int.parse(parts[1]);
      int c = int.parse(parts[2]);
      int v = int.parse(parts[3]);
      int idx = r * gridWidth + c;
      if (idx >= 0 && idx < grid.length) {
        grid[idx] += v;
        undoStack.add('$idx $v');
      }
    } else if (action == 'D') {
      int r = int.parse(parts[1]);
      int c = int.parse(parts[2]);
      int v = int.parse(parts[3]);
      int idx = r * gridWidth + c;
      if (idx >= 0 && idx < grid.length) {
        int actual = grid[idx] < v ? grid[idx] : v;
        grid[idx] -= actual;
        undoStack.add('$idx ${-actual}');
      }
    }
  }
  return logs;
}

