  var urgentPriorities = Priority.values.where((p) => p.requiresNotification).toList();
  print('Priorities requiring notification: ${urgentPriorities.map((p) => p.name).join(', ')}');
}

class RoleInfo {
  final String description;
  final int level;
  const RoleInfo(this.description, this.level);
}

enum UserRole {
  @RoleInfo('System Administrator', 100)
  admin,

  @RoleInfo('Content Moderator', 50)
  moderator,

  @RoleInfo('Regular User', 10)
  user,

  @RoleInfo('Guest User', 1)
  guest;

  String get displayName {
    switch (this) {
      case UserRole.admin:
        return 'Administrator';
      case UserRole.moderator:
        return 'Moderator';
      case UserRole.user:
        return 'User';
      case UserRole.guest:
        return 'Guest';
    }
  }

  int get permissionLevel {
    switch (this) {
      case UserRole.admin:
        return 100;
      case UserRole.moderator:
        return 50;
      case UserRole.user:
        return 10;
      case UserRole.guest:
        return 1;
    }
  }

  String get description {
    switch (this) {
      case UserRole.admin:
        return 'Has full system access and can manage all users';
      case UserRole.moderator:
        return 'Can moderate content and manage regular users';
      case UserRole.user:
        return 'Standard user with basic permissions';
      case UserRole.guest:
        return 'Limited access, read-only permissions';
    }
  }

  bool get hasAdminAccess => this == UserRole.admin || this == UserRole.moderator;
}

enum Status {
  success(200, 'Operation successful'),
  created(201, 'Resource created'),
  badRequest(400, 'Invalid request'),
  unauthorized(401, 'Authentication required'),
  forbidden(403, 'Access denied'),
  notFound(404, 'Resource not found'),
  serverError(500, 'Internal server error');

  final int code;
  final String message;

  const Status(this.code, this.message);

  bool get isSuccess => code >= 200 && code < 300;
  bool get isError => code >= 400;
  bool get isClientError => code >= 400 && code < 500;
  bool get isServerError => code >= 500;
}

enum Priority {
  critical(1, '#FF0000', '🔴'),
  high(2, '#FF8800', '🟠'),
  medium(3, '#FFFF00', '🟡'),
  low(4, '#00FF00', '🟢'),
  trivial(5, '#0088FF', '🔵');

  final int value;
  final String color;
  final String icon;

  const Priority(this.value, this.color, this.icon);

  bool get requiresNotification => value <= 2;

  Duration get responseTime {
    switch (this) {
      case Priority.critical:
        return Duration(hours: 1);
      case Priority.high:
        return Duration(hours: 4);
      case Priority.medium:
        return Duration(days: 1);
      case Priority.low:
        return Duration(days: 3);
      case Priority.trivial:
        return Duration(days: 7);
    }
  }
}

