double fn0(List<int> counts, int threshold) {

  int lo = 0;
  int hi = counts.length;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (counts[mid] >= threshold) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  return lo < counts.length ? lo.toDouble() : -1.0;
}

