double fn0(List<int> operations, int numBuckets) {
  List<int> stack = [];
  for (int op in operations) {
    if (op > 0) {
      stack.add(op);
    } else if (op == 0 && stack.isNotEmpty) {
      stack.removeLast();
    }
  }
  List<double> counts = List.filled(numBuckets, 0.0);
  for (int bucket in stack) {
    counts[bucket - 1] += 1.0;
  }
  double total = 0.0;
  for (double c in counts) {
    total += c;
  }
  return total / numBuckets;
}

