String fn0(List<int> strengths) {
  Map<String, int> bins = {'weak': 0, 'medium': 0, 'strong': 0};
  for (int s in strengths) {
    if (s >= -50) {
      bins['strong'] = bins['strong']! + 1;
    } else if (s >= -70) {
      bins['medium'] = bins['medium']! + 1;
    } else {
      bins['weak'] = bins['weak']! + 1;
    }
  }
  List<String> parts = [];
  for (String key in ['weak', 'medium', 'strong']) {
    parts.add(key + ':' + bins[key].toString());
  }
  return parts.join(',');
}

