import 'dart:async';
import 'dart:convert';
abstract class Option<T> {

  R map<R>(R Function(T) onSome, R Function() onNone) {
    if (this is Some<T>) {
      return onSome((this as Some<T>).value);
    } else {
      return onNone();
    }
  }
}

class Some<T> extends Option<T> {
  final T value;
  Some(this.value);

  @override
  String toString() => 'Some($value)';
}

class None<T> extends Option<T> {
  @override
  String toString() => 'None';
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  Option<int> someValue = Some<int>(42);
  Option<int> noneValue = None<int>();

  String resultSome = someValue.map<String>((val) => 'Value: $val', () => 'No value');
  String resultNone = noneValue.map<String>((val) => 'Value: $val', () => 'No value');

  print('Some example: $someValue');
  print('Mapped Some: $resultSome');
  print('None example: $noneValue');
  print('Mapped None: $resultNone');

  Option<String> someString = Some<String>('Hello');
  print('String Some: $someString');
}

