import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  var userProfile = {
    'username': 'player123',
    'points': 0,
    'level': 1,
    'badges': <String>[],
    'achievements': <String, bool>{
      'first_login': false,
      'reach_100_points': false,
      'reach_500_points': false,
      'reach_1000_points': false,
      'complete_5_tasks': false,
      'complete_10_tasks': false,
      'daily_streak_3': false,
      'daily_streak_7': false,
      'level_5_reached': false,
      'level_10_reached': false,
    },
    'tasks_completed': 0,
    'daily_streak': 0,
    'last_login': DateTime.now().subtract(Duration(days: 1)),
  };

  var badges = {
    'newcomer': {'name': 'Newcomer', 'description': 'Welcome to the app!', 'icon': '🌟'},
    'centurion': {'name': 'Centurion', 'description': 'Reached 100 points', 'icon': '💯'},
    'champion': {'name': 'Champion', 'description': 'Reached 500 points', 'icon': '🏆'},
    'legend': {'name': 'Legend', 'description': 'Reached 1000 points', 'icon': '👑'},
    'task_rookie': {'name': 'Task Rookie', 'description': 'Completed 5 tasks', 'icon': '📋'},
    'task_master': {'name': 'Task Master', 'description': 'Completed 10 tasks', 'icon': '📚'},
    'streak_starter': {'name': 'Streak Starter', 'description': '3 day streak', 'icon': '🔥'},
    'streak_keeper': {'name': 'Streak Keeper', 'description': '7 day streak', 'icon': '💥'},
    'level_5': {'name': 'Rising Star', 'description': 'Reached level 5', 'icon': '⭐'},
    'level_10': {'name': 'Elite Player', 'description': 'Reached level 10', 'icon': '🌠'},
  };

  var pointValues = {
    'daily_login': 10,
    'complete_task': 25,
    'streak_bonus': 5,
    'achievement_unlock': 50,
  };

  void addPoints(int points, String reason) {
    userProfile['points'] = (userProfile['points'] as int) + points;
    print('🎯 +$points points for $reason! Total: ${userProfile['points']} points');

    int currentLevel = userProfile['level'] as int;
    int newLevel = ((userProfile['points'] as int) / 100).floor() + 1;

    if (newLevel > currentLevel) {
      userProfile['level'] = newLevel;
      print('🎉 LEVEL UP! You are now level $newLevel!');
      addPoints(pointValues['achievement_unlock']!, 'leveling up');
    }
  }

  void awardBadge(String badgeId) {
    var userBadges = userProfile['badges'] as List<String>;
    if (!userBadges.contains(badgeId)) {
      userBadges.add(badgeId);
      var badge = badges[badgeId]!;
      print('🏅 NEW BADGE UNLOCKED: ${badge['icon']} ${badge['name']} - ${badge['description']}');
      addPoints(pointValues['achievement_unlock']!, 'unlocking a badge');
    }
  }

  void checkAchievements() {
    var achievements = userProfile['achievements'] as Map<String, bool>;
    var points = userProfile['points'] as int;
    var tasksCompleted = userProfile['tasks_completed'] as int;
    var dailyStreak = userProfile['daily_streak'] as int;
    var level = userProfile['level'] as int;

    if (!achievements['first_login']!) {
      achievements['first_login'] = true;
      awardBadge('newcomer');
    }

    if (points >= 100 && !achievements['reach_100_points']!) {
      achievements['reach_100_points'] = true;
      awardBadge('centurion');
    }

    if (points >= 500 && !achievements['reach_500_points']!) {
      achievements['reach_500_points'] = true;
      awardBadge('champion');
    }

    if (points >= 1000 && !achievements['reach_1000_points']!) {
      achievements['reach_1000_points'] = true;
      awardBadge('legend');
    }

    if (tasksCompleted >= 5 && !achievements['complete_5_tasks']!) {
      achievements['complete_5_tasks'] = true;
      awardBadge('task_rookie');
    }

    if (tasksCompleted >= 10 && !achievements['complete_10_tasks']!) {
      achievements['complete_10_tasks'] = true;
      awardBadge('task_master');
    }

    if (dailyStreak >= 3 && !achievements['daily_streak_3']!) {
      achievements['daily_streak_3'] = true;
      awardBadge('streak_starter');
    }

    if (dailyStreak >= 7 && !achievements['daily_streak_7']!) {
      achievements['daily_streak_7'] = true;
      awardBadge('streak_keeper');
    }

    if (level >= 5 && !achievements['level_5_reached']!) {
      achievements['level_5_reached'] = true;
      awardBadge('level_5');
    }

    if (level >= 10 && !achievements['level_10_reached']!) {
      achievements['level_10_reached'] = true;
      awardBadge('level_10');
    }
  }

  void handleDailyLogin() {
    var lastLogin = userProfile['last_login'] as DateTime;
    var now = DateTime.now();
    var daysSinceLastLogin = now.difference(lastLogin).inDays;

    print('\n📅 Daily Login Check...');

    if (daysSinceLastLogin >= 1) {
      addPoints(pointValues['daily_login']!, 'daily login');

      if (daysSinceLastLogin == 1) {
        userProfile['daily_streak'] = (userProfile['daily_streak'] as int) + 1;
        int streakBonus = (userProfile['daily_streak'] as int) * pointValues['streak_bonus']!;
        addPoints(streakBonus, 'daily streak bonus (${userProfile['daily_streak']} days)');
      } else {
        userProfile['daily_streak'] = 1;
        print('❌ Streak broken! Starting over at 1 day.');
      }

      userProfile['last_login'] = now;
    } else {
      print('✅ Already logged in today!');
    }
  }

  void completeTask(String taskName) {
    print('\n📝 Completing task: $taskName');
    userProfile['tasks_completed'] = (userProfile['tasks_completed'] as int) + 1;
    addPoints(pointValues['complete_task']!, 'completing a task');
    checkAchievements();
  }

  void displayStats() {
    print('\n' + '='*50);
    print('👤 USER PROFILE: ${userProfile['username']}');
    print('='*50);
    print('📊 Level: ${userProfile['level']}');
    print('💰 Points: ${userProfile['points']}');
    print('🔥 Daily Streak: ${userProfile['daily_streak']} days');
    print('✅ Tasks Completed: ${userProfile['tasks_completed']}');

    print('\n🏅 BADGES EARNED:');
    var userBadges = userProfile['badges'] as List<String>;
    if (userBadges.isEmpty) {
      print('   No badges yet!');
    } else {
      for (var badgeId in userBadges) {
        var badge = badges[badgeId]!;
        print('   ${badge['icon']} ${badge['name']} - ${badge['description']}');
      }
    }

    print('\n🎯 ACHIEVEMENTS PROGRESS:');
    var achievements = userProfile['achievements'] as Map<String, bool>;
    var completed = achievements.values.where((v) => v).length;
    print('   Completed: $completed/${achievements.length}');
    print('='*50);
  }

  print('🎮 GAMIFICATION SYSTEM DEMO');
  print('='*50);

  displayStats();

  print('\n\n🚀 SIMULATING FIRST LOGIN...');
  handleDailyLogin();
  checkAchievements();

  print('\n\n🚀 SIMULATING TASK COMPLETION...');
  var tasks = [
    'Read article',
    'Watch tutorial',
    'Complete quiz',
    'Share content',
    'Update profile',
    'Join community',
    'Post comment',
    'Rate app',
    'Invite friend',
    'Complete survey',
    'Upload photo',
  ];

  for (int i = 0; i < 6; i++) {
    completeTask(tasks[i]);
  }

  print('\n\n🚀 SIMULATING DAILY STREAK...');
  for (int day = 1; day <= 7; day++) {
    print('\n--- Day $day ---');
    userProfile['last_login'] = DateTime.now().subtract(Duration(days: 8 - day));
    handleDailyLogin();

    if (day % 2 == 0 && day + 5 < tasks.length) {
      completeTask(tasks[day + 5]);
    }

    checkAchievements();
  }

  print('\n\n🏁 FINAL STATS:');
  displayStats();

  print('\n\n🏆 LEADERBOARD (Simulated):');
  print('='*50);
  var leaderboard = [
    {'rank': 1, 'username': 'champion99', 'points': 2500, 'level': 26},
    {'rank': 2, 'username': 'gamer2023', 'points': 2100, 'level': 22},
    {'rank': 3, 'username': 'proPlayer', 'points': 1800, 'level': 19},
    {'rank': 4, 'username': userProfile['username'], 'points': userProfile['points'], 'level': userProfile['level']},
    {'rank': 5, 'username': 'rookie101', 'points': 850, 'level': 9},
  ];

  leaderboard.sort((a, b) => (b['points'] as int).compareTo(a['points'] as int));

  for (int i = 0; i < leaderboard.length; i++) {
    leaderboard[i]['rank'] = i + 1;
  }

  for (var entry in leaderboard) {
    var highlight = entry['username'] == userProfile['username'] ? ' 👈 YOU' : '';
    print('#${entry['rank']} ${entry['username']} - ${entry['points']} pts (Lvl ${entry['level']})$highlight');
  }
  print('='*50);

  int pointsToNextLevel = ((userProfile['level'] as int) * 100) - (userProfile['points'] as int);
  print('\n📈 Progress to Level ${(userProfile['level'] as int) + 1}: ${pointsToNextLevel} points needed');

  print('\n💡 NEXT ACHIEVEMENTS TO UNLOCK:');
  var achievements = userProfile['achievements'] as Map<String, bool>;
  var unlockedCount = 0;
  achievements.forEach((key, value) {
    if (!value && unlockedCount < 3) {
      String suggestion = '';
      switch (key) {
        case 'reach_100_points':
          suggestion = 'Earn ${100 - (userProfile['points'] as int)} more points';
          break;
        case 'reach_500_points':
          suggestion = 'Earn ${500 - (userProfile['points'] as int)} more points';
          break;
        case 'reach_1000_points':
          suggestion = 'Earn ${1000 - (userProfile['points'] as int)} more points';
          break;
        case 'complete_5_tasks':
          suggestion = 'Complete ${5 - (userProfile['tasks_completed'] as int)} more tasks';
          break;
        case 'complete_10_tasks':
          suggestion = 'Complete ${10 - (userProfile['tasks_completed'] as int)} more tasks';
          break;
        case 'daily_streak_3':
          suggestion = 'Login for ${3 - (userProfile['daily_streak'] as int)} more consecutive days';
          break;
        case 'daily_streak_7':
          suggestion = 'Login for ${7 - (userProfile['daily_streak'] as int)} more consecutive days';
          break;
        case 'level_5_reached':
          suggestion = 'Reach level 5 (${5 - (userProfile['level'] as int)} more levels)';
          break;
        case 'level_10_reached':
          suggestion = 'Reach level 10 (${10 - (userProfile['level'] as int)} more levels)';
          break;
      }
      if (suggestion.isNotEmpty) {
        print('   • $suggestion');
        unlockedCount++;
      }
    }
  });
}

