@pragma('vm:entry-point')
bool fn0(List<int> sortedProductIds, int targetId) {
  int low = 0;
  int high = sortedProductIds.length;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    if (sortedProductIds[mid] < targetId) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  if (low < sortedProductIds.length && sortedProductIds[low] == targetId) {
    return (low + 1 < sortedProductIds.length && sortedProductIds[low + 1] == targetId);
  }
  return false;
}

