import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<String> shelfCodes, int currentDayIndex) {
  final overdueDays = <int>[];
  for (final code in shelfCodes) {
    final parts = code.split('-');
    if (parts.length != 2) {
      overdueDays.add(0);
      continue;
    }
    final section = parts[0];
    final checkout = int.tryParse(parts[1]) ?? 0;
    int loanDays;
    if (section == 'A') {
      loanDays = 10;
    } else if (section == 'B') {
      loanDays = 5;
    } else if (section == 'C') {
      loanDays = 15;
    } else {
      loanDays = 7;
    }
    if ((section == 'A' || section == 'C') && checkout % 2 == 0) {
      loanDays = loanDays * 2;
    }
    var due = checkout + loanDays;
    if (due % 7 == 0) {
      due += 1;
    }
    final daysOverdue = currentDayIndex > due ? currentDayIndex - due : 0;
    overdueDays.add(daysOverdue);
  }
  return overdueDays;
}

