import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  var board = [
    [5, 3, 0, 0, 7, 0, 0, 0, 0],
    [6, 0, 0, 1, 9, 5, 0, 0, 0],
    [0, 9, 8, 0, 0, 0, 0, 6, 0],
    [8, 0, 0, 0, 6, 0, 0, 0, 3],
    [4, 0, 0, 8, 0, 3, 0, 0, 1],
    [7, 0, 0, 0, 2, 0, 0, 0, 6],
    [0, 6, 0, 0, 0, 0, 2, 8, 0],
    [0, 0, 0, 4, 1, 9, 0, 0, 5],
    [0, 0, 0, 0, 8, 0, 0, 7, 9]
  ];

  print('Original Sudoku puzzle:');
  for (var row in board) {
    print(row.map((cell) => cell == 0 ? '.' : cell.toString()).join(' '));
  }
  print('');

  bool isValid(List<List<int>> board, int row, int col, int num) {

    for (int x = 0; x < 9; x++) {
      if (board[row][x] == num) {
        return false;
      }
    }

    for (int x = 0; x < 9; x++) {
      if (board[x][col] == num) {
        return false;
      }
    }

    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++) {
      for (int j = 0; j < 3; j++) {
        if (board[i + startRow][j + startCol] == num) {
          return false;
        }
      }
    }

    return true;
  }

  List<int>? findEmpty(List<List<int>> board) {
    for (int i = 0; i < 9; i++) {
      for (int j = 0; j < 9; j++) {
        if (board[i][j] == 0) {
          return [i, j];
        }
      }
    }
    return null;
  }

  bool solve(List<List<int>> board) {
    var empty = findEmpty(board);
    if (empty == null) {
      return true; 
    }

    int row = empty[0];
    int col = empty[1];

    for (int num = 1; num <= 9; num++) {
      if (isValid(board, row, col, num)) {
        board[row][col] = num;

        if (solve(board)) {
          return true;
        }

        board[row][col] = 0;
      }
    }

    return false;
  }

  if (solve(board)) {
    print('Solved Sudoku puzzle:');
    for (var row in board) {
      print(row.join(' '));
    }
  } else {
    print('No solution exists for this Sudoku puzzle.');
  }
}

