    int prev = i > 0 ? logLine[i - 1].codeUnitAt(0) : 32;
    int next = i + 3 < logLine.length ? logLine[i + 3].codeUnitAt(0) : 32;
    if ((prev >= 48 && prev <= 57) || prev == 46) continue;
