  for (int i = 0; i < inventoryCode.length; i++) {
    String currentChar = inventoryCode[i];
    int code = currentChar.codeUnitAt(0);
    bool isAlphaNum = (code >= 48 && code <= 57) ||
                      (code >= 65 && code <= 90) ||
                      (code >= 97 && code <= 122);

    if (isAlphaNum) {
      totalChars++;
      if (lastChar == null || currentChar != lastChar) {
