import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(
  List<double> timestamps,
  List<double> values,
  List<double> confidences,
  double threshold,
) {
  final int n = timestamps.length;
  if (n < 3) return 0;

  final List<int> indices = List<int>.generate(n, (int i) => i);
  indices.sort((int a, int b) {
    final int tsCompare = timestamps[a].compareTo(timestamps[b]);
    if (tsCompare != 0) return tsCompare;
    return confidences[b].compareTo(confidences[a]);
  });

  int count = 0;
  for (int i = 1; i < n - 1; i++) {
    final double prevVal = values[indices[i - 1]];
    final double currVal = values[indices[i]];
    final double nextVal = values[indices[i + 1]];
    if (currVal < prevVal &&
        currVal < nextVal &&
        (prevVal - currVal) >= threshold &&
        (nextVal - currVal) >= threshold) {
      count++;
    }
  }

  return count;
}

