@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  Iterable<int> fibonacci(int max) sync* {
    int a = 0, b = 1;
    while (a <= max) {
      yield a;                 
      final next = a + b;
      a = b;
      b = next;
    }
  }

  Iterable<int> naturals(int n) sync* {
    for (int i = 1; i <= n; i++) {
      yield i;
    }
  }


  Iterable<int> squaresUpTo(int n) sync* {

    yield* naturals(n).map((i) => i * i);
  }

  print('Fibonacci numbers ≤ 100:');
  for (final value in fibonacci(100)) {
    print(value);
  }

  print('\nSquares of the first 10 natural numbers:');
  for (final value in squaresUpTo(10)) {
    print(value);
  }
}

