import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(int startR, int startC, int targetR, int targetC, int k) {
  if (startR < 0 || startR > 7 || startC < 0 || startC > 7) return 0.0;
  if (targetR < 0 || targetR > 7 || targetC < 0 || targetC > 7) return 0.0;
  if (k < 0) return 0.0;

  double backtrack(int r, int c, int stepsLeft, int visited) {
    if (stepsLeft == 0) {
      return (r == targetR && c == targetC) ? 1.0 : 0.0;
    }
    double prob = 0.0;
    const dr = [1, 1, -1, -1, 2, 2, -2, -2];
    const dc = [2, -2, 2, -2, 1, -1, 1, -1];
    for (int i = 0; i < 8; i++) {
      int nr = r + dr[i];
      int nc = c + dc[i];
      if (nr >= 0 && nr < 8 && nc >= 0 && nc < 8) {
        int bit = 1 << (nr * 8 + nc);
        if ((visited & bit) == 0) {
          prob += 0.125 * backtrack(nr, nc, stepsLeft - 1, visited | bit);
        }
      }
    }
    return prob;
  }

  return backtrack(startR, startC, k, 1 << (startR * 8 + startC));
}

