@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(int targetFlavors, int ingredientFlavors) {
  if (targetFlavors == 0) return 1.0;
  int matched = targetFlavors & ingredientFlavors;
  int targetCount = 0;
  int matchedCount = 0;
  int t = targetFlavors;
  int m = matched;
  while (t > 0) {
    targetCount += t & 1;
    matchedCount += m & 1;
    t >>= 1;
    m >>= 1;
  }
  return matchedCount / targetCount;
}

