import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<List<int>> ingredientGrid, int scaleFactor) {
  if (scaleFactor <= 0) {
    return 'invalid';
  }
  if (ingredientGrid.isEmpty) {
    return '';
  }

  int cols = ingredientGrid[0].length;
  if (cols == 0) {
    return '';
  }

  for (int r = 0; r < ingredientGrid.length; r++) {
    if (ingredientGrid[r].length != cols) {
      return 'invalid';
    }
  }

  List<int> scaledSequence = [];
  int rows = ingredientGrid.length;

  for (int diagonal = 0; diagonal <= rows + cols - 2; diagonal++) {
    List<int> current = [];

    int startRow = diagonal < cols ? 0 : diagonal - cols + 1;
    int endRow = diagonal < rows ? diagonal : rows - 1;

    for (int r = startRow; r <= endRow; r++) {
      int c = diagonal - r;
      int scaled = ingredientGrid[r][c] * scaleFactor;
      current.add(scaled);
    }

    if (diagonal % 2 == 0) {
      for (int i = current.length - 1; i >= 0; i--) {
        scaledSequence.add(current[i]);
      }
    } else {
      scaledSequence.addAll(current);
    }
  }

  List<String> parts = [];
  int index = 0;

  while (index < scaledSequence.length) {
    int value = scaledSequence[index];
    int count = 1;

    while (index + count < scaledSequence.length &&
        scaledSequence[index + count] == value) {
      count++;
    }

    parts.add(count > 1 ? '$value*$count' : '$value');
    index += count;
  }

  return parts.join('|');
}

