import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String encodedChart) {
  Set<int> corrupted = {};
  if (encodedChart.isEmpty) {
    return corrupted;
  }

  List<String> rows = encodedChart.split('|');

  for (String row in rows) {
    int colon = row.indexOf(':');
    int hash = row.indexOf('#');

    if (!row.startsWith('R') || colon < 2 || hash <= colon + 1) {
      continue;
    }

    int rowNumber = int.tryParse(row.substring(1, colon)) ?? -1;
    int givenChecksum = int.tryParse(row.substring(hash + 1)) ?? -1;
    String tokens = row.substring(colon + 1, hash);

    bool bad = rowNumber < 0 || givenChecksum < 0;
    int seatPosition = 0;
    int score = 0;
    String previousType = '';
    int i = 0;

    while (!bad && i < tokens.length) {
      String type = tokens[i];
      if (type != 'A' && type != 'E') {
        bad = true;
        break;
      }

      if (type == previousType) {
        bad = true;
        break;
      }
      previousType = type;
      i++;

      int start = i;
      while (i < tokens.length) {
        int code = tokens.codeUnitAt(i);
        if (code < 48 || code > 57) {
          break;
        }
        i++;
      }

      if (start == i) {
        bad = true;
        break;
      }

      int count = int.parse(tokens.substring(start, i));
      if (count <= 0) {
        bad = true;
        break;
      }

      for (int j = 0; j < count; j++) {
        seatPosition++;
        score += type == 'A' ? seatPosition * 3 : seatPosition;
      }
    }

    if (seatPosition != 12) {
      bad = true;
    }

    int expectedChecksum = (score + rowNumber * 7 + tokens.length) % 97;
    if (bad || expectedChecksum != givenChecksum) {
      corrupted.add(rowNumber);
    }
  }

  return corrupted;
}

