  void inorder(Node? node) {
    if (node == null) return;
    inorder(node.left);
    inorderList.add(node.data);
    inorder(node.right);
  }

  void preorder(Node? node) {
    if (node == null) return;
    preorderList.add(node.data);
    preorder(node.left);
    preorder(node.right);
  }

  void postorder(Node? node) {
    if (node == null) return;
    postorder(node.left);
    postorder(node.right);
    postorderList.add(node.data);
