import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> hand) {
  final suitRanks = <String, Set<int>>{};
  for (final card in hand) {
    final suit = card[card.length - 1];
    final rankStr = card.substring(0, card.length - 1);
    final rank = switch (rankStr) {
      'A' => 1,
      'J' => 11,
      'Q' => 12,
      'K' => 13,
      _ => int.parse(rankStr),
    };
    suitRanks.putIfAbsent(suit, () => <int>{}).add(rank);
  }
  final result = <String, int>{};
  for (final entry in suitRanks.entries) {
    final ranks = entry.value;
    final count = ranks.length;
    if (count <= 1) {
      result[entry.key] = 0;
      continue;
    }
    int minR = 14, maxR = 0;
    for (final r in ranks) {
      if (r < minR) minR = r;
      if (r > maxR) maxR = r;
    }
    var gaps = (maxR - minR + 1) - count;
    if (ranks.contains(1)) {
      final alt = Set<int>.from(ranks)..remove(1)..add(14);
      int aMin = 14, aMax = 0;
      for (final r in alt) {
        if (r < aMin) aMin = r;
        if (r > aMax) aMax = r;
      }
      final altGaps = (aMax - aMin + 1) - alt.length;
      if (altGaps < gaps) gaps = altGaps;
    }
    result[entry.key] = gaps;
  }
  return result;
}

