Map<String, int> fn0(List<String> sequences) {
  List<String> sorted = List<String>.from(sequences);
  sorted.sort((a, b) {
    int gcA = 0, gcB = 0;
    for (int i = 0; i < a.length; i++) {
      if (a[i] == 'G' || a[i] == 'C') gcA++;
    }
    for (int i = 0; i < b.length; i++) {
      if (b[i] == 'G' || b[i] == 'C') gcB++;
    }
    if (gcA != gcB) return gcB - gcA;
    return a.compareTo(b);
  });
  Map<String, int> result = {};
  for (int i = 0; i < sorted.length; i++) {
    if (!result.containsKey(sorted[i])) {
      result[sorted[i]] = i + 1;
    }
  }
  return result;
}

