import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String start, List<String> squares) {
  int f = start.codeUnitAt(0), r = int.parse(start[1]);
  List<String> res = [];
  for (var m in [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]]) {
    int nf = f + m[0], nr = r + m[1];
    if (nf < 97 || nf > 104 || nr < 1 || nr > 8) continue;
    String c = String.fromCharCode(nf) + nr.toString();
    int lo = 0, hi = squares.length - 1;
    while (lo <= hi) {
      int mid = (lo + hi) ~/ 2;
      int cmp = c.compareTo(squares[mid]);
      if (cmp == 0) { res.add(c); break; }
      else if (cmp < 0) hi = mid - 1;
      else lo = mid + 1;
    }
  }
  res.sort();
  return res;
}

