import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> bytes = [72, 101, 108, 108, 111, 44, 32, 228, 184, 150, 231, 149, 140];

  List<int> codePoints = [];

  int i = 0;

  while (i < bytes.length) {
    int byte1 = bytes[i];

    if (byte1 < 128) {

      codePoints.add(byte1);
      i++;
    } else if (byte1 >= 192 && byte1 < 224) {

      if (i + 1 >= bytes.length) {

        codePoints.add(0xFFFD); 
        break;
      }
      int byte2 = bytes[i + 1];
      if (byte2 < 128 || byte2 >= 192) {

        codePoints.add(0xFFFD);
        i++;
        continue;
      }
      int codePoint = ((byte1 & 0x1F) << 6) | (byte2 & 0x3F);
      codePoints.add(codePoint);
      i += 2;
    } else if (byte1 >= 224 && byte1 < 240) {

      if (i + 2 >= bytes.length) {

        codePoints.add(0xFFFD);
        break;
      }
      int byte2 = bytes[i + 1];
      int byte3 = bytes[i + 2];
      if (byte2 < 128 || byte2 >= 192 || byte3 < 128 || byte3 >= 192) {

        codePoints.add(0xFFFD);
        i++;
        continue;
      }
      int codePoint = ((byte1 & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F);
      codePoints.add(codePoint);
      i += 3;
    } else if (byte1 >= 240 && byte1 < 248) {

      if (i + 3 >= bytes.length) {

        codePoints.add(0xFFFD);
        break;
      }
      int byte2 = bytes[i + 1];
      int byte3 = bytes[i + 2];
      int byte4 = bytes[i + 3];
      if (byte2 < 128 || byte2 >= 192 || byte3 < 128 || byte3 >= 192 || byte4 < 128 || byte4 >= 192) {

        codePoints.add(0xFFFD);
        i++;
        continue;
      }
      int codePoint = ((byte1 & 0x07) << 18) | ((byte2 & 0x3F) << 12) | ((byte3 & 0x3F) << 6) | (byte4 & 0x3F);
      codePoints.add(codePoint);
      i += 4;
    } else {

      codePoints.add(0xFFFD); 
      i++;
    }
  }

  String decodedString = String.fromCharCodes(codePoints);

  print(decodedString); 
}

