import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<String>> grid) {
  if (grid.isEmpty) return {};
  int rows = grid.length;
  List<List<int>> memo = List.generate(rows, (i) => List.filled(grid[i].length, 0));
  List<List<String>> categories = List.generate(rows, (i) => List.filled(grid[i].length, ''));
  List<List<int>> numbers = List.generate(rows, (i) => List.filled(grid[i].length, 0));

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < grid[i].length; j++) {
      String code = grid[i][j];
      categories[i][j] = code[0];
      numbers[i][j] = int.parse(code.substring(1));
    }
  }

  const List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

  int dfs(int r, int c) {
    if (memo[r][c] != 0) return memo[r][c];
    int maxLen = 1;
    String cat = categories[r][c];
    int num = numbers[r][c];
    for (var dir in dirs) {
      int nr = r + dir[0];
      int nc = c + dir[1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
        if (categories[nr][nc] == cat && numbers[nr][nc] > num) {
          int len = 1 + dfs(nr, nc);
          if (len > maxLen) maxLen = len;
        }
      }
    }
    memo[r][c] = maxLen;
    return maxLen;
  }

  Map<String, int> result = {};
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < grid[i].length; j++) {
      String cat = categories[i][j];
      int len = dfs(i, j);
      if (!result.containsKey(cat) || len > result[cat]!) {
        result[cat] = len;
      }
    }
  }
  return result;
}

