double fn0(List<double> cycles, double maxCapacity) {
  int left = 0;
  double sum = 0.0;
  int maxLen = 0;
  for (int right = 0; right < cycles.length; right++) {
    sum += cycles[right];
    while (sum > maxCapacity && left <= right) {
      sum -= cycles[left];
      left++;
