import 'dart:isolate';
import 'dart:async';

@pragma('vm:entry-point')
void worker(SendPort mainSendPort) {

  final ReceivePort workerReceivePort = ReceivePort();

  mainSendPort.send(workerReceivePort.sendPort);

  workerReceivePort.listen((message) {
    if (message is List) {
      final int data = message[0];
      final SendPort replyPort = message[1];

      int result = 0;
      for (int i = 1; i <= data; i++) {
        result += i;
      }

      replyPort.send(result);
    }
  });
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
Future<void> fn0() async {

  final ReceivePort mainReceivePort = ReceivePort();

  await Isolate.spawn(worker, mainReceivePort.sendPort);

  final SendPort workerSendPort = await mainReceivePort.first;

  final ReceivePort resultPort = ReceivePort();

  workerSendPort.send([10000, resultPort.sendPort]);

  final int result = await resultPort.first;

  print('Result from isolate: $result (sum of numbers from 1 to 10000)');

  mainReceivePort.close();
  resultPort.close();
}

