List<int> fn0(int n, int kr, int kc, int k) {



  int countWithin(int d) {
    if (d < 0) return 0;
    int rLo = kr - d < 1 ? 1 : kr - d;
    int rHi = kr + d > n ? n : kr + d;
    int cLo = kc - d < 1 ? 1 : kc - d;
    int cHi = kc + d > n ? n : kc + d;
    return (rHi - rLo + 1) * (cHi - cLo + 1);
  }

  int maxR = kr - 1 > n - kr ? kr - 1 : n - kr;
  int maxC = kc - 1 > n - kc ? kc - 1 : n - kc;
  int lo = 0;
  int hi = maxR > maxC ? maxR : maxC;
  while (lo < hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (countWithin(mid) >= k) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  int within = countWithin(lo);
  int exact = within - countWithin(lo - 1);
  return [lo, within, exact];
}

