import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> initialSlots, int teamId) {
  if (initialSlots.isEmpty) {
    return 0.0;
  }

  int size = 1;
  while (size < initialSlots.length) {
    size *= 2;
  }

  List<int> slots = List<int>.filled(size, 0);
  for (int i = 0; i < initialSlots.length; i++) {
    slots[i] = initialSlots[i];
  }

  bool exists = false;
  for (final team in slots) {
    if (team == teamId) {
      exists = true;
      break;
    }
  }

  if (!exists) {
    return 0.0;
  }

  List<List<double>> dp = List<List<double>>.generate(
    size,
    (_) => List<double>.filled(size + 1, 0.0),
  );

  for (int i = 0; i < size; i++) {
    dp[i][0] = slots[i] == 0 ? 0.0 : 1.0;
  }

  for (int round = 1; (1 << round) <= size; round++) {
    int blockSize = 1 << round;
    int half = blockSize ~/ 2;

    for (int i = 0; i < size; i++) {
      if (slots[i] == 0) {
        continue;
      }

      int blockStart = (i ~/ blockSize) * blockSize;
      bool inLeft = (i - blockStart) < half;
      int oppStart = inLeft ? blockStart + half : blockStart;
      int oppEnd = oppStart + half;

      double survive = 0.0;

      for (int j = oppStart; j < oppEnd; j++) {
        if (slots[j] == 0) {
          continue;
        }

        double winChance = slots[i] == slots[j] ? 0.0 : 0.5;
        survive += dp[j][round - 1] * winChance;
      }

      bool emptyOppSide = true;
      for (int j = oppStart; j < oppEnd; j++) {
        if (slots[j] != 0) {
          emptyOppSide = false;
          break;
        }
      }

      if (emptyOppSide) {
        survive = 1.0;
      }

      dp[i][round] = dp[i][round - 1] * survive;
    }
  }

  int rounds = 0;
  while ((1 << rounds) < size) {
    rounds++;
  }

  double answer = 0.0;
  for (int i = 0; i < size; i++) {
    if (slots[i] == teamId) {
      answer += dp[i][rounds];
    }
  }

  return answer;
}

