import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(
    List<List<int>> playlists, int fromDay, int toDay) {




  if (toDay < fromDay) {
    return {'coveredDays': 0, 'gapDays': 0, 'maxOverlap': 0, 'firstGapDay': -1};
  }
  final events = <List<int>>[];
  for (final p in playlists) {
    final len = p[1];
    if (len <= 0) continue;
    final s = p[0] < fromDay ? fromDay : p[0];
    final rawEnd = p[0] + len - 1;
    final e = rawEnd > toDay ? toDay : rawEnd;
    if (s > e) continue;
    events.add([s, 1]);
    events.add([e + 1, -1]);
  }
  events.sort((a, b) => a[0].compareTo(b[0]));
  var covered = 0;
  var maxOverlap = 0;
  var firstGap = -1;
  var active = 0;
  var prev = fromDay;
  var i = 0;
  while (i < events.length) {
    final day = events[i][0];
    if (day > prev) {
      if (active > 0) {
        covered += day - prev;
      } else if (firstGap == -1) {
        firstGap = prev;
      }
      prev = day;
    }
    while (i < events.length && events[i][0] == day) {
      active += events[i][1];
      i++;
    }
    if (active > maxOverlap) maxOverlap = active;
  }
  if (prev <= toDay) {
    if (active > 0) {
      covered += toDay - prev + 1;
    } else if (firstGap == -1) {
      firstGap = prev;
    }
  }
  return {
    'coveredDays': covered,
    'gapDays': toDay - fromDay + 1 - covered,
    'maxOverlap': maxOverlap,
    'firstGapDay': firstGap,
  };
}

