import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String notation) {
  double total = 0.0;
  int i = 0;
  final int len = notation.length;

  while (i < len) {
    while (i < len && notation.codeUnitAt(i) == 0x20) i++;
    if (i >= len) break;

    int count = 0;
    bool hasCount = false;
    while (i < len) {
      int c = notation.codeUnitAt(i);
      if (c >= 0x30 && c <= 0x39) {
        hasCount = true;
        count = count * 10 + (c - 0x30);
        i++;
      } else {
        break;
      }
    }
    if (!hasCount) count = 1;

    if (i < len) {
      int c = notation.codeUnitAt(i);
      if (c == 0x64 || c == 0x44) i++;
    }

    int sides = 0;
    while (i < len) {
      int c = notation.codeUnitAt(i);
      if (c >= 0x30 && c <= 0x39) {
        sides = sides * 10 + (c - 0x30);
        i++;
      } else {
        break;
      }
    }

    int modifier = 0;
    if (i < len) {
      int c = notation.codeUnitAt(i);
      if (c == 0x2B || c == 0x2D) {
        int sign = c == 0x2D ? -1 : 1;
        i++;
        int val = 0;
        while (i < len) {
          c = notation.codeUnitAt(i);
          if (c >= 0x30 && c <= 0x39) {
            val = val * 10 + (c - 0x30);
            i++;
          } else {
            break;
          }
        }
        modifier = sign * val;
      }
    }

    total += count * (sides + 1) / 2.0 + modifier;
  }

  return total;
}

