Map<String, int> fn0(int boardMask) {
  int evenPop = 0;
  int oddPop = 0;
  for (int rank = 0; rank < 8; rank++) {
    int rankBits = (boardMask >> (rank * 8)) & 0xFF;
    int pc = 0;
    for (int b = 0; b < 8; b++) {
      if ((rankBits & (1 << b)) != 0) pc++;
    }
    if (rank.isEven) evenPop += pc; else oddPop += pc;
  }
  return {'even': evenPop, 'odd': oddPop};
}

