import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<String> logLevels, int maxErrors) {
  if (logLevels.isEmpty) return "none";

  int bestStart = 0;
  int bestLength = 0;
  int left = 0;
  int errorCount = 0;

  for (int right = 0; right < logLevels.length; right++) {
    if (logLevels[right] == "ERROR" || logLevels[right] == "CRITICAL") {
      errorCount++;
    }

    while (errorCount > maxErrors) {
      if (logLevels[left] == "ERROR" || logLevels[left] == "CRITICAL") {
        errorCount--;
      }
      left++;
    }

    int currentLength = right - left + 1;
    if (currentLength > bestLength) {
      bestLength = currentLength;
      bestStart = left;
    }
  }

  if (bestLength == 0) return "none";
  return "$bestStart:${bestStart + bestLength - 1}";
}

