import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> numbers = [64, 34, 25, 12, 22, 11, 90, 88, 45, 50, 43, 24, 9, 5, 77];

  print('Original array: $numbers');

  void quickSort(List<int> arr, int low, int high) {
    if (low < high) {

      int partition(List<int> arr, int low, int high) {

        int pivot = arr[high];


        int i = low - 1;

        for (int j = low; j < high; j++) {

          if (arr[j] <= pivot) {
            i++;

            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
          }
        }

        int temp = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp;

        return i + 1;
      }

      int partitionIndex = partition(arr, low, high);

      quickSort(arr, low, partitionIndex - 1);
      quickSort(arr, partitionIndex + 1, high);
    }
  }

  quickSort(numbers, 0, numbers.length - 1);

  print('Sorted array: $numbers');

  List<int> moreNumbers = [3, -7, 45, 0, -12, 88, 2, 44, -5, 10];
  print('\nOriginal array 2: $moreNumbers');
  quickSort(moreNumbers, 0, moreNumbers.length - 1);
  print('Sorted array 2: $moreNumbers');

  List<int> duplicates = [5, 2, 8, 2, 9, 1, 5, 5, 3, 2];
  print('\nOriginal array 3: $duplicates');
  quickSort(duplicates, 0, duplicates.length - 1);
  print('Sorted array 3: $duplicates');
}

