double fn0(List<List<double>> grid, double threshold) {
  double sum = 0.0;
  int count = 0;
  for (var row in grid) {
    for (var value in row) {
      if (value >= threshold) {
        sum += value;
        count++;
      }
    }
  }
  if (count == 0) return 0.0;
  return sum / count;
}

