List<int> fn0(List<int> keys, int bucketCount) {
  if (keys.isEmpty) return List.filled(bucketCount, 0);
  if (keys.length == 1) {
    List<int> result = List.filled(bucketCount, 0);
    result[keys[0].abs() % bucketCount] = 1;
    return result;
