  int mid = keys.length ~/ 2;
  List<int> left = fn0(keys.sublist(0, mid), bucketCount);
  List<int> right = fn0(keys.sublist(mid), bucketCount);
  return [for (int i = 0; i < bucketCount; i++) left[i] + right[i]];
}

