import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String code) {
  int total = 0;
  int multiplier = 1;
  List<int> stack = [];
  for (int i = 0; i < code.length; i++) {
    String ch = code[i];
    if (ch == '(') {
      stack.add(multiplier);
      multiplier *= 2;
    } else if (ch == '[') {
      stack.add(multiplier);
      multiplier *= 3;
    } else if (ch == ')' || ch == ']') {
      if (stack.isNotEmpty) {
        multiplier = stack.removeLast();
      }
    } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      int digit = ch.codeUnitAt(0) - 48;
      total += digit * multiplier;
    }
  }
  return total;
}

