import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> entries, int startBalance, int targetBalance, int maxFlags) {
  if (startBalance < 0) return false;
  if (entries.isEmpty) return startBalance == targetBalance;

  List<Set<int>> dp = List.generate(maxFlags + 1, (_) => <int>{});
  dp[0].add(startBalance);

  for (int entry in entries) {
    List<Set<int>> newDp = List.generate(maxFlags + 1, (_) => <int>{});
    for (int j = 0; j <= maxFlags; j++) {
      for (int bal in dp[j]) {
        int newBal = bal + entry;
        if (newBal >= 0) {
          newDp[j].add(newBal);
        }
        if (j < maxFlags) {
          newDp[j + 1].add(bal);
        }
      }
    }
    dp = newDp;
  }

  for (int j = 0; j <= maxFlags; j++) {
    if (dp[j].contains(targetBalance)) return true;
  }
  return false;
}

