import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  final List<int> arr = args.isNotEmpty
      ? args.map((s) => int.tryParse(s)).whereType<int>().toList()
      : [19, -2, 0, 5, 12, 12, 8, 3, -7, 1];

  print('Original: $arr');

  final int n = arr.length;
  if (n <= 1) {
    print('Sorted:   $arr');
    return;
  }

  for (int start = (n ~/ 2) - 1; start >= 0; start--) {
    int root = start;
    while (true) {
      final int left = (root << 1) + 1; 
      if (left >= n) break; 
      final int right = left + 1; 
      int swapIndex = root;

      if (arr[swapIndex] < arr[left]) swapIndex = left;
      if (right < n && arr[swapIndex] < arr[right]) swapIndex = right;

      if (swapIndex == root) break;

      final int tmp = arr[root];
      arr[root] = arr[swapIndex];
      arr[swapIndex] = tmp;

      root = swapIndex;
    }
  }

  for (int end = n - 1; end > 0; end--) {

    final int tmp = arr[end];
    arr[end] = arr[0];
    arr[0] = tmp;

    int root = 0;
    while (true) {
      final int left = (root << 1) + 1;
      if (left >= end) break; 
      final int right = left + 1;
      int swapIndex = root;

      if (arr[swapIndex] < arr[left]) swapIndex = left;
      if (right < end && arr[swapIndex] < arr[right]) swapIndex = right;

      if (swapIndex == root) break;

      final int tmp2 = arr[root];
      arr[root] = arr[swapIndex];
      arr[swapIndex] = tmp2;

      root = swapIndex;
    }
  }

  print('Sorted:   $arr');
}

