@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<Map<int, int>> precinctVotes, int windowSize) {
  if (precinctVotes.isEmpty || windowSize <= 0 || windowSize > precinctVotes.length) {
    return <int>{};
  }

  int? _majority(Map<int, int> freq) {
    int total = 0;
    freq.forEach((_, v) => total += v);
    for (final MapEntry<int, int> entry in freq.entries) {
      if (entry.value * 2 > total) return entry.key;
    }
    return null;
  }

  Map<int, int> freq = {};
  for (int i = 0; i < windowSize; i++) {
    precinctVotes[i].forEach((fn0, count) {
      freq[fn0] = (freq[fn0] ?? 0) + count;
    });
  }

  Set<int> result = {};
  int? winner = _majority(freq);
  if (winner != null) result.add(winner);

  for (int i = 0; i + windowSize < precinctVotes.length; i++) {
    precinctVotes[i].forEach((fn0, count) {
      int newVal = (freq[fn0] ?? 0) - count;
      if (newVal <= 0) {
        freq.remove(fn0);
      } else {
        freq[fn0] = newVal;
      }
    });
    precinctVotes[i + windowSize].forEach((fn0, count) {
      freq[fn0] = (freq[fn0] ?? 0) + count;
    });
    winner = _majority(freq);
    if (winner != null) result.add(winner);
  }
  return result;
}

