int fn0(String modules) {
  if (modules.length < 15 || modules.length > 95) return 0;
  int payload = 0;
  int check = 0;
  int pos = 0;
  int tokenVal = 0;
  int tokenLen = 0;
  int tokens = 0;
  bool validStart = false;
  for (int i = 0; i < modules.length; i++) {
    int d = modules.codeUnitAt(i) - 48;
    if (d < 0 || d > 9) return 0;
    if (tokens == 0 && d == 1 && i + 2 < modules.length) {
      if (modules[i + 1] == '1' && modules[i + 2] == '1') {
        validStart = true;
        i += 2;
        continue;
      }
    }
    if (d == 0) {
      if (tokenLen > 0) {
        if (tokenLen < 2 || tokenLen > 7) return 0;
        tokens++;
        int w = (tokens % 2 == 0) ? 3 : 1;
        check = (check + (tokenVal % 10) * w) % 10;
        if (tokens > 1 && tokens < 13) {
          payload = payload * 10 + (tokenVal % 10);
        }
        tokenVal = 0;
        tokenLen = 0;
      }
    } else {
      tokenVal = tokenVal * 10 + d;
      tokenLen++;
    }
  }
  if (tokenLen > 0) {
    tokens++;
    check = (check + tokenVal % 10) % 10;
    if (tokens > 1 && tokens < 13) payload = payload * 10 + (tokenVal % 10);
  }
  if (!validStart || tokens != 13 || check != 0) return 0;
  return payload;
}

