@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<String> symbols) {
  if (symbols.isEmpty) return {};
  Map<int, int> dashFreqByLength = {};
  Map<int, int> dotCountFreq = {};
  for (String s in symbols) {
    int len = s.length;
    int dashes = 0;
    int dots = 0;
    for (int i = 0; i < s.length; i++) {
      if (s[i] == '-') dashes++;
      else if (s[i] == '.') dots++;
    }
    dashFreqByLength[len] = (dashFreqByLength[len] ?? 0) + dashes;
    dotCountFreq[dots] = (dotCountFreq[dots] ?? 0) + 1;
  }
  Set<int> result = {};
  dotCountFreq.forEach((dots, freq) {
    if (freq > 1 && dashFreqByLength.containsKey(dots)) {
      result.add(dashFreqByLength[dots]!);
    }
  });
  return result;
}

