List<String> fn0(String log) {
  List<String> tokens = [];
  if (log.isEmpty) return tokens;
  List<String> entries = log.split(',');
  for (String entry in entries) {
    entry = entry.trim();
    if (entry.isEmpty) continue;
    List<String> parts = entry.split(' ');
    String bin = '';
    String sku = '';
    int qty = 0;
    for (String part in parts) {
      if (part.startsWith('BIN:')) {
        bin = part.substring(4);
      } else if (part.startsWith('SKU:')) {
        sku = part.substring(4);
      } else if (part.startsWith('QTY:')) {
        qty = int.tryParse(part.substring(4)) ?? 0;
      }
    }
    if (bin.isNotEmpty && sku.isNotEmpty && qty > 0) {
      tokens.add('$bin-$sku');
    }
  }
  return tokens;
}

