import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<List<int>> ledger) {
  if (ledger.isEmpty || ledger[0].isEmpty) return [];
  int rows = ledger.length;
  int cols = ledger[0].length;
  List<String> results = [];
  List<int> path = List<int>.filled(rows, 0);

  void dfs(int row, int col, int sum) {
    sum += ledger[row][col];
    path[row] = col;
    if (row == rows - 1) {
      if (sum == 0) {
        results.add(path.join(','));
      }
    } else {
      for (int nextCol = col - 1; nextCol <= col + 1; nextCol++) {
        if (nextCol >= 0 && nextCol < cols) {
          dfs(row + 1, nextCol, sum);
        }
      }
    }
  }

  for (int c = 0; c < cols; c++) {
    dfs(0, c, 0);
  }

  results.sort();
  return results;
}

