    final maxC = max(r, max(g, b)), minC = min(r, min(g, b));
    final delta = maxC - minC;
    final l = (maxC + minC) / 2.0;
    double h = 0, s = 0;

    if (delta != 0) {
      s = delta / (1 - (2 * l - 1).abs());
      if (maxC == r) {
        h = 60 * (((g - b) / delta) % 6);
      } else if (maxC == g) {
        h = 60 * (((b - r) / delta) + 2);
      } else {
        h = 60 * (((r - g) / delta) + 4);
      }
    }
    return [h, s, l];
  }

  List<int> hslToRgb(List<double> hsl) {
    double h = hsl[0], s = hsl[1], l = hsl[2];

    final c = (1 - (2 * l - 1).abs()) * s;
    final x = c * (1 - ((h / 60) % 2 - 1).abs());
    final m = l - c / 2;

    double r1 = 0, g1 = 0, b1 = 0;
    if (h < 60) {
      r1 = c; g1 = x; b1 = 0;
    } else if (h < 120) {
      r1 = x; g1 = c; b1 = 0;
    } else if (h < 180) {
      r1 = 0; g1 = c; b1 = x;
    } else if (h < 240) {
      r1 = 0; g1 = x; b1 = c;
    } else if (h < 300) {
      r1 = x; g1 = 0; b1 = c;
    } else {
      r1 = c; g1 = 0; b1 = x;
    }

    return [
      ((r1 + m) * 255).round(),
      ((g1 + m) * 255).round(),
      ((b1 + m) * 255).round()
    ];
  }

  String rgbToHex(List<int> rgb) =>
      rgb.map((v) => v.toRadixString(16).padLeft(2, '0').toUpperCase()).join();

  List<double> seedHsl = rgbToHsl(seedRgb);

  List<int> complementary = hslToRgb(
      [(seedHsl[0] + 180) % 360, seedHsl[1], seedHsl[2]]);

  List<int> analogous1 =
      hslToRgb([_wrap(seedHsl[0] + 30), seedHsl[1], seedHsl[2]]);
  List<int> analogous2 =
      hslToRgb([_wrap(seedHsl[0] - 30), seedHsl[1], seedHsl[2]]);

  List<int> triadic1 =
      hslToRgb([_wrap(seedHsl[0] + 120), seedHsl[1], seedHsl[2]]);
  List<int> triadic2 =
      hslToRgb([_wrap(seedHsl[0] + 240), seedHsl[1], seedHsl[2]]);

  List<int> lighter = hslToRgb(
      [seedHsl[0], seedHsl[1], _clamp(seedHsl[2] + 0.2)]);
  List<int> darker =
      hslToRgb([seedHsl[0], seedHsl[1], _clamp(seedHsl[2] - 0.2)]);

  void show(String name, List<int> rgb) =>
      print('${name.padRight(14)}: #${rgbToHex(rgb)}');

  print('\nDynamic Color Scheme for #${rgbToHex(seedRgb)}');
  print('────────────────────────────────────────');
  show('Seed', seedRgb);
  show('Complement', complementary);
  show('Analogous +30°', analogous1);
  show('Analogous -30°', analogous2);
  show('Triadic +120°', triadic1);
  show('Triadic +240°', triadic2);
  show('Lighter', lighter);
  show('Darker', darker);
  print('────────────────────────────────────────\n');
}

List<int> _hexToRgb(String hex) {
  final normalized = hex.replaceAll('#', '').padLeft(6, '0');
  return [
    int.parse(normalized.substring(0, 2), radix: 16),
    int.parse(normalized.substring(2, 4), radix: 16),
    int.parse(normalized.substring(4, 6), radix: 16)
  ];
}

double _clamp(double v, [double min = 0, double max = 1]) =>
    v < min ? min : (v > max ? max : v);

double _wrap(double h) => (h + 360) % 360;

