import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String dna, String marker) {
  if (dna.isEmpty || marker.isEmpty || marker.length > dna.length) {
    return <String>[];
  }

  Map<String, int> need = <String, int>{};
  for (int i = 0; i < marker.length; i++) {
    String ch = marker[i];
    need[ch] = (need[ch] ?? 0) + 1;
  }

  Map<String, int> have = <String, int>{};
  int satisfied = 0;
  int required = need.length;
  int left = 0;
  int bestLength = dna.length + 1;
  List<String> result = <String>[];
  Set<String> seen = <String>{};

  for (int right = 0; right < dna.length; right++) {
    String add = dna[right];
    have[add] = (have[add] ?? 0) + 1;

    if (need.containsKey(add) && have[add] == need[add]) {
      satisfied++;
    }

    while (satisfied == required && left <= right) {
      int currentLength = right - left + 1;
      String window = dna.substring(left, right + 1);

      if (currentLength < bestLength) {
        bestLength = currentLength;
        result.clear();
        seen.clear();
      }

      if (currentLength == bestLength && !seen.contains(window)) {
        result.add(window);
        seen.add(window);
      }

      String remove = dna[left];
      have[remove] = have[remove]! - 1;

      if (need.containsKey(remove) && have[remove]! < need[remove]!) {
        satisfied--;
      }

      left++;
    }
  }

  return result;
}

