import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> packets, int threshold) {
  if (packets.isEmpty) return [];

  List<int> deduped = [];
  Set<int> seen = {};
  for (int p in packets) {
    if (!seen.contains(p)) {
      seen.add(p);
      deduped.add(p);
    }
  }


  List<int> result = [];
  int burstMax = deduped[0];

  for (int i = 1; i < deduped.length; i++) {
    if ((deduped[i] - deduped[i - 1]).abs() > threshold) {
      result.add(burstMax);
      burstMax = deduped[i];
    } else {
      if (deduped[i] > burstMax) {
        burstMax = deduped[i];
      }
    }
  }
  result.add(burstMax);

  return result;
}

