  final winners = <int>{};
  for (final row in tallies) {
    if (row.isEmpty) continue;
    var best = 0;
    var tie = false;
    for (var i = 1; i < row.length; i++) {
      if (row[i] > row[best]) {
        best = i;
        tie = false;
      } else if (row[i] == row[best]) {
        tie = true;
      }
