import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<String> logs) {
  if (logs.isEmpty) {
    return 'empty';
  }

  List<List<int>> rects = [];
  int minX = 1 << 30;
  int minY = 1 << 30;
  int maxX = -(1 << 30);
  int maxY = -(1 << 30);

  for (String line in logs) {
    List<String> parts = line.split(' ');
    int x1 = int.parse(parts[1]);
    int y1 = int.parse(parts[2]);
    int x2 = int.parse(parts[3]);
    int y2 = int.parse(parts[4]);

    int left = x1 < x2 ? x1 : x2;
    int right = x1 > x2 ? x1 : x2;
    int bottom = y1 < y2 ? y1 : y2;
    int top = y1 > y2 ? y1 : y2;

    rects.add([left, bottom, right, top]);
    if (left < minX) minX = left;
    if (bottom < minY) minY = bottom;
    if (right > maxX) maxX = right;
    if (top > maxY) maxY = top;
  }

  int bestX = 0;
  int bestY = 0;
  int bestCount = -1;
  int bestDist = 1 << 30;

  for (int x = minX; x <= maxX; x++) {
    for (int y = minY; y <= maxY; y++) {
      int count = 0;
      for (List<int> r in rects) {
        if (x >= r[0] && x <= r[2] && y >= r[1] && y <= r[3]) {
          count++;
        }
      }

      int dist = x.abs() + y.abs();
      if (count > bestCount ||
          (count == bestCount &&
              (dist < bestDist ||
                  (dist == bestDist &&
                      (x < bestX || (x == bestX && y < bestY)))))) {
        bestCount = count;
        bestDist = dist;
        bestX = x;
        bestY = y;
      }
    }
  }

  return '$bestX,$bestY:$bestCount';
}

