void fn0(List<String> args) {

  if (args.length != 2) {
    print('Usage: dart fast_exp.dart <base> <exponent>');
    print('Example: dart fast_exp.dart 5 13  ➜  5^13 = 1220703125');
    return;
  }



  final BigInt base = BigInt.parse(args[0]);
  int exponent = int.parse(args[1]);

  if (exponent < 0) {
    print('Exponent must be non-negative.');
    return;
  }

  BigInt result = BigInt.one; 
  BigInt power  = base;       


  while (exponent > 0) {
    if ((exponent & 1) == 1) {
      result *= power;        
    }
    power *= power;           
    exponent >>= 1;           
  }

  print('${args[0]}^${args[1]} = $result');
}

