import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final List<List<int>> edges = [
    [0, 1], [0, 2],
    [1, 2],
    [2, 0], [2, 3],
    [3, 2],
    [4, 2], [4, 3]
  ];

  final Set<int> nodes = {};
  for (var e in edges) {
    nodes.add(e[0]);
    nodes.add(e[1]);
  }
  final int n = nodes.length;

  final Map<int, List<int>> outgoing = {for (var v in nodes) v: []};
  for (var e in edges) {
    outgoing[e[0]]!.add(e[1]);
  }

  const double damping = 0.85;   
  const int iterations = 20;     

  final Map<int, double> rank = {for (var v in nodes) v: 1.0 / n};

  for (int it = 0; it < iterations; it++) {

    final Map<int, double> newRank = {
      for (var v in nodes) v: (1 - damping) / n
    };

    for (var v in nodes) {
      final links = outgoing[v]!;
      if (links.isEmpty) {

        final share = rank[v]! / n;
        for (var u in nodes) {
          newRank[u] = newRank[u]! + damping * share;
        }
      } else {
        final share = rank[v]! / links.length;
        for (var u in links) {
          newRank[u] = newRank[u]! + damping * share;
        }
      }
    }

    for (var v in nodes) {
      rank[v] = newRank[v]!;
    }
  }

  print('PageRank after $iterations iterations:');
  for (var v in nodes) {
    print('Node $v → ${rank[v]!.toStringAsFixed(4)}');
  }
}

