import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<String> rows) {
  if (rows.isEmpty) return false;
  String prev = '';
  int width = -1;
  for (int i = 0; i < rows.length; i++) {
    String r = rows[i];
    int pipeIdx = r.lastIndexOf('|');
    if (pipeIdx == -1 || pipeIdx == r.length - 1) return false;
    String body = r.substring(0, pipeIdx);
    String lenStr = r.substring(pipeIdx + 1);
    int expectedLen;
    try {
      expectedLen = int.parse(lenStr);
      if (expectedLen < 0) return false;
    } catch (_) {
      return false;
    }
    String decoded;
    if (body == 'R') {
      if (i == 0) return false;
      decoded = prev;
    } else if (body.isEmpty) {
      decoded = '';
    } else {
      StringBuffer sb = StringBuffer();
      int j = 0;
      while (j < body.length) {
        int k = j;
        while (k < body.length) {
          int c = body.codeUnitAt(k);
          if (c < 48 || c > 57) break;
          k++;
        }
        if (k == j || k >= body.length) return false;
        int count = int.parse(body.substring(j, k));
        if (count < 0 || count > 1000) return false;
        String ch = body.substring(k, k + 1);
        sb.write(ch * count);
        j = k + 1;
      }
      decoded = sb.toString();
    }
    if (decoded.length != expectedLen) return false;
    if (width == -1) {
      width = decoded.length;
    } else if (decoded.length != width) {
      return false;
    }
    prev = decoded;
  }
  return true;
}

