import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int? modularInverse(int a, int m) {
    if (m == 1) return 0;

    int m0 = m;
    int x0 = 0;
    int x1 = 1;

    while (a > 1) {

      int q = a ~/ m;

      int temp = m;
      m = a % m;
      a = temp;

      temp = x0;
      x0 = x1 - q * x0;
      x1 = temp;
    }

    if (x1 < 0) {
      x1 += m0;
    }

    return x1;
  }


  List<int> extendedGCD(int a, int b) {
    if (b == 0) {
      return [a, 1, 0]; 
    }

    int x1 = 1, x2 = 0;
    int y1 = 0, y2 = 1;

    while (b != 0) {
      int q = a ~/ b;

      int temp = b;
      b = a % b;
      a = temp;

      temp = x2;
      x2 = x1 - q * x2;
      x1 = temp;

      temp = y2;
      y2 = y1 - q * y2;
      y1 = temp;
    }

    return [a, x1, y1]; 
  }

  print("=== Modular Inverse Examples ===");

  int a1 = 3;
  int m1 = 11;
  int? inverse1 = modularInverse(a1, m1);
  print("Modular inverse of $a1 mod $m1 = $inverse1");
  if (inverse1 != null) {
    print("Verification: ($a1 * $inverse1) mod $m1 = ${(a1 * inverse1) % m1}");
  }

  int a2 = 10;
  int m2 = 17;
  int? inverse2 = modularInverse(a2, m2);
  print("\nModular inverse of $a2 mod $m2 = $inverse2");
  if (inverse2 != null) {
    print("Verification: ($a2 * $inverse2) mod $m2 = ${(a2 * inverse2) % m2}");
  }

  int a3 = 7;
  int m3 = 26;
  int? inverse3 = modularInverse(a3, m3);
  print("\nModular inverse of $a3 mod $m3 = $inverse3");
  if (inverse3 != null) {
    print("Verification: ($a3 * $inverse3) mod $m3 = ${(a3 * inverse3) % m3}");
  }

  print("\n=== Extended GCD Examples ===");

  int x = 30;
  int y = 18;
  List<int> result1 = extendedGCD(x, y);
  print("\nExtended GCD of $x and $y:");
  print("GCD = ${result1[0]}");
  print("Coefficients: x = ${result1[1]}, y = ${result1[2]}");
  print("Verification: $x * ${result1[1]} + $y * ${result1[2]} = ${x * result1[1] + y * result1[2]}");

  x = 35;
  y = 15;
  List<int> result2 = extendedGCD(x, y);
  print("\nExtended GCD of $x and $y:");
  print("GCD = ${result2[0]}");
  print("Coefficients: x = ${result2[1]}, y = ${result2[2]}");
  print("Verification: $x * ${result2[1]} + $y * ${result2[2]} = ${x * result2[1] + y * result2[2]}");

  print("\n=== Using Extended GCD for Modular Inverse ===");
  int a4 = 5;
  int m4 = 13;
  List<int> extResult = extendedGCD(a4, m4);

  if (extResult[0] == 1) { 
    int modInverse = extResult[1] % m4;
    if (modInverse < 0) modInverse += m4;
    print("Modular inverse of $a4 mod $m4 using Extended GCD = $modInverse");
    print("Verification: ($a4 * $modInverse) mod $m4 = ${(a4 * modInverse) % m4}");
  } else {
    print("Modular inverse of $a4 mod $m4 does not exist (GCD != 1)");
  }

  print("\n=== Case with No Modular Inverse ===");
  int a5 = 6;
  int m5 = 9;
  List<int> extResult2 = extendedGCD(a5, m5);
  print("GCD of $a5 and $m5 = ${extResult2[0]}");
  if (extResult2[0] != 1) {
    print("Modular inverse of $a5 mod $m5 does not exist because GCD($a5, $m5) = ${extResult2[0]} ≠ 1");
  }
}

