@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String barcode) {
  if (barcode.isEmpty) return <int>{};
  Map<int, int> first = {};
  Map<int, int> last = {};
  for (int i = 0; i < barcode.length; i++) {
    int d = int.parse(barcode[i]);
    first.putIfAbsent(d, () => i);
    last[d] = i;
  }
  Map<int, int> spans = {};
  int maxSpan = -1;
  for (int d in first.keys) {
    int span = last[d]! - first[d]!;
    spans[d] = span;
    if (span > maxSpan) {
      maxSpan = span;
    }
  }
  Set<int> result = <int>{};
  for (int d in spans.keys) {
    if (spans[d] == maxSpan) {
      result.add(d);
    }
  }
  return result;
}

