import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> preorder) {
  List<int>? parse(List<int> list, int start) {
    if (start >= list.length) return null;
    int val = list[start];
    if (val >= 0) {
      return [start + 1, val];
    }
    int parentSize = -val;
    List<int>? left = parse(list, start + 1);
    if (left == null) return null;
    List<int>? right = parse(list, left[0]);
    if (right == null) return null;
    if (left[1] + right[1] == parentSize) {
      return [right[0], parentSize];
    }
    return null;
  }
  var result = parse(preorder, 0);
  return result != null && result[0] == preorder.length;
}

