import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String dna, int maxSegmentLength) {
  int n = dna.length;
  if (n == 0) {
    return 0;
  }

  String complement(String c) {
    switch (c) {
      case 'A':
        return 'T';
      case 'T':
        return 'A';
      case 'C':
        return 'G';
      default:
        return 'C';
    }
  }

  const int inf = 1 << 30;
  List<List<int>> cost = List.generate(
    n,
    (_) => List.filled(n, inf),
  );

  for (int len = 2; len <= maxSegmentLength && len <= n; len += 2) {
    for (int start = 0; start + len <= n; start++) {
      int end = start + len - 1;
      int mismatches = 0;

      for (int left = start, right = end; left < right; left++, right--) {
        if (complement(dna[left]) != dna[right]) {
          mismatches++;
        }
      }

      cost[start][end] = mismatches;
    }
  }

  List<int> dp = List.filled(n + 1, inf);
  dp[0] = 0;

  for (int i = 0; i < n; i++) {
    if (dp[i] == inf) {
      continue;
    }

    for (int len = 2; len <= maxSegmentLength && i + len <= n; len += 2) {
      int end = i + len - 1;
      if (cost[i][end] != inf) {
        int nextValue = dp[i] + cost[i][end];
        if (nextValue < dp[i + len]) {
          dp[i + len] = nextValue;
        }
      }
    }
  }

  return dp[n] == inf ? -1 : dp[n];
}

