import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {


  const int geneLength      = 32;      
  const int populationSize  = 50;      
  const int maxGenerations  = 200;     
  const double crossoverRate= 0.7;     
  const double mutationRate = 0.01;    
  const int tournamentSize  = 3;       

  final rng = Random(0);

  List<int> randomChromosome() =>
      List<int>.generate(geneLength, (_) => rng.nextBool() ? 1 : 0);

  int fitness(List<int> c) =>                       
      c.fold<int>(0, (sum, bit) => sum + bit);

  List<int> tournamentSelect(List<List<int>> pop) {

    List<List<int>> contenders = List.generate(
        tournamentSize, (_) => pop[rng.nextInt(pop.length)]);
    contenders.sort((a, b) => fitness(b).compareTo(fitness(a)));
    return contenders.first;
  }

  List<int> crossover(List<int> p1, List<int> p2) {
    if (rng.nextDouble() > crossoverRate) return List<int>.from(p1);
    int point = rng.nextInt(geneLength - 1) + 1;  
    return List<int>.from(p1.take(point))..addAll(p2.skip(point));
  }

  List<int> mutate(List<int> c) => List<int>.generate(
      geneLength, (i) => rng.nextDouble() < mutationRate ? 1 - c[i] : c[i]);

  List<List<int>> population =
      List<List<int>>.generate(populationSize, (_) => randomChromosome());

  for (int gen = 0; gen < maxGenerations; gen++) {

    population.sort((a, b) => fitness(b).compareTo(fitness(a)));
    int bestFit = fitness(population.first);

    print('Generation $gen | Best fitness: $bestFit'
        ' | Chromosome: ${population.first.join()}');

    if (bestFit == geneLength) break;

    List<List<int>> nextPop = [];

    nextPop.add(population.first);

    while (nextPop.length < populationSize) {

      List<int> parent1 = tournamentSelect(population);
      List<int> parent2 = tournamentSelect(population);

      List<int> child = mutate(crossover(parent1, parent2));

      nextPop.add(child);
    }
    population = nextPop;
  }
}

