    if (digits[mid] < target) {
      left = mid + 1;
    } else {
      if (digits[mid] == target) first = mid;
      right = mid - 1;
    }
  }
  left = 0;
  right = digits.length - 1;
  while (left <= right) {
    int mid = (left + right) ~/ 2;
    if (digits[mid] > target) {
      right = mid - 1;
    } else {
      if (digits[mid] == target) last = mid;
      left = mid + 1;
    }
  }
  return first == -1 ? {-1} : {first, last};
}

