@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String row, String target, int minLength, int maxLength, int minGap) {
  int count = 0;
  int n = row.length;
  int i = 0;
  while (i < n) {
    if (row[i] == target) {
      int start = i;
      while (i < n && row[i] == target) i++;
      int len = i - start;
      if (len >= minLength && len <= maxLength) {
        int spacesBefore = 0, j = start - 1;
        while (j >= 0 && row[j] == ' ') { spacesBefore++; j--; }
        bool validPrefix = (start == 0) || (spacesBefore >= minGap);
        int spacesAfter = 0, k = i;
        while (k < n && row[k] == ' ') { spacesAfter++; k++; }
        bool validSuffix = (i == n) || (spacesAfter >= minGap);
        if (validPrefix && validSuffix) count++;
      }
    } else {
      i++;
    }
  }
  return count;
}

