@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String path) {
  if (path.isEmpty) return false;
  List<String> tokens = path.split('-');
  List<int> files = [];
  List<int> ranks = [];
  for (String t in tokens) {
    if (t.length != 2) return false;
    int f = t.codeUnitAt(0) - 'a'.codeUnitAt(0);
    int r = t.codeUnitAt(1) - '1'.codeUnitAt(0);
    if (f < 0 || f > 7 || r < 0 || r > 7) return false;
    files.add(f);
    ranks.add(r);
  }
  for (int i = 1; i < files.length; i++) {
    int df = (files[i] - files[i - 1]).abs();
    int dr = (ranks[i] - ranks[i - 1]).abs();
    if (!((df == 1 && dr == 2) || (df == 2 && dr == 1))) return false;
  }
  return true;
}

