@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> timetable) {
  if (timetable.isEmpty) return {};
  int left = 0;
  int maxCount = 0;
  int bestLeft = 0;
  int bestRight = 0;
  for (int right = 0; right < timetable.length; right++) {
    while (timetable[right] - timetable[left] > 60) {
      left++;
    }
    int count = right - left + 1;
    if (count > maxCount) {
      maxCount = count;
      bestLeft = left;
      bestRight = right;
    }
  }
  return timetable.sublist(bestLeft, bestRight + 1).toSet();
}

