import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> keys, int bucketCount) {
  int asciiSum(String s) {
    int sum = 0;
    for (int i = 0; i < s.length; i++) {
      sum += s.codeUnitAt(i);
    }
    return sum;
  }

  Map<int, List<String>> buckets = {};
  for (int i = 0; i < bucketCount; i++) {
    buckets[i] = [];
  }

  for (String key in keys) {
    int hash = asciiSum(key) % bucketCount;
    buckets[hash]!.add(key);
  }

  Map<String, int> result = {};

  for (int i = 0; i < bucketCount; i++) {
    List<String> bucketKeys = buckets[i]!;
    if (bucketKeys.isEmpty) continue;
    if (bucketKeys.length == 1) {
      result['bucket_$i'] = 1;
    } else {
      int newBucketCount = bucketCount * 2;
      Map<int, int> subBucketCounts = {};
      for (String key in bucketKeys) {
        int newHash = asciiSum(key) % newBucketCount;
        subBucketCounts[newHash] = (subBucketCounts[newHash] ?? 0) + 1;
      }
      for (var entry in subBucketCounts.entries) {
        result['bucket_${i}_${entry.key}'] = entry.value;
      }
    }
  }

  return result;
}

