import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final List<List<double>> dist = [
    [0, 10, 15, 20],
    [10, 0, 35, 25],
    [15, 35, 0, 30],
    [20, 25, 30, 0],
  ];

  final int n = dist.length;
  if (n == 0) {
    print('No cities provided.');
    return;
  }


  final List<int> cities = List<int>.generate(n - 1, (i) => i + 1);

  double bestCost = double.infinity;
  List<int> bestTour = [];

  void permute(List<int> prefix, List<int> remaining) {
    if (remaining.isEmpty) {

      final tour = <int>[0, ...prefix, 0];
      double cost = 0;
      for (var i = 0; i < tour.length - 1; i++) {
        cost += dist[tour[i]][tour[i + 1]];
      }
      if (cost < bestCost) {
        bestCost = cost;
        bestTour = List<int>.from(tour);
      }
      return;
    }

    for (var i = 0; i < remaining.length; i++) {
      final nextPrefix = List<int>.from(prefix)..add(remaining[i]);
      final nextRemaining = List<int>.from(remaining)..removeAt(i);
      permute(nextPrefix, nextRemaining);
    }
  }

  permute([], cities);

  print('Best tour:  ${bestTour.join(' -> ')}');
  print('Total cost: ${bestCost.toStringAsFixed(2)}');
}

