double fn0(String bins) {
  if (bins.isEmpty) {
    return 0.0;
  }
  List<String> parts = bins.split(',');
  double total = 0.0;
  int count = 0;
  for (String part in parts) {
    String token = part.trim();
    if (token == 'weak') total += 0.0;
    if (token == 'medium') total += 0.5;
    if (token == 'strong') total += 1.0;
    if (token == 'weak' || token == 'medium' || token == 'strong') count++;
  }
  return count == 0 ? 0.0 : total / count;
}

