bool fn0(List<int> sortedDurations, int target) {

  int lo = 0;
  int hi = sortedDurations.length - 1;
  while (lo <= hi) {
    int mid = (lo + hi) ~/ 2;
    if (sortedDurations[mid] == target) return true;
    if (sortedDurations[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return false;
}

