import 'dart:convert';
import 'dart:async';

/// A complete Dart program demonstrating async* streams.
/// The main function listens to a stream generated by an async* local function,
/// which yields numbers with delays.

@pragma('vm:never-inline')
@pragma('vm:entry-point')
Future<void> fn0() async {

  Stream<int> generateNumbers() async* {
    for (int i = 1; i <= 5; i++) {

      await Future.delayed(Duration(seconds: 1));
      yield i;
    }
  }

  print('Starting to listen to the stream...');
  await for (var number in generateNumbers()) {
    print('Received: $number');
  }
  print('Stream completed.');
}

