import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<int> voteTally) {
  if (voteTally.isEmpty) return "impossible";
  final sorted = List<int>.from(voteTally)..sort();
  int total = 0;
  for (int v in sorted) total += v;
  if (total == 0) return "impossible";
  final prefix = [0];
  for (int i = 0; i < sorted.length; i++) {
    prefix.add(prefix.last + sorted[i]);
  }
  int n = sorted.length;
  int low = 0, high = n;
  while (low < high) {
    int mid = (low + high + 1) ~/ 2;
    if (2 * prefix[mid] < total) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  int needed = n - low;
  return needed.toString();
}

