List<int> fn0(List<int> quantities) {


  if (quantities.isEmpty) return <int>[];
  int g = 0;
  for (final q in quantities) {
    int a = g;
    int b = q;
    while (b != 0) {
      final t = a % b;
      a = b;
      b = t;
    }
    g = a;
  }
  if (g == 0) return <int>[];
  final small = <int>[];
  final large = <int>[];
  for (int d = 1; d * d <= g; d++) {
    if (g % d == 0) {
      small.add(d);
      final other = g ~/ d;
      if (other != d) large.add(other);
    }
  }
  return small + large.reversed.toList();
}

