List<String> fn0(List<String> actions) {
  List<List<int>> roundStack = [];
  List<String> history = [];
  List<int> currentRound = [];
  for (String action in actions) {
    if (action.startsWith('roll:')) {
      int value = int.parse(action.substring(5));
      currentRound.add(value);
    } else if (action == 'undo') {
      if (currentRound.isNotEmpty) {
        currentRound.removeLast();
      }
    } else if (action == 'endRound') {
      if (currentRound.isNotEmpty) {
        roundStack.add(List<int>.from(currentRound));
        history.add('Round ${roundStack.length}: ${currentRound.join(", ")}');
        currentRound = [];
      }
    }
  }
  return history;
}

