import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(int totalCents, int people, int roundBase) {


  if (people <= 0) return false;
  if (roundBase <= 0) return false;
  if (totalCents < 0) return false;



  if (roundBase == 1) {
    int perShare = (2 * totalCents + people) ~/ (2 * people);
    return people * perShare == totalCents;
  }



  int roundToBase(int x) {
    return ((2 * x + roundBase) ~/ (2 * roundBase)) * roundBase;
  }



  int numerator = 2 * totalCents + people * roundBase;
  int denominator = 2 * people * roundBase;
  int perShare = roundBase * (numerator ~/ denominator);


  int reconstructed = people * perShare;
  int roundedTotal = roundToBase(totalCents);
  return reconstructed == roundedTotal;
}

