import 'dart:async';
import 'dart:convert';
import 'dart:core';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int n = 4;

  List<List<int>> dist = [
    [0, 29, 20, 21],
    [29, 0, 15, 17],
    [20, 15, 0, 28],
    [21, 17, 28, 0],
  ];

  List<int> cities = List.generate(n, (i) => i);

  int bestCost = 1 << 30;  
  List<int> bestRoute = [];

  void swap(List<int> arr, int i, int j) {
    final tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }

  void permute(List<int> arr, int l) {
    if (l == arr.length - 1) {

      int cost = 0;
      for (int i = 0; i < arr.length - 1; i++) {
        cost += dist[arr[i]][arr[i + 1]];
      }
      cost += dist[arr[arr.length - 1]][arr[0]];

      if (cost < bestCost) {
        bestCost = cost;
        bestRoute = List.from(arr);
      }
    } else {
      for (int i = l; i < arr.length; i++) {
        swap(arr, l, i);
        permute(arr, l + 1);
        swap(arr, l, i);
      }
    }
  }

  permute(cities, 0);

  String routeStr = bestRoute.join(' -> ') + ' -> ${bestRoute[0]}';
  print('Best route: $routeStr');
  print('Minimum cost: $bestCost');
}

