import 'dart:async';
import 'dart:convert';
import 'dart:collection';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int n = 4;
  Map<int, List<int>> graph = {
    0: [1],
    1: [2],
    2: [3],
    3: [1],
  };

  List<int> disc = List.filled(n, -1);
  List<int> low = List.filled(n, -1);

  List<int> stack = [];
  Set<int> onStack = HashSet<int>();

  int time = 0;

  List<List<int>> sccs = [];

  void dfs(int u) {
    disc[u] = low[u] = time++;
    stack.add(u);
    onStack.add(u);

    for (int v in graph[u] ?? []) {
      if (disc[v] == -1) {
        dfs(v);
        low[u] = low[u] < low[v] ? low[u] : low[v];
      } else if (onStack.contains(v)) {
        low[u] = low[u] < disc[v] ? low[u] : disc[v];
      }
    }

    if (low[u] == disc[u]) {
      List<int> scc = [];
      while (true) {
        int v = stack.removeLast();
        onStack.remove(v);
        scc.add(v);
        if (v == u) break;
      }
      sccs.add(scc);
    }
  }

  for (int i = 0; i < n; i++) {
    if (disc[i] == -1) {
      dfs(i);
    }
  }

  print('Strongly Connected Components:');
  for (var scc in sccs) {
    print(scc);
  }
}

