import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(int rows, int cols, List<String> operations) {
  var grid = List.generate(rows, (_) => List.filled(cols, 0));
  var stack = <List<int>>[];
  for (var op in operations) {
    var parts = op.split(' ');
    if (parts[0] == 'WET' || parts[0] == 'DRY') {
      if (parts.length != 3) continue;
      var r = int.tryParse(parts[1]);
      var c = int.tryParse(parts[2]);
      if (r == null || c == null) continue;
      if (r >= 0 && r < rows && c >= 0 && c < cols) {
        stack.add([r, c, grid[r][c]]);
        var delta = parts[0] == 'WET' ? 1 : -1;
        var newVal = grid[r][c] + delta;
        if (newVal < 0) newVal = 0;
        if (newVal > 9) newVal = 9;
        grid[r][c] = newVal;
      }
    } else if (parts[0] == 'UNDO') {
      if (stack.isNotEmpty) {
        var last = stack.removeLast();
        grid[last[0]][last[1]] = last[2];
      }
    }
  }
  return grid.map((row) => row.join(',')).join(';');
}

