@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> digits) {
  if (digits.isEmpty) return false;
  final nonZero = digits.where((d) => d != 0).toList();
  if (nonZero.isEmpty) return false;
  List<List<int>> runs = [];
  List<int> currentRun = [nonZero[0]];
  for (int i = 1; i < nonZero.length; i++) {
    if (nonZero[i] == nonZero[i - 1]) {
      currentRun.add(nonZero[i]);
    } else {
      runs.add(currentRun);
      currentRun = [nonZero[i]];
    }
  }
  runs.add(currentRun);
  int sum = 0;
  for (var run in runs) {
    sum += run.length * run[0];
  }
  return sum % 11 == 0 && runs.length % 2 == 1;
}

