import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> arr = [4, 2, 2, 8, 3, 3, 1, 7, 0, 9, 5, 1, 6, 4, 3, 8, 2, 7, 5, 4];

  print('Original array: $arr');

  int minVal = arr.reduce((a, b) => a < b ? a : b);
  int maxVal = arr.reduce((a, b) => a > b ? a : b);
  int range = maxVal - minVal + 1;

  List<int> count = List.filled(range, 0);

  for (int i = 0; i < arr.length; i++) {
    count[arr[i] - minVal]++;
  }

  for (int i = 1; i < count.length; i++) {
    count[i] += count[i - 1];
  }

  List<int> output = List.filled(arr.length, 0);


  for (int i = arr.length - 1; i >= 0; i--) {
    int element = arr[i];
    int countIndex = element - minVal;
    output[count[countIndex] - 1] = element;
    count[countIndex]--;
  }

  for (int i = 0; i < arr.length; i++) {
    arr[i] = output[i];
  }

  print('Sorted array: $arr');

  List<int> arr2 = [-3, 5, -1, 0, 2, -3, 4, 1, -2, 3, 0, -1, 2];
  print('\nOriginal array with negatives: $arr2');

  minVal = arr2.reduce((a, b) => a < b ? a : b);
  maxVal = arr2.reduce((a, b) => a > b ? a : b);
  range = maxVal - minVal + 1;

  count = List.filled(range, 0);

  for (int i = 0; i < arr2.length; i++) {
    count[arr2[i] - minVal]++;
  }

  for (int i = 1; i < count.length; i++) {
    count[i] += count[i - 1];
  }

  output = List.filled(arr2.length, 0);

  for (int i = arr2.length - 1; i >= 0; i--) {
    int element = arr2[i];
    int countIndex = element - minVal;
    output[count[countIndex] - 1] = element;
    count[countIndex]--;
  }

  for (int i = 0; i < arr2.length; i++) {
    arr2[i] = output[i];
  }

  print('Sorted array with negatives: $arr2');

  List<int> digits = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5, 8, 9, 7, 9, 3, 2, 3, 8, 4];
  print('\nOriginal digits array: $digits');

  count = List.filled(10, 0);

  for (int i = 0; i < digits.length; i++) {
    count[digits[i]]++;
  }

  int index = 0;
  for (int i = 0; i < 10; i++) {
    while (count[i] > 0) {
      digits[index++] = i;
      count[i]--;
    }
  }

  print('Sorted digits array: $digits');

  print('\nCounting sort is O(n + k) where n is the number of elements');
  print('and k is the range of input. It\'s very efficient for small ranges!');
}

