import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(int payloadSize, int flags, int optionSize) {
  int count = 0;
  int f = flags;
  while (f != 0) {
    count += (f & 1);
    f >>= 1;
  }
  int overhead = count * optionSize;
  int total = payloadSize + overhead;
  if (total == 0) return 0.0;
  return overhead / total;
}

