  for (final ch in input.split('')) {
    if (s == 0) {
      if (ch == '#') { c.update('wall', (v) => v + 1); s = 1; }
      else if (ch == '.') { c.update('path', (v) => v + 1); s = 1; }
      else if (ch == 'S') { c.update('start', (v) => v + 1); s = 1; }
      else if (ch == 'E') { c.update('end', (v) => v + 1); s = 1; }
    } else {
      if (ch == ';') s = 0;
      else if (ch == '#') c.update('wall', (v) => v + 1);
      else if (ch == '.') c.update('path', (v) => v + 1);
      else if (ch == 'S') c.update('start', (v) => v + 1);
      else if (ch == 'E') c.update('end', (v) => v + 1);
    }
  }
  return c;
}

