import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> requests, int overhead) {
  int n = requests.length;
  if (n == 0) return [];
  const int INF = 1000000000;
  List<int> dp = List.filled(n + 1, INF);
  List<int> parent = List.filled(n + 1, -1);
  dp[0] = 0;
  for (int i = 1; i <= n; i++) {
    int maxF = requests[i - 1];
    int minF = requests[i - 1];
    for (int j = i - 1; j >= 0; j--) {
      if (requests[j] > maxF) maxF = requests[j];
      if (requests[j] < minF) minF = requests[j];
      int cost = dp[j] + (maxF - minF) + overhead;
      if (cost < dp[i]) {
        dp[i] = cost;
        parent[i] = j;
      }
    }
  }
  List<int> batches = [];
  int curr = n;
  while (curr > 0) {
    batches.add(curr - parent[curr]);
    curr = parent[curr];
  }
  return batches.reversed.toList();
}

