@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> moisture, int target) {
  if (moisture.isEmpty || target < 0) return false;
  final int n = moisture.length;
  int firstEnd = -1;
  int sum = 0;
  int left = 0;
  for (int right = 0; right < n; right++) {
    sum += moisture[right];
    while (sum > target && left <= right) {
      sum -= moisture[left];
      left++;
    }
    if (sum == target) {
      firstEnd = right;
      break;
    }
  }
  if (firstEnd == -1) return false;
  sum = 0;
  left = firstEnd + 1;
  for (int right = firstEnd + 1; right < n; right++) {
    sum += moisture[right];
    while (sum > target && left <= right) {
      sum -= moisture[left];
      left++;
    }
    if (sum == target) return true;
  }
  return false;
}

