import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> moistureGrid) {
  List<int> stack = [];
  int balanced = 0;
  int maxDepth = 0;
  int currentDepth = 0;
  for (List<int> row in moistureGrid) {
    for (int level in row) {
      if (stack.isNotEmpty && stack.last == level) {
        stack.removeLast();
        balanced++;
        currentDepth--;
      } else {
        stack.add(level);
        currentDepth++;
        if (currentDepth > maxDepth) maxDepth = currentDepth;
      }
    }
  }
  return {'balancedZones': balanced, 'maxDepth': maxDepth, 'remaining': stack.length};
}

