@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(int ax1, int ay1, int ax2, int ay2, int bx1, int by1, int bx2, int by2) {
  int leftA = ax1;
  int rightA = ax2;
  if (leftA > rightA) {
    leftA = ax2;
    rightA = ax1;
  }
  int bottomA = ay1;
  int topA = ay2;
  if (bottomA > topA) {
    bottomA = ay2;
    topA = ay1;
  }
  int leftB = bx1;
  int rightB = bx2;
  if (leftB > rightB) {
    leftB = bx2;
    rightB = bx1;
  }
  int bottomB = by1;
  int topB = by2;
  if (bottomB > topB) {
    bottomB = by2;
    topB = by1;
  }
  int overlapLeft = leftA > leftB ? leftA : leftB;
  int overlapRight = rightA < rightB ? rightA : rightB;
  int overlapBottom = bottomA > bottomB ? bottomA : bottomB;
  int overlapTop = topA < topB ? topA : topB;
  if (overlapLeft >= overlapRight || overlapBottom >= overlapTop) {
    return 0.0;
  }
  return ((overlapRight - overlapLeft) * (overlapTop - overlapBottom)).toDouble();
}

