List<int> fn0(List<int> entries) {
  final result = <int>[];
  int pos = 0;
  void parse(int depth) {
    while (pos < entries.length) {
      final token = entries[pos];
      if (token == 0) {
        pos++;
        parse(depth + 1);
      } else {
        final sign = (depth % 2 == 0) ? 1 : -1;
        result.add(token * sign);
        pos++;
      }
    }
  }
  parse(0);
  return result;
}

