String fn0(List<List<int>> rounds) {
  if (rounds.isEmpty) {
    return "No rounds";
  }
  Map<String, int> freq = {};
  for (var round in rounds) {
    int sum = 0;
    Set<int> distinct = {};
    for (var die in round) {
      sum += die;
      distinct.add(die);
    }
    String key = "$sum:${distinct.length}";
    freq[key] = (freq[key] ?? 0) + 1;
  }
  String bestKey = "";
  int bestCount = -1;
  int bestSum = -1;
  int bestDistinct = -1;
  freq.forEach((key, count) {
    var parts = key.split(":");
    int sum = int.parse(parts[0]);
    int distinct = int.parse(parts[1]);
    if (count > bestCount ||
        (count == bestCount && sum > bestSum) ||
        (count == bestCount && sum == bestSum && distinct > bestDistinct)) {
      bestCount = count;
      bestSum = sum;
      bestDistinct = distinct;
      bestKey = key;
    }
  });
  return "Most common: sum=$bestSum, distinct=$bestDistinct, count=$bestCount";
}

