@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String script) {
  List<int> counts = [0, 0, 0, 0];
  String key = "";
  String state = "IDLE";
  for (int i = 0; i < script.length; i++) {
    String c = script[i];
    if (state == "IDLE") {
      if (c == "\\") state = "ESCAPE";
      else if (c == ".") counts = [0, 0, 0, 0];
      else if (c != " ") { state = "KEY"; key = c; }
    } else if (state == "KEY") {
      if (c == "\\") state = "ESCAPE";
      else if (c == " ") { counts[key.length % 4]++; state = "IDLE"; key = ""; }
      else if (c == ".") { counts = [0, 0, 0, 0]; state = "IDLE"; key = ""; }
      else key += c;
    } else if (state == "ESCAPE") {
      key += c;
      state = "KEY";
    }
  }
  if ((state == "KEY" || state == "ESCAPE") && key.isNotEmpty) {
    counts[key.length % 4]++;
  }
  Set<int> res = {};
  for (int v in counts) {
    if (v > 0) res.add(v);
  }
  return res;
}

