import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<List<int>> intervals) {
  if (intervals.isEmpty) return 0;
  var sorted = List.of(intervals)..sort((a, b) => a[0].compareTo(b[0]));
  int total = 0;
  int curStart = sorted[0][0];
  int curEnd = sorted[0][1];
  for (int i = 1; i < sorted.length; i++) {
    int s = sorted[i][0];
    int e = sorted[i][1];
    if (s <= curEnd) {
      if (e > curEnd) curEnd = e;
    } else {
      total += curEnd - curStart + 1;
      curStart = s;
      curEnd = e;
    }
  }
  total += curEnd - curStart + 1;
  return total;
}

