Set<int> fn0(List<List<int>> gameRounds) {
  if (gameRounds.isEmpty) return {};
  var indexed = <Map<String, dynamic>>[];
  for (var i = 0; i < gameRounds.length; i++) {
    var dice = List<int>.from(gameRounds[i]);
    dice.sort((a, b) => b.compareTo(a));
    indexed.add({'idx': i, 'dice': dice, 'sum': dice.fold(0, (a, b) => a + b)});
  }
  indexed.sort((a, b) {
    var da = a['dice'] as List<int>;
    var db = b['dice'] as List<int>;
    var sa = da.where((d) => d == 6).length;
    var sb = db.where((d) => d == 6).length;
    if (sa != sb) return sb.compareTo(sa);
    var suma = a['sum'] as int;
    var sumb = b['sum'] as int;
    if (suma != sumb) return sumb.compareTo(suma);
    for (var k = 0; k < da.length && k < db.length; k++) {
      if (da[k] != db[k]) return db[k].compareTo(da[k]);
    }
    return db.length.compareTo(da.length);
  });
  var result = <int>{};
  for (var i = 0; i < indexed.length; i++) {
    if (i == 0 || indexed[i]['sum'] != indexed[i - 1]['sum']) {
      result.add(indexed[i]['idx'] as int);
    }
  }
  return result;
}

