double fn0(String encoded) {






  if (encoded.isEmpty || encoded.length % 2 != 0) return 0.0;
  List<int> winners = [];
  for (int i = 0; i < encoded.length; i += 2) {
    int seed, count;
    try {
      seed = int.parse(encoded[i]);
      count = int.parse(encoded[i + 1]);
    } catch (_) {
      return 0.0;
    }
    if (seed < 1 || seed > 4 || count < 1) return 0.0;
    for (int j = 0; j < count; j++) {
      winners.add(seed);
      if (winners.length > 3) return 0.0; 
    }
  }
  if (winners.length != 3) return 0.0;
  int w1 = winners[0], w2 = winners[1], champion = winners[2];

  if ((w1 != 1 && w1 != 4) || (w2 != 2 && w2 != 3) || (champion != w1 && champion != w2)) {
    return 0.0;
  }
  int opponent1, opponent2;
  if (champion == w1) {

    opponent1 = (w1 == 1) ? 4 : 1; 
    opponent2 = w2;                
  } else { 
    opponent2 = w1;                
    opponent1 = (w2 == 2) ? 3 : 2; 
  }
  return (opponent1 + opponent2) / 2.0;
}

