import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String square) {
  int state = 0; 
  int file = -1, rank = -1;

  for (int i = 0; i < square.length; i++) {
    int code = square.codeUnitAt(i);

    if (state == 0) {
      if (code >= 97 && code <= 104) { 
        file = code - 97;
        state = 1;
      } else {
        return -1;
      }
    } else if (state == 1) {
      if (code >= 49 && code <= 56) { 
        rank = code - 49;
        state = 2;
      } else {
        return -1;
      }
    } else {
      return -1; 
    }
  }

  return (state == 2) ? (file + rank * 8) : -1;
}

