import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {
  List<int> p = [30, 35, 15, 5, 10, 20, 25]; 
  int n = p.length - 1;

  List<List<int>> m = List.generate(n, (_) => List.filled(n, 0));

  List<List<int>> s = List.generate(n, (_) => List.filled(n, 0));

  const int INF = 999999999;

  for (int l = 2; l <= n; l++) {
    for (int i = 0; i <= n - l; i++) {
      int j = i + l - 1;
      m[i][j] = INF;
      for (int k = i; k < j; k++) {
        int q = m[i][k] + m[k + 1][j] + p[i] * p[k + 1] * p[j + 1];
        if (q < m[i][j]) {
          m[i][j] = q;
          s[i][j] = k;
        }
      }
    }
  }

  print('Minimum cost: ${m[0][n - 1]}');

  String getParenthesis(int i, int j) {
    if (i == j) {
      return 'A${i + 1}';
    }
    return '(${getParenthesis(i, s[i][j])}${getParenthesis(s[i][j] + 1, j)})';
  }

  print('Optimal parenthesization: ${getParenthesis(0, n - 1)}');
}

