  final resultC = await completerC.future;
  print(resultC);

  final completerD = Completer.sync();
  completerD.complete('Immediate synchronous completion');
  print(await completerD.future);

  final completerE = Completer<String>();
  scheduleMicrotask(() => completerE.complete('Completed in a microtask'));
