import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<String> asciiRows, String target, int k) {
  Set<int> result = {};
  if (k <= 0) return result;
  int t = target.codeUnitAt(0);
  for (int i = 0; i < asciiRows.length; i++) {
    String row = asciiRows[i];
    if (row.isEmpty) continue;
    int lo = 0, hi = row.length;
    while (lo < hi) {
      int mid = (lo + hi) ~/ 2;
      if (row.codeUnitAt(mid) < t) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    int first = lo;
    lo = 0;
    hi = row.length;
    while (lo < hi) {
      int mid = (lo + hi) ~/ 2;
      if (row.codeUnitAt(mid) <= t) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    int last = lo - 1;
    if (first <= last && (last - first + 1) == k) {
      result.add(i);
    }
  }
  return result;
}

