@pragma('vm:entry-point')
Map<String, int> fn0(List<int> readings) {
  if (readings.isEmpty) {
    return {'longestRiseRun': 0, 'totalRise': 0};
  }
  int currentRun = 1;
  int longestRun = 1;
  int totalRise = 0;
  for (int i = 1; i < readings.length; i++) {
    if (readings[i] >= readings[i - 1]) {
      currentRun++;
      totalRise += readings[i] - readings[i - 1];
    } else {
      currentRun = 1;
    }
    if (currentRun > longestRun) {
      longestRun = currentRun;
    }
  }
  return {'longestRiseRun': longestRun, 'totalRise': totalRise};
}

