@pragma('vm:entry-point')
int fn0(List<int> sortedPixels, int threshold) {
  int lo = 0;
  int hi = sortedPixels.length - 1;
  int result = -1;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (sortedPixels[mid] >= threshold) {
      result = mid;
      hi = mid - 1;
    } else {
      lo = mid + 1;
    }
  }
  return result;
}

