import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<String> pixels) {
  final sorted = List<String>.from(pixels);
  sorted.sort((a, b) {
    final pa = a.split(',');
    final ra = int.parse(pa[0]);
    final ga = int.parse(pa[1]);
    final ba = int.parse(pa[2]);
    final maxA = ra > ga ? (ra > ba ? ra : ba) : (ga > ba ? ga : ba);
    final minA = ra < ga ? (ra < ba ? ra : ba) : (ga < ba ? ga : ba);
    final chromaA = maxA - minA;
    final lumaA = 299 * ra + 587 * ga + 114 * ba;

    final pb = b.split(',');
    final rb = int.parse(pb[0]);
    final gb = int.parse(pb[1]);
    final bb = int.parse(pb[2]);
    final maxB = rb > gb ? (rb > bb ? rb : bb) : (gb > bb ? gb : bb);
    final minB = rb < gb ? (rb < bb ? rb : bb) : (gb < bb ? gb : bb);
    final chromaB = maxB - minB;
    final lumaB = 299 * rb + 587 * gb + 114 * bb;

    if (chromaA != chromaB) {
      return chromaB.compareTo(chromaA);
    }
    if (lumaA != lumaB) {
      return lumaA.compareTo(lumaB);
    }
    return a.compareTo(b);
  });
  return sorted.join(';');
}

