import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {


  List<int> coins1 = [1, 5, 10, 25];
  int amount1 = 41;

  int minCoins(List<int> coins, int amount) {
    if (amount == 0) return 0;

    List<int> dp = List.filled(amount + 1, amount + 1);
    dp[0] = 0;

    for (int i = 1; i <= amount; i++) {
      for (int coin in coins) {
        if (coin <= i) {
          dp[i] = dp[i] < dp[i - coin] + 1 ? dp[i] : dp[i - coin] + 1;
        }
      }
    }

    return dp[amount] > amount ? -1 : dp[amount];
  }

  List<int> getCoinsUsed(List<int> coins, int amount) {
    if (amount == 0) return [];

    List<int> dp = List.filled(amount + 1, amount + 1);
    List<int> coinUsed = List.filled(amount + 1, -1);
    dp[0] = 0;

    for (int i = 1; i <= amount; i++) {
      for (int coin in coins) {
        if (coin <= i && dp[i - coin] + 1 < dp[i]) {
          dp[i] = dp[i - coin] + 1;
          coinUsed[i] = coin;
        }
      }
    }

    if (dp[amount] > amount) return [];

    List<int> result = [];
    int current = amount;
    while (current > 0 && coinUsed[current] != -1) {
      result.add(coinUsed[current]);
      current -= coinUsed[current];
    }

    return result;
  }

  print('Coin Change Problem Implementation');
  print('=' * 40);

  int result1 = minCoins(coins1, amount1);
  List<int> coinsUsed1 = getCoinsUsed(coins1, amount1);
  print('Coins available: $coins1');
  print('Target amount: $amount1');
  print('Minimum coins needed: $result1');
  print('Coins used: $coinsUsed1');
  print('');

  List<int> coins2 = [2, 5, 10];
  int amount2 = 11;
  int result2 = minCoins(coins2, amount2);
  List<int> coinsUsed2 = getCoinsUsed(coins2, amount2);
  print('Coins available: $coins2');
  print('Target amount: $amount2');
  print('Minimum coins needed: $result2');
  print('Coins used: $coinsUsed2');
  print('');

  List<int> coins3 = [3];
  int amount3 = 2;
  int result3 = minCoins(coins3, amount3);
  List<int> coinsUsed3 = getCoinsUsed(coins3, amount3);
  print('Coins available: $coins3');
  print('Target amount: $amount3');
  print('Minimum coins needed: ${result3 == -1 ? "Impossible" : result3}');
  print('Coins used: ${coinsUsed3.isEmpty ? "No solution" : coinsUsed3}');
  print('');

  List<int> coins4 = [1, 7, 10];
