@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> voteGrid) {
  if (voteGrid.isEmpty) return 0.0;
  int rows = voteGrid.length;
  int cols = voteGrid[0].length;
  if (cols == 0) return 0.0;
  int swingCount = 0;
  int total = rows * cols;
  List<List<int>> dirs = [[0,1],[1,0],[0,-1],[-1,0]];
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      bool isSwing = false;
      for (var d in dirs) {
        int ni = i + d[0];
        int nj = j + d[1];
        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols &&
            voteGrid[i][j] * voteGrid[ni][nj] < 0) {
          isSwing = true;
          break;
        }
      }
      if (isSwing) swingCount++;
    }
  }
  return swingCount / total;
}

