List<String> fn0(String log) {
  int state = 0;
  String level = "", message = "", userId = "";
  for (int i = 0; i < log.length; i++) {
    int code = log.codeUnitAt(i);
    if (state == 0 && code == 91) state = 1;
    else if (state == 0) return [];
    else if (state == 1 && code == 93) {
      if (!["INFO", "WARN", "ERROR", "FATAL"].contains(level)) return [];
      state = 2;
    } else if (state == 1) level += String.fromCharCode(code);
    else if (state == 2 && code == 32 && i + 1 < log.length && log.codeUnitAt(i + 1) == 34) {
      state = 3; i++;
    } else if (state == 2) return [];
    else if (state == 3 && code == 34) state = 4;
    else if (state == 3) message += String.fromCharCode(code);
    else if (state == 4 && code == 32 && i + 1 < log.length) state = 5;
    else if (state == 4) return [];
    else if (state == 5 && (code >= 48 && code <= 57 || code >= 65 && code <= 90 || code >= 97 && code <= 122)) {
      userId += String.fromCharCode(code);
    } else if (state == 5) return [];
  }
  return state == 5 && userId.isNotEmpty ? [level, message, userId] : [];
}

