import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> intervals) {
  if (intervals.isEmpty) return [];
  int n = intervals.length;
  List<int> parent = List.generate(n, (i) => i);
  List<int> rank = List.filled(n, 0);
  int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
  void union(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return;
    if (rank[ra] < rank[rb]) { parent[ra] = rb; }
    else if (rank[ra] > rank[rb]) { parent[rb] = ra; }
    else { parent[rb] = ra; rank[ra]++; }
  }
  Map<int, int> primeToIdx = {};
  for (int i = 0; i < n; i++) {
    int v = intervals[i];
    if (v <= 1) continue;
    for (int d = 2; d * d <= v; d++) {
      if (v % d == 0) {
        if (primeToIdx.containsKey(d)) union(i, primeToIdx[d]!);
        else primeToIdx[d] = i;
        while (v % d == 0) v ~/= d;
      }
    }
    if (v > 1) {
      if (primeToIdx.containsKey(v)) union(i, primeToIdx[v]!);
      else primeToIdx[v] = i;
    }
  }
  Map<int, int> sizes = {};
  for (int i = 0; i < n; i++) {
    int r = find(i);
    sizes[r] = (sizes[r] ?? 0) + 1;
  }
  List<int> res = sizes.values.toList();
  res.sort((a, b) => b.compareTo(a));
  return res;
}

