import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<List<int>> moisture) {
  if (moisture.isEmpty || moisture[0].isEmpty) return 0;
  int r = moisture.length;
  int c = moisture[0].length;

  List<List<List<int>>> dp = List.generate(
    r,
    (_) => List.generate(
      c,
      (_) => [-1000000000, -1000000000],
    ),
  );

  dp[0][0][0] = moisture[0][0];

  for (int i = 0; i < r; i++) {
    for (int j = 0; j < c; j++) {
      if (i == 0 && j == 0) continue;

      int val = moisture[i][j];

      if (i > 0 && dp[i - 1][j][0] != -1000000000) {
        dp[i][j][0] = dp[i][j][0] > dp[i - 1][j][0] + val
            ? dp[i][j][0]
            : dp[i - 1][j][0] + val;
      }
      if (j > 0 && dp[i][j - 1][0] != -1000000000) {
        dp[i][j][0] = dp[i][j][0] > dp[i][j - 1][0] + val
            ? dp[i][j][0]
            : dp[i][j - 1][0] + val;
      }

      if (i > 0 && dp[i - 1][j][1] != -1000000000) {
        dp[i][j][1] = dp[i][j][1] > dp[i - 1][j][1] + val
            ? dp[i][j][1]
            : dp[i - 1][j][1] + val;
      }
      if (j > 0 && dp[i][j - 1][1] != -1000000000) {
        dp[i][j][1] = dp[i][j][1] > dp[i][j - 1][1] + val
            ? dp[i][j][1]
            : dp[i][j - 1][1] + val;
      }

      if (i > 1 && dp[i - 2][j][0] != -1000000000) {
        dp[i][j][1] = dp[i][j][1] > dp[i - 2][j][0] + val
            ? dp[i][j][1]
            : dp[i - 2][j][0] + val;
      }
      if (j > 1 && dp[i][j - 2][0] != -1000000000) {
        dp[i][j][1] = dp[i][j][1] > dp[i][j - 2][0] + val
            ? dp[i][j][1]
            : dp[i][j - 2][0] + val;
      }
    }
  }

  int ans0 = dp[r - 1][c - 1][0];
  int ans1 = dp[r - 1][c - 1][1];
  return ans0 > ans1 ? ans0 : ans1;
}

