Map<String, int> fn0(String telemetry) {
  if (telemetry.isEmpty) return {};
  Map<String, int> counts = {};
  List<String> samples = telemetry.split('|');
  for (String sample in samples) {
    if (sample.isEmpty) continue;
    List<String> pairs = sample.split(',');
    for (String pair in pairs) {
      if (pair.isEmpty) continue;
      int eqIndex = pair.indexOf('=');
      if (eqIndex > 0) {
        String sensorId = pair.substring(0, eqIndex);
        counts[sensorId] = (counts[sensorId] ?? 0) + 1;
      }
    }
  }
  return counts;
}

