import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {
  const int INF = 1000000000;


  List<List<int>> dist = [
    [0,   5,  INF, 10],
    [INF, 0,   3,  INF],
    [INF, INF, 0,   1],
    [INF, INF, INF, 0],
  ];

  int n = dist.length;

  for (int k = 0; k < n; k++) {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        int throughK = dist[i][k] + dist[k][j];
        if (throughK < dist[i][j]) {
          dist[i][j] = throughK;
        }
      }
    }
  }

  print('All-pairs shortest paths:');
  for (int i = 0; i < n; i++) {
    List<String> row = dist[i]
        .map((d) => d >= INF ? 'INF' : d.toString())
        .toList();
    print(row.join('\t'));
  }
}

