import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<List<int>> zones) {



  if (zones.isEmpty) return 'area=0,overlap=0';
  final rects = <List<int>>[];
  var total = 0;
  for (final z in zones) {
    final x1 = z[0] < z[2] ? z[0] : z[2];
    final x2 = z[0] < z[2] ? z[2] : z[0];
    final y1 = z[1] < z[3] ? z[1] : z[3];
    final y2 = z[1] < z[3] ? z[3] : z[1];
    rects.add([x1, y1, x2, y2]);
    total += (x2 - x1) * (y2 - y1);
  }
  final xSet = <int>{};
  final ySet = <int>{};
  for (final r in rects) {
    xSet.add(r[0]);
    xSet.add(r[2]);
    ySet.add(r[1]);
    ySet.add(r[3]);
  }
  final xs = xSet.toList()..sort();
  final ys = ySet.toList()..sort();
  var union = 0;
  for (var i = 0; i + 1 < xs.length; i++) {
    for (var j = 0; j + 1 < ys.length; j++) {
      for (final r in rects) {
        if (r[0] <= xs[i] && xs[i + 1] <= r[2] && r[1] <= ys[j] && ys[j + 1] <= r[3]) {
          union += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
          break;
        }
      }
    }
  }
  final overlap = total - union;
  return 'area=$union,overlap=$overlap';
}

