@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String manifest) {
  if (manifest.isEmpty) return '';
  StringBuffer result = StringBuffer();
  int i = 0;
  int totalQty = 0;
  while (i < manifest.length - 1) {
    String numStr = '';
    while (i < manifest.length - 1 && manifest.codeUnitAt(i) >= 48 && manifest.codeUnitAt(i) <= 57) {
      numStr += manifest[i];
      i++;
    }
    if (numStr.isEmpty || i >= manifest.length - 1) return 'INVALIDCHECKSUM';
    int qty = int.parse(numStr);
    String item = manifest[i];
    if (item.codeUnitAt(0) < 65 || item.codeUnitAt(0) > 90) return 'INVALIDCHECKSUM';
    totalQty += qty;
    result.write(item * qty);
    i++;
  }
  int checkVal = totalQty % 26;
  String expectedCheck = String.fromCharCode(65 + checkVal);
  if (manifest[manifest.length - 1] != expectedCheck) return 'INVALIDCHECKSUM';
  return result.toString();
}

