import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(String readings) {
  int level = 0;
  int peaks = 0;
  int invalid = 0;

  for (int i = 0; i < readings.length; i++) {
    String ch = readings[i];
    if (ch == 'H') {
      level++;
      if (level >= 3) peaks++;
    } else if (ch == 'L') {
      if (level > 0) level--;
    } else if (ch != 'S') {
      invalid++;
    }
  }

