import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final fixed = List<int>.filled(5, 0, growable: false);
  print("Fixed-length List<int> created with List.filled: $fixed (length=${fixed.length})");

  for (var i = 0; i < fixed.length; i++) {
    fixed[i] = (i + 1) * 10;
  }
  print("After setting values by index: $fixed");

  fixed.setRange(1, 3, [111, 222]); 
  print("After setRange(1, 3, [111, 222]): $fixed");

  fixed.fillRange(3, 5, 42); 
  print("After fillRange(3, 5, 42): $fixed");

  try {
    fixed.add(60);
  } catch (e) {
    print("Expected error on add: $e");
  }

  try {
    fixed.insert(0, -1);
  } catch (e) {
    print("Expected error on insert: $e");
  }

  try {
    fixed.removeLast();
  } catch (e) {
    print("Expected error on removeLast: $e");
  }

  try {
    fixed.length = 2;
  } catch (e) {
    print("Expected error on setting length: $e");
  }

  final squares = List<int>.generate(6, (i) => (i + 1) * (i + 1), growable: false);
  print("Fixed-length generated squares: $squares (length=${squares.length})");

  final source = [1, 2, 3, 4, 5, 6, 7, 8];
  final fixedCopy = List<int>.of(source, growable: false);
  fixedCopy[0] = 999; 
  print("Fixed-length copy (modifiable elements): $fixedCopy");

  try {
    fixedCopy.add(9);
  } catch (e) {
    print("Expected error adding to fixedCopy: $e");
  }

  final unmod = List.unmodifiable(fixedCopy);
  print("Unmodifiable list created from fixedCopy: $unmod");
  try {
    unmod[0] = 0;
  } catch (e) {
    print("Expected error writing element of unmodifiable list: $e");
  }
  try {
    unmod.add(10);
  } catch (e) {
    print("Expected error adding to unmodifiable list: $e");
  }

  final bytes = Uint8List(4); 
  print("Uint8List initial: $bytes (length=${bytes.length})");
  bytes[0] = 255;
  bytes.setAll(1, [1, 2, 3]); 
  print("Uint8List after modifications: $bytes");

  try {
    bytes.add(10);
  } catch (e) {
    print("Expected error adding to Uint8List: $e");
  }

  print("Done.");
}

