import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> strengths, int maxSpread) {
  if (strengths.isEmpty) return 0.0;
  int left = 0;
  double bestCenter = 0.0;
  int bestCount = 0;
  for (int right = 0; right < strengths.length; right++) {
    while (strengths[right] - strengths[left] > maxSpread) {
      left++;
    }
    final count = right - left + 1;
    if (count > bestCount) {
      bestCount = count;
      bestCenter = (strengths[left] + strengths[right]) / 2.0;
    }
  }
  return bestCenter;
}

