double fn0(List<int> cardValues, int handSize) {
  if (cardValues.isEmpty || handSize <= 0 || handSize > cardValues.length) {
    return 0.0;
  }
  int currentSum = 0;
  for (int i = 0; i < handSize; i++) {
    currentSum += cardValues[i];
  }
  int maxSum = currentSum;
  for (int i = handSize; i < cardValues.length; i++) {
    currentSum += cardValues[i] - cardValues[i - handSize];
    if (currentSum > maxSum) {
      maxSum = currentSum;
    }
  }
  return maxSum / handSize;
}

