import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> readings) {
  if (readings.isEmpty) return 0.0;

  List<List<int>> rects = [];
  for (var r in readings) {
    int h = r[2];
    if (h <= 0) continue;
    int x = r[0];
    int y = r[1];
    rects.add([x + y - h, x + y + h, x - y - h, x - y + h]);
  }

  if (rects.isEmpty) return 0.0;

  Set<int> xSet = {};
  for (var rect in rects) {
    xSet.add(rect[0]);
    xSet.add(rect[1]);
  }
  List<int> xList = xSet.toList()..sort();

  double totalArea = 0.0;

  for (int i = 0; i < xList.length - 1; i++) {
    int x1 = xList[i];
    int x2 = xList[i + 1];

    List<List<int>> activeY = [];
    for (var rect in rects) {
      if (rect[0] <= x1 && rect[1] >= x2) {
        activeY.add([rect[2], rect[3]]);
      }
    }

    if (activeY.isEmpty) continue;

    activeY.sort((a, b) => a[0].compareTo(b[0]));

    int mergedYLength = 0;
    int currentY1 = activeY[0][0];
    int currentY2 = activeY[0][1];

    for (int j = 1; j < activeY.length; j++) {
      if (activeY[j][0] <= currentY2) {
        if (activeY[j][1] > currentY2) {
          currentY2 = activeY[j][1];
        }
      } else {
        mergedYLength += (currentY2 - currentY1);
        currentY1 = activeY[j][0];
        currentY2 = activeY[j][1];
      }
    }
    mergedYLength += (currentY2 - currentY1);

    totalArea += (x2 - x1) * mergedYLength;
  }

  return totalArea / 2.0;
}

