@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> hand) {
  if (hand.isEmpty) return 0;

  List<int> unique = hand.toSet().toList()..sort();

  List<List<int>> runs = [];
  List<int> currentRun = [unique[0]];

  for (int i = 1; i < unique.length; i++) {
    if (unique[i] == unique[i - 1] + 1) {
      currentRun.add(unique[i]);
    } else {
      runs.add(currentRun);
      currentRun = [unique[i]];
    }
  }
  runs.add(currentRun);

  int maxLen = 0;
  for (var run in runs) {
    if (run.length > maxLen) maxLen = run.length;
  }

  int bestSum = 0;
  for (var run in runs) {
    if (run.length == maxLen) {
      int sum = run.fold(0, (a, b) => a + b);
      if (sum > bestSum) bestSum = sum;
    }
  }

  return bestSum * maxLen;
}

