@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> powerLevels, int attunementBase) {
  int gcd(int a, int b) {
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a;
  }

  Set<int> result = {};
  int base = attunementBase < 0 ? -attunementBase : attunementBase;
  for (int level in powerLevels) {
    int absLevel = level < 0 ? -level : level;
    result.add(gcd(absLevel, base));
  }
  return result;
}

