import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> nums1 = [1, 2, 3];
  List<int> nums2 = [1, 2];
  List<int> nums3 = [1];
  List<int> nums4 = [];
  List<int> nums5 = [1, 2, 3, 4];

  List<List<int>> generatePermutations(List<int> nums) {
    List<List<int>> result = [];
    List<int> currentPermutation = [];
    List<bool> used = List.filled(nums.length, false);

    void backtrack() {

      if (currentPermutation.length == nums.length) {
        result.add(List.from(currentPermutation));
        return;
      }

      for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;

        currentPermutation.add(nums[i]);
        used[i] = true;

        backtrack();

        currentPermutation.removeLast();
        used[i] = false;
      }
    }

    backtrack();
    return result;
  }

  print('Permutations of $nums1:');
  List<List<int>> perms1 = generatePermutations(nums1);
  for (var perm in perms1) {
    print(perm);
  }
  print('Total: ${perms1.length} permutations\n');

  print('Permutations of $nums2:');
  List<List<int>> perms2 = generatePermutations(nums2);
  for (var perm in perms2) {
    print(perm);
  }
  print('Total: ${perms2.length} permutations\n');

  print('Permutations of $nums3:');
  List<List<int>> perms3 = generatePermutations(nums3);
  for (var perm in perms3) {
    print(perm);
  }
  print('Total: ${perms3.length} permutations\n');

  print('Permutations of $nums4:');
  List<List<int>> perms4 = generatePermutations(nums4);
  for (var perm in perms4) {
    print(perm);
  }
  print('Total: ${perms4.length} permutations\n');

  print('Permutations of $nums5:');
  List<List<int>> perms5 = generatePermutations(nums5);
  for (var perm in perms5) {
    print(perm);
  }
  print('Total: ${perms5.length} permutations\n');

  List<List<int>> generatePermutationsSwap(List<int> nums) {
    List<List<int>> result = [];
    List<int> numsCopy = List.from(nums);

    void backtrackSwap(int start) {
      if (start == numsCopy.length) {
        result.add(List.from(numsCopy));
        return;
      }

      for (int i = start; i < numsCopy.length; i++) {

        int temp = numsCopy[start];
        numsCopy[start] = numsCopy[i];
        numsCopy[i] = temp;

        backtrackSwap(start + 1);

        temp = numsCopy[start];
        numsCopy[start] = numsCopy[i];
        numsCopy[i] = temp;
      }
    }

    backtrackSwap(0);
    return result;
  }

  print('--- Using swap-based backtracking ---');
  print('Permutations of $nums1:');
  List<List<int>> permsSwap = generatePermutationsSwap(nums1);
  for (var perm in permsSwap) {
    print(perm);
  }
  print('Total: ${permsSwap.length} permutations');
}

