import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  List<int> arr = <int>[];
  for (final s in args) {
    final v = int.tryParse(s);
    if (v != null) arr.add(v);
  }
  if (arr.isEmpty) {
    arr = [38, 27, 43, 3, 9, 82, 10, -5, 0, 7, 7, 100, -1];
  }

  print('Before: $arr');

  final int n = arr.length;
  if (n <= 1) {
    print('After:  $arr');
    return;
  }

  final List<int> buffer = List<int>.filled(n, 0);
  int width = 1;
  while (width < n) {
    int i = 0;
    while (i < n) {
      final int left = i;
      final int mid = (i + width < n) ? i + width : n;
      final int right = (i + 2 * width < n) ? i + 2 * width : n;

      int li = left;   
      int ri = mid;    
      int di = left;   

      while (li < mid && ri < right) {
        if (arr[li] <= arr[ri]) {
          buffer[di++] = arr[li++];
        } else {
          buffer[di++] = arr[ri++];
        }
      }

      while (li < mid) buffer[di++] = arr[li++];
      while (ri < right) buffer[di++] = arr[ri++];

      for (int k = left; k < right; k++) {
        arr[k] = buffer[k];
      }

      i += 2 * width;
    }
    width *= 2;
  }

  print('After:  $arr');
}

