import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(
    List<List<int>> scheduledStops, List<List<int>> actualStops) {
  int totalDoubledArea = 0, maxManhattanDeviation = 0, onTimeOverlapCount = 0;
  int n = scheduledStops.length < actualStops.length ? scheduledStops.length : actualStops.length;
  int? pSx, pSy, pAx, pAy;

  for (int i = 0; i < n; i++) {
    int sx = scheduledStops[i][0], sy = scheduledStops[i][1];
    int ax = actualStops[i][0], ay = actualStops[i][1];
    int dist = (sx - ax).abs() + (sy - ay).abs();

    if (dist > maxManhattanDeviation) maxManhattanDeviation = dist;
    if (dist <= 2) onTimeOverlapCount++;

    if (pSx != null) {
      int width = (sx - pSx!).abs();
      if (width > 0) {
        totalDoubledArea += ((pSy! - pAy!).abs() + (sy - ay).abs()) * width;
      }
    }
    pSx = sx; pSy = sy; pAx = ax; pAy = ay;
  }
  return {
    'totalDoubledArea': totalDoubledArea,
    'maxManhattanDeviation': maxManhattanDeviation,
    'onTimeOverlapCount': onTimeOverlapCount,
  };
}

