@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<List<int>> grid) {


  final result = <int>{};
  if (grid.isEmpty || grid[0].isEmpty) return result;
  final rows = grid.length;
  final cols = grid[0].length;
  const dirs = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];
  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      if (grid[r][c] != 1) continue;
      var isolated = true;
      for (final d in dirs) {
        final nr = r + d[0];
        final nc = c + d[1];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {
          isolated = false;
          break;
        }
      }
      if (isolated) result.add(r * cols + c);
    }
  }
  return result;
}

