import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> cycleMinutes) {



  if (cycleMinutes.isEmpty) {
    return {'syncMinutes': 0, 'commonStep': 0, 'totalCycles': 0};
  }
  int gcd(int a, int b) {
    while (b != 0) {
      final t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
  int g = cycleMinutes[0];
  int l = cycleMinutes[0];
  for (int i = 1; i < cycleMinutes.length; i++) {
    final c = cycleMinutes[i];
    g = gcd(g, c);
    l = l ~/ gcd(l, c) * c;
  }
  int total = 0;
  for (final c in cycleMinutes) {
    total += l ~/ c;
  }
  return {'syncMinutes': l, 'commonStep': g, 'totalCycles': total};
}

