double fn0(List<List<double>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0.0;
  double total = 0.0;
  int count = 0;
  int rows = grid.length;
  int cols = grid[0].length;
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      double val = grid[i][j];
      if (val > 0.0 && ((i + j) % 2 == 0)) {
        total += val;
        count++;
      }
    }
  }
  if (count == 0) return 0.0;
  return total / count;
}

