import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> packetSizes, int mtu) {
  if (mtu <= 0) return -1;
  int bestWasted = -1;
  int bestCount = -1;
  int currentSum = 0;
  int currentCount = 0;
  for (int size in packetSizes) {
    if (size > mtu) {
      if (currentCount > 0) {
        int wasted = mtu - currentSum;
        if (bestWasted == -1 || wasted < bestWasted || (wasted == bestWasted && currentCount > bestCount)) {
          bestWasted = wasted;
          bestCount = currentCount;
        }
        currentSum = 0;
        currentCount = 0;
      }
      continue;
    }
    if (currentSum + size > mtu) {
      if (currentCount > 0) {
        int wasted = mtu - currentSum;
        if (bestWasted == -1 || wasted < bestWasted || (wasted == bestWasted && currentCount > bestCount)) {
          bestWasted = wasted;
          bestCount = currentCount;
        }
      }
      currentSum = size;
      currentCount = 1;
    } else {
      currentSum += size;
      currentCount++;
    }
  }
  if (currentCount > 0) {
    int wasted = mtu - currentSum;
    if (bestWasted == -1 || wasted < bestWasted || (wasted == bestWasted && currentCount > bestCount)) {
      bestWasted = wasted;
      bestCount = currentCount;
    }
  }
  return bestWasted;
}

