@pragma('vm:entry-point')
double fn0(String records) {
  int state = 0;
  int valid = 0;
  int total = 0;
  for (int i = 0; i < records.length; i++) {
    String ch = records[i];
    if (state == 0) {
      if (ch == 'V' || ch == 'I') {
        state = 1;
        total++;
      }
    } else if (state == 1) {
      if (ch == 'o' || ch == 'n') {
        valid++;
        state = 0;
      } else if (ch == 'x' || ch == ' ') {
        state = 0;
      }
    }
  }
  if (total == 0) return 0.0;
  return valid / total;
}

