import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<List<int>> rounds) {
  final canonical = <List<int>>[];
  for (final round in rounds) {
    final freq = <int, int>{};
    for (final die in round) {
      freq[die] = (freq[die] ?? 0) + 1;
    }
    final sorted = List<int>.from(round);
    sorted.sort((a, b) {
      final fa = freq[a] ?? 0;
      final fb = freq[b] ?? 0;
      if (fa != fb) return fb.compareTo(fa);
      return b.compareTo(a);
    });
    canonical.add(sorted);
  }
  for (var i = 1; i < canonical.length; i++) {
    final prev = canonical[i - 1];
    final curr = canonical[i];
    final minLen = prev.length < curr.length ? prev.length : curr.length;
    var j = 0;
    for (; j < minLen; j++) {
      if (prev[j] > curr[j]) return false;
      if (prev[j] < curr[j]) break;
    }
    if (j == minLen && prev.length > curr.length) return false;
  }
  return true;
}

