import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String digits) {
  if (digits.isEmpty) return true;

  List<int> decodeStack = [];
  List<String> pendingPairs = [];

  for (int i = 0; i < digits.length; i++) {
    String ch = digits[i];

    if (ch == '[') {
      String guardDigit = '';
      int j = i + 1;
      while (j < digits.length && digits[j] != '|') {
        guardDigit += digits[j];
        j++;
      }
      if (j >= digits.length || guardDigit.isEmpty) return false;

      pendingPairs.add(guardDigit);
      decodeStack.add(int.parse(guardDigit));
      i = j;
    } else if (ch == ']') {
      if (pendingPairs.isEmpty) return false;

      String guardDigit = pendingPairs.removeLast();
      int expected = int.parse(guardDigit);

      String content = '';
      int j = i + 1;
      while (j < digits.length && digits[j] != ']') {
        content += digits[j];
        j++;
      }
      if (j >= digits.length) return false;

      List<int> items = [];
      String current = '';
      for (int k = 0; k < content.length; k++) {
        if (content[k] == ',') {
          if (current.isEmpty) return false;
          items.add(int.parse(current));
          current = '';
        } else {
          current += content[k];
        }
      }
      if (current.isNotEmpty) items.add(int.parse(current));

      if (items.isEmpty) return false;

      int sum = 0;
      for (int val in items) {
        sum += val;
      }

      if (sum != expected) return false;

      decodeStack.addAll(items);
      i = j;
    } else if (ch == '|') {
      int separatorIdx = pendingPairs.length - 1;
      if (separatorIdx < 0) return false;

      String lastGuard = pendingPairs[separatorIdx];
      String subFromStack = '';
      int popCount = int.parse(lastGuard);

      if (decodeStack.length < popCount) return false;

      for (int p = 0; p < popCount; p++) {
        subFromStack = decodeStack.removeLast().toString() + subFromStack;
      }

      int reversed = 0;
      int temp = int.parse(subFromStack);
      while (temp > 0) {
        reversed = reversed * 10 + (temp % 10);
        temp ~/= 10;
      }
      if (subFromStack == '0') reversed = 0;

      if (reversed != int.parse(lastGuard)) return false;
    } else {
      if (digits.codeUnitAt(i) >= 48 && digits.codeUnitAt(i) <= 57) {
        decodeStack.add(int.parse(ch));
      }
      else {
        return false;
      }
    }
  }

  return pendingPairs.isEmpty;
}

