import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int fractionBits = 16;
  const int scale = 1 << fractionBits; 

  int toFixed(double value) {
    return (value * scale).round();
  }

  double fromFixed(int fixed) {
    return fixed / scale;
  }

  int fixedAdd(int a, int b) {
    return a + b;
  }

  int fixedSub(int a, int b) {
    return a - b;
  }

  int fixedMul(int a, int b) {

    int result = ((a.toSigned(64) * b.toSigned(64)) ~/ scale).toSigned(32);
    return result;
  }

  int fixedDiv(int a, int b) {
    if (b == 0) {
      throw ArgumentError('Division by zero');
    }

    int result = ((a.toSigned(64) * scale) ~/ b.toSigned(64)).toSigned(32);
    return result;
