import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<String> operations) {
  double moisture = 0.0;
  List<double> stack = [];
  for (var op in operations) {
    if (op == 'undo') {
      if (stack.isNotEmpty) {
        moisture -= stack.removeLast();
      }
    } else if (op.startsWith('add ')) {
      double val = double.parse(op.substring(4));
      moisture += val;
      stack.add(val);
    } else if (op.startsWith('sub ')) {
      double val = double.parse(op.substring(4));
      moisture -= val;
      stack.add(-val);
    }
  }
  return moisture;
}

