List<String> fn0(List<String> cells, String target) {
  final result = List<String>.from(cells);
  int distance(String cell, String center) {
    int colC = cell.codeUnitAt(0) - 65;
    int rowC = int.parse(cell.substring(1));
    int colT = center.codeUnitAt(0) - 65;
    int rowT = int.parse(center.substring(1));
    return (colC - colT).abs() + (rowC - rowT).abs();
  }
  result.sort((a, b) {
    int dA = distance(a, target);
    int dB = distance(b, target);
    if (dA != dB) return dA.compareTo(dB);
    return a.compareTo(b);
  });
  return result;
}

