@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> readings) {
  if (readings.isEmpty) return 0;
  int bestSwing = 0;
  void traverse(int index, int pathMin, int pathMax) {
    int val = readings[index];
    int curMin = val < pathMin ? val : pathMin;
    int curMax = val > pathMax ? val : pathMax;
    int swing = curMax - curMin;
    if (swing > bestSwing) bestSwing = swing;
    int left = 2 * index + 1;
    int right = 2 * index + 2;
    if (left < readings.length) {
      traverse(left, curMin, curMax);
    }
    if (right < readings.length) {
      traverse(right, curMin, curMax);
    }
  }
  traverse(0, readings[0], readings[0]);
  return bestSwing;
}

