@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> cellWalls) {
  if (cellWalls.isEmpty) return 0.0;
  int totalOpenDirections = 0;
  for (int walls in cellWalls) {

    int masked = walls & 0xF;

    int wallCount = ((masked >> 0) & 1) + ((masked >> 1) & 1) +
                    ((masked >> 2) & 1) + ((masked >> 3) & 1);
    totalOpenDirections += (4 - wallCount);
  }
  return totalOpenDirections / (cellWalls.length * 4.0);
}

