import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(int teams, int matchDays, int restDays) {
  Map<String, int> result = {};
  int numRounds = 0;
  int t = teams;
  while (t > 1) {
    t ~/= 2;
    numRounds++;
  }
  int currentDay = 0;
  int remainingTeams = teams;
  for (int round = 1; round <= numRounds; round++) {
    int matches = remainingTeams ~/ 2;
    result["R${round}_start"] = currentDay;
    result["R${round}_end"] = currentDay + matchDays - 1;
    currentDay += matchDays;
    remainingTeams ~/= 2;
    if (round < numRounds) {
      int rest = (matches < 4) ? restDays ~/ 2 : restDays;
      currentDay += rest;
    }
  }
  result["total"] = currentDay - 1;
  return result;
}

