import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> seeds, int rounds) {
  if (seeds.isEmpty || rounds <= 0) {
    return seeds.toSet();
  }
  if (seeds.length == 1) {
    return <int>{seeds[0]};
  }
  List<int> winners = <int>[];
  for (int i = 0; i < seeds.length; i += 2) {
    if (i + 1 == seeds.length) {
      winners.add(seeds[i]);
    } else {
      winners.add(seeds[i] < seeds[i + 1] ? seeds[i] : seeds[i + 1]);
    }
  }
  return fn0(winners, rounds - 1);
}

