double fn0(String password) {
  if (password.isEmpty) return 0.0;
  Map<String, int> freq = {};
  for (int i = 0; i < password.length; i++) {
    freq[password[i]] = (freq[password[i]] ?? 0) + 1;
  }
  int repeatedCount = 0;
  for (int count in freq.values) {
    if (count > 1) repeatedCount += count;
  }
  return repeatedCount / password.length;
}

