import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  var men = ['A', 'B', 'C'];
  var women = ['X', 'Y', 'Z'];

  List<List<int>> menPrefs = [
    [0, 1, 2], 
    [1, 0, 2], 
    [0, 1, 2], 
  ];

  List<List<int>> womenPrefs = [
    [1, 0, 2], 
    [0, 1, 2], 
    [0, 1, 2], 
  ];

  int n = menPrefs.length;

  List<int> womanPartner = List.filled(n, -1);

  List<int> nextProposal = List.filled(n, 0);


  List<List<int>> womenRank = List.generate(n, (w) {
    var rank = List.filled(n, 0);
    for (int i = 0; i < n; i++) {
      rank[womenPrefs[w][i]] = i;
    }
    return rank;
  });

  List<int> freeMen = List.generate(n, (i) => i);

  while (freeMen.isNotEmpty) {
    int m = freeMen.removeAt(0);

    int w = menPrefs[m][nextProposal[m]];
    nextProposal[m]++;

    if (womanPartner[w] == -1) {

      womanPartner[w] = m;
    } else {
      int m1 = womanPartner[w]!;

      if (womenRank[w][m] < womenRank[w][m1]) {

        womanPartner[w] = m;

        freeMen.add(m1);
      } else {

        freeMen.add(m);
      }
    }
  }

  List<int> manPartner = List.filled(n, -1);
  for (int w = 0; w < n; w++) {
    manPartner[womanPartner[w]] = w;
  }

  for (int m = 0; m < n; m++) {
    print('${men[m]} is matched with ${women[manPartner[m]]}');
  }
}

