int fn0(String misspelled, List<String> suggestions, String query) {
  if (!suggestions.contains(query)) return -1;
  var sorted = List<String>.from(suggestions);
  sorted.sort((a, b) {
    int diffA = (a.length - misspelled.length).abs();
    int diffB = (b.length - misspelled.length).abs();
    if (diffA != diffB) return diffA.compareTo(diffB);
    return a.compareTo(b);
  });
  return sorted.indexOf(query);
}

