import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(int packedPhases, int phaseCount, int flags) {
  if (phaseCount == 0) return true;
  if (phaseCount < 0 || phaseCount > 10) return false;
  const int allRed = 0, nsGreen = 1, nsYellow = 2, ewGreen = 3, ewYellow = 4;
  const int allowDirectChange = 1 << 0, requireAllRedStart = 1 << 1;
  final int first = packedPhases & 0x7;
  if (first > 4) return false;
  if ((flags & requireAllRedStart) != 0 && first != allRed) return false;
  int previous = first;
  for (int i = 1; i < phaseCount; i++) {
    final int current = (packedPhases >> (i * 3)) & 0x7;
    if (current > 4) return false;
    bool ok;
    if (previous == nsGreen) {
      ok = current == nsYellow || current == allRed;
    } else if (previous == nsYellow) {
      ok = current == allRed || ((flags & allowDirectChange) != 0 && current == ewGreen);
    } else if (previous == ewGreen) {
      ok = current == ewYellow || current == allRed;
    } else if (previous == ewYellow) {
      ok = current == allRed || ((flags & allowDirectChange) != 0 && current == nsGreen);
    } else {
      ok = true;
    }
    if (!ok) return false;
    previous = current;
  }
  return true;
}

