@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> songNames, List<int> durations, int minDuration, int maxDuration) {
  if (songNames.isEmpty || minDuration > maxDuration) return [];
  int left = 0, right = songNames.length;
  while (left < right) {
    int mid = (left + right) ~/ 2;
    if (durations[mid] < minDuration) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  int start = left;
  left = 0;
  right = songNames.length;
  while (left < right) {
    int mid = (left + right) ~/ 2;
    if (durations[mid] <= maxDuration) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  int end = left;
  return songNames.sublist(start, end);
}

