import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> hand, int k) {
  if (hand.isEmpty) {
    return k;
  }
  int totalMissing = hand[hand.length - 1] - hand.length;
  if (totalMissing < k) {
    return hand[hand.length - 1] + (k - totalMissing);
  }
  int left = 0;
  int right = hand.length - 1;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    int missing = hand[mid] - (mid + 1);
    if (missing < k) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  if (left == 0) {
    return k;
  }
  int missingBefore = hand[left - 1] - left;
  return hand[left - 1] + (k - missingBefore);
}

