import 'dart:async';
import 'dart:convert';
import 'dart:core';

abstract class Shape {

  factory Shape(String type, double dimension) {
    if (type == 'circle') {
      return Circle(dimension);
    } else if (type == 'square') {
      return Square(dimension);
    } else {
      throw ArgumentError('Unknown shape type: $type');
    }
  }

  double get area;
}

class Circle implements Shape {
  final double radius;
  Circle(this.radius);

  @override
  double get area => 3.14159 * radius * radius;
}

class Square implements Shape {
  final double side;
  Square(this.side);

  @override
  double get area => side * side;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  Shape circle = Shape('circle', 5);
  print('Circle area (radius 5): ${circle.area}');

  Shape square = Shape('square', 4);
  print('Square area (side 4): ${square.area}');

  try {
    Shape unknown = Shape('triangle', 3);
