import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> strengths) {
  if (strengths.isEmpty) return {};
  if (strengths.length <= 4) {
    return strengths.asMap().keys.toSet();
  }

  List<int> indices = List.generate(strengths.length, (i) => i);
  indices.sort((a, b) {
    int bwA = strengths[a] ^ a;
    int bwB = strengths[b] ^ b;
    if (bwA != bwB) return bwB.compareTo(bwA);
    if (strengths[a] != strengths[b]) {
      return strengths[b].compareTo(strengths[a]);
    }
    return a.compareTo(b);
  });

  List<int> currentRound = indices;
  while (currentRound.length > 4) {
    List<int> nextRound = [];
    for (int i = 0; i < currentRound.length; i += 2) {
      if (i + 1 < currentRound.length) {
        int p1 = currentRound[i];
        int p2 = currentRound[i + 1];
        int s1 = strengths[p1];
        int s2 = strengths[p2];
        if (s1 != s2) {
          nextRound.add(s1 > s2 ? p1 : p2);
        } else {
          int bw1 = s1 ^ p1;
          int bw2 = s2 ^ p2;
          nextRound.add(bw1 > bw2 ? p1 : p2);
        }
      } else {
        nextRound.add(currentRound[i]);
      }
    }
    currentRound = nextRound;
  }

  return currentRound.toSet();
}

