Set<int> fn0(List<int> temperatures, int windowSize, int low, int high) {
  if (windowSize <= 0 || temperatures.length < windowSize) return {};
  Set<int> result = {};
  int outOfRange = 0;
  for (int i = 0; i < windowSize; i++) {
    if (temperatures[i] < low || temperatures[i] > high) outOfRange++;
  }
  if (outOfRange == 0) result.add(0);
  for (int i = windowSize; i < temperatures.length; i++) {
    if (temperatures[i - windowSize] < low || temperatures[i - windowSize] > high) outOfRange--;
    if (temperatures[i] < low || temperatures[i] > high) outOfRange++;
    if (outOfRange == 0) result.add(i - windowSize + 1);
  }
  return result;
}

