String fn0(String moduleRow) {
  if (moduleRow.isEmpty) return '0C';
  StringBuffer buffer = StringBuffer();
  int count = 1;
  for (int i = 1; i < moduleRow.length; i++) {
    if (moduleRow[i] == moduleRow[i - 1]) {
      count++;
    } else {
      buffer.write('$count${moduleRow[i-1]}');
      count = 1;
    }
  }
  buffer.write('$count${moduleRow[moduleRow.length - 1]}');
  int checksum = 0;
  for (int i = 0; i < moduleRow.length; i++) {
    checksum = (checksum + moduleRow.codeUnitAt(i)) % 10;
  }
  buffer.write('${checksum}S');
  return buffer.toString();
}

