import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> commands) {
  List<double> stack = [];
  int lastCheckpoint = -1;
  List<String> reports = [];

  for (String cmd in commands) {
    if (cmd.startsWith('SAMPLE ')) {
      stack.add(double.parse(cmd.substring(7)));
    } else if (cmd.startsWith('ACCUMULATE ')) {
      double val = double.parse(cmd.substring(11));
      if (stack.isNotEmpty) {
        stack[stack.length - 1] += val;
      } else {
        stack.add(val);
      }
    } else if (cmd == 'CHECKPOINT') {
      lastCheckpoint = stack.length;
    } else if (cmd == 'ROLLBACK') {
      if (lastCheckpoint == -1) {
        stack.clear();
      } else {
        stack.length = lastCheckpoint;
        lastCheckpoint = -1;
      }
    } else if (cmd == 'REPORT') {
      reports.add(stack.toString());
    }
  }
  return reports;
}

