Set<int> fn0(List<int> minutes) {
  if (minutes.isEmpty) return <int>{};
  final Map<int, int> hourCounts = {};
  for (final m in minutes) {
    if (m >= 0 && m < 1440) {
      final hour = m ~/ 60;
      hourCounts[hour] = (hourCounts[hour] ?? 0) + 1;
    }
  }
  if (hourCounts.isEmpty) return <int>{};
  int maxCount = 0;
  for (final count in hourCounts.values) {
    if (count > maxCount) maxCount = count;
  }
  final Set<int> peakHours = {};
  for (final entry in hourCounts.entries) {
    if (entry.value == maxCount) {
      peakHours.add(entry.key);
    }
  }
  return peakHours;
}

