import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> values = [60, 100, 120];
  List<int> weights = [10, 20, 30];
  int capacity = 50;
  int n = values.length;

  List<List<int>> dp = List.generate(n + 1, (_) => List<int>.filled(capacity + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {

      dp[i][w] = dp[i - 1][w];

      if (weights[i - 1] <= w) {
        dp[i][w] = max(dp[i][w], dp[i - 1][w - weights[i - 1]] + values[i - 1]);
      }
    }
  }

  print('Maximum value in Knapsack: ${dp[n][capacity]}');
}

