import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String typo, List<String> dictionary, int maxEdits) {
  int distance(String a, String b) {
    final Map<String, int> memo = {};

    int solve(int i, int j) {
      String key = '$i:$j';
      if (memo.containsKey(key)) {
        return memo[key]!;
      }

      if (i == a.length) {
        return b.length - j;
      }
      if (j == b.length) {
        return a.length - i;
      }

      if (a[i] == b[j]) {
        memo[key] = solve(i + 1, j + 1);
        return memo[key]!;
      }

      int insertCost = 1 + solve(i, j + 1);
      int deleteCost = 1 + solve(i + 1, j);
      int replaceCost = 1 + solve(i + 1, j + 1);

      int best = insertCost;
      if (deleteCost < best) {
        best = deleteCost;
      }
      if (replaceCost < best) {
        best = replaceCost;
      }

      if (i + 1 < a.length &&
          j + 1 < b.length &&
          a[i] == b[j + 1] &&
          a[i + 1] == b[j]) {
        int swapCost = 1 + solve(i + 2, j + 2);
        if (swapCost < best) {
          best = swapCost;
        }
      }

      memo[key] = best;
      return best;
    }

    return solve(0, 0);
  }

  List<Map<String, Object>> matches = [];

  for (String word in dictionary) {
    int d = distance(typo, word);
    if (d <= maxEdits) {
      matches.add({'word': word, 'dist': d});
    }
  }

  matches.sort((a, b) {
    int da = a['dist'] as int;
    int db = b['dist'] as int;
    if (da != db) {
      return da.compareTo(db);
    }
    return (a['word'] as String).compareTo(b['word'] as String);
  });

  return matches.map((e) => e['word'] as String).toList();
}

