import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int vertices = 5;

  int source = 0;

  List<List<int>> edges = [
    [0, 1, -1],
    [0, 2, 4],
    [1, 2, 3],
    [1, 3, 2],
    [1, 4, 2],
    [3, 2, 5],
    [3, 1, 1],
    [4, 3, -3],
  ];

  List<double> dist = List.filled(vertices, double.infinity);
  dist[source] = 0;

  for (int i = 1; i < vertices; i++) {
    for (var edge in edges) {
      int u = edge[0];
      int v = edge[1];
      int w = edge[2];
      if (dist[u] != double.infinity && dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
      }
    }
  }

  bool hasNegativeCycle = false;
  for (var edge in edges) {
    int u = edge[0];
    int v = edge[1];
    int w = edge[2];
    if (dist[u] != double.infinity && dist[u] + w < dist[v]) {
      hasNegativeCycle = true;
      break;
    }
  }

  if (hasNegativeCycle) {
    print("Graph contains a negative-weight cycle");
  } else {
    print("Shortest distances from source $source:");
    for (int i = 0; i < vertices; i++) {
      print("Vertex $i: ${dist[i] == double.infinity ? 'Infinity' : dist[i]}");
    }
  }
}

