import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<int> cycleCounts, int k) {
  List<int> arr = List.from(cycleCounts);
  if (k < 1 || k > arr.length) return "Invalid k";
  int left = 0, right = arr.length - 1, kIndex = k - 1;
  while (true) {
    int pivot = arr[right];
    int i = left;
    for (int j = left; j < right; j++) {
      if (arr[j] <= pivot) {
        int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp; i++;
      }
    }
    int tmp = arr[i]; arr[i] = arr[right]; arr[right] = tmp;
    if (kIndex == i) break;
    if (kIndex < i) right = i - 1;
    else left = i + 1;
  }
  return "The ${k}th smallest cycle count is ${arr[kIndex]}";
}

