    if (screenWidth < tabletBreakpoint) return tablet;
    return desktop;
  }

  Map<String, dynamic> calculateFlexibleGrid(double containerWidth, double minItemWidth, double gap) {
    int columns = (containerWidth / minItemWidth).floor();
    columns = columns.clamp(1, 12);
    double itemWidth = (containerWidth - (columns - 1) * gap) / columns;
    return {
      'columns': columns,
      'itemWidth': itemWidth,
      'totalGap': (columns - 1) * gap,
    };
  }

  print('Testing responsive utilities:');
  for (var entry in devices.entries) {
    final width = entry.value['width']!;
    final padding = getResponsiveValue(width, 16.0, 24.0, 32.0);
    print('${entry.key}: Padding = ${padding}px');

    final grid = calculateFlexibleGrid(width - padding * 2, 150.0, 16.0);
    print('  Grid: ${grid['columns']} cols, ${grid['itemWidth'].toStringAsFixed(1)}px items\n');
  }

  print('=== Orientation Handling ===\n');
  for (var entry in devices.entries) {
    final width = entry.value['width']!;
    final height = entry.value['height']!;

    bool isPortrait = height > width;
    print('${entry.key}:');
    print('  Portrait (${width}x${height}): ${isPortrait ? "Yes" : "No"}');

    final landscapeWidth = height;
    final landscapeHeight = width;
    print('  Landscape (${landscapeWidth}x${landscapeHeight}): Layout adjustments needed');

    double aspectRatio = width / height;
    String aspectType;
    if (aspectRatio < 0.5) {
      aspectType = 'Tall';
    } else if (aspectRatio < 0.75) {
      aspectType = 'Portrait';
    } else if (aspectRatio < 1.33) {
      aspectType = 'Square-ish';
    } else if (aspectRatio < 1.78) {
      aspectType = 'Landscape';
    } else {
      aspectType = 'Wide';
    }
    print('  Aspect Ratio: ${aspectRatio.toStringAsFixed(2)} ($aspectType)\n');
  }
}

