import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> knights) {
  const offsets = [
    [1, 2], [2, 1], [2, -1], [1, -2],
    [-1, -2], [-2, -1], [-2, 1], [-1, 2]
  ];
  final result = <String, int>{};
  for (final pos in knights) {
    final file = pos.codeUnitAt(0) - 97 + 1;
    final rank = int.parse(pos.substring(1));
    for (final off in offsets) {
      final nf = file + off[0];
      final nr = rank + off[1];
      if (nf >= 1 && nf <= 8 && nr >= 1 && nr <= 8) {
        final sq = String.fromCharCode(nf + 96) + nr.toString();
        result[sq] = (result[sq] ?? 0) + 1;
      }
    }
  }
  return result;
}

