@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String line) {
  int len = line.length;
  if (len < 18 || line[0] != '[' || line[3] != ':' || line[6] != ':' || line[9] != ']') return false;
  int h = (line.codeUnitAt(1) - 48) * 10 + line.codeUnitAt(2) - 48;
  int m = (line.codeUnitAt(4) - 48) * 10 + line.codeUnitAt(5) - 48;
  int s = (line.codeUnitAt(7) - 48) * 10 + line.codeUnitAt(8) - 48;
  if (h < 0 || h > 23 || m < 0 || m > 59 || s < 0 || s > 59) return false;
  if (line[10] != ' ') return false;
  int pos = 11, levelEnd = 11;
  while (levelEnd < len && line[levelEnd] != ' ') levelEnd++;
  if (levelEnd == pos || levelEnd >= len) return false;
  String level = line.substring(pos, levelEnd);
  if (level != 'DEBUG' && level != 'INFO' && level != 'WARN' && level != 'ERROR') return false;
  pos = levelEnd + 1;
  if (pos >= len) return false;
  int msgStart = -1;
  if (line[pos] == '"') { msgStart = pos; } else {
    for (int i = pos; i < len - 1; i++) {
      if (line[i] == ' ' && line[i + 1] == '"') { msgStart = i + 1; break; }
    }
    if (msgStart == -1) return false;
    String meta = line.substring(pos, msgStart - 1);
    Set<String> seen = {};
    String lastKey = '';
    for (String pair in meta.split(';')) {
      if (pair.isEmpty) return false;
      int eq = pair.indexOf('=');
      if (eq <= 0 || eq >= pair.length - 1) return false;
      String key = pair.substring(0, eq), val = pair.substring(eq + 1);
      for (int j = 0; j < key.length; j++) { int c = key.codeUnitAt(j); if (c < 97 || c > 122) return false; }
      for (int j = 0; j < val.length; j++) { int c = val.codeUnitAt(j); if (c < 48 || c > 57) return false; }
      if (!seen.add(key)) return false;
      if (lastKey.isNotEmpty && key.compareTo(lastKey) <= 0) return false;
      lastKey = key;
    }
  }
  pos = msgStart + 1;
  while (pos < len) {
    if (line[pos] == '\\') { pos++; if (pos >= len || line[pos] != '"') return false; pos++; }
    else if (line[pos] == '"') { pos++; return pos == len; }
    else pos++;
  }
  return false;
}

