  int fromBE = bytesBE.getUint32(0, Endian.big);

  print('Read from little endian bytes: 0x${fromLE.toRadixString(16).padLeft(8, '0')}');
  print('Read from big endian bytes:    0x${fromBE.toRadixString(16).padLeft(8, '0')}');
}

