import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String stream) {
  Set<int> result = {};
  int state = 0;
  int dataSum = 0;
  int digitCount = 0;
  int checkDigit = -1;

  for (int i = 0; i < stream.length; i++) {
    String c = stream[i];
    if (c == 'X') {
      state = 0;
      dataSum = 0;
      digitCount = 0;
      continue;
    }
    switch (state) {
      case 0:
        if (c == 'B') {
          state = 1;
          dataSum = 0;
          digitCount = 0;
        }
        break;
      case 1:
        int code = c.codeUnitAt(0);
        if (code >= 48 && code <= 57) {
          dataSum += code - 48;
          digitCount++;
        } else if (c == 'C' && digitCount > 0) {
          state = 2;
        } else {
          state = 0;
        }
        break;
      case 2:
        int code2 = c.codeUnitAt(0);
        if (code2 >= 48 && code2 <= 57) {
          checkDigit = code2 - 48;
          state = 3;
        } else {
          state = 0;
        }
        break;
      case 3:
        if (c == 'E' && checkDigit == dataSum % 10) {
          result.add(checkDigit);
        }
        state = 0;
        dataSum = 0;
        digitCount = 0;
        break;
    }
  }
  return result;
}

