import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<List<int>> pixels) {
  int redSumX = 0, redSumY = 0, redCount = 0;
  int blueSumX = 0, blueSumY = 0, blueCount = 0;

  for (var pixel in pixels) {
    int x = pixel[0], y = pixel[1];
    int r = pixel[2], g = pixel[3], b = pixel[4];
    if (r > g && r > b) {
      redSumX += x;
      redSumY += y;
      redCount++;
    } else if (b > r && b > g) {
      blueSumX += x;
      blueSumY += y;
      blueCount++;
    }
  }

  if (redCount == 0 || blueCount == 0) return 0;

  int redCX = redSumX ~/ redCount;
  int redCY = redSumY ~/ redCount;
  int blueCX = blueSumX ~/ blueCount;
  int blueCY = blueSumY ~/ blueCount;

  return (redCX - blueCX).abs() + (redCY - blueCY).abs();
}

