import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<int>> capacity = [
    [0, 16, 13, 0, 0, 0],
    [0, 0, 10, 12, 0, 0],
    [0, 4, 0, 0, 14, 0],
    [0, 0, 9, 0, 0, 20],
    [0, 0, 0, 7, 0, 4],
    [0, 0, 0, 0, 0, 0]
  ];

  int n = capacity.length;
  int source = 0;
  int sink = 5;

  List<List<int>> residualGraph = List.generate(
    n, 
    (i) => List.generate(n, (j) => capacity[i][j])
  );

  bool bfs(List<List<int>> rGraph, int s, int t, List<int> parent) {
    List<bool> visited = List.filled(n, false);
    List<int> queue = [];

    queue.add(s);
    visited[s] = true;
    parent[s] = -1;

    while (queue.isNotEmpty) {
      int u = queue.removeAt(0);

      for (int v = 0; v < n; v++) {
        if (!visited[v] && rGraph[u][v] > 0) {
          queue.add(v);
          parent[v] = u;
          visited[v] = true;

          if (v == t) {
            return true;
          }
        }
      }
    }

    return false;
  }

  int maxFlow = 0;
  List<int> parent = List.filled(n, 0);

  while (bfs(residualGraph, source, sink, parent)) {

    int pathFlow = 999999999;

    for (int v = sink; v != source; v = parent[v]) {
      int u = parent[v];
      pathFlow = pathFlow < residualGraph[u][v] ? pathFlow : residualGraph[u][v];
    }

    for (int v = sink; v != source; v = parent[v]) {
      int u = parent[v];
      residualGraph[u][v] -= pathFlow;
      residualGraph[v][u] += pathFlow;
    }

    maxFlow += pathFlow;
  }

  print('Maximum flow from node $source to node $sink: $maxFlow');

  print('\nFlow through edges:');
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (capacity[i][j] > 0) {
        int flow = capacity[i][j] - residualGraph[i][j];
        if (flow > 0) {
          print('Edge ($i -> $j): $flow / ${capacity[i][j]}');
        }
      }
    }
  }

  List<bool> reachable = List.filled(n, false);
  List<int> queue = [source];
  reachable[source] = true;

  while (queue.isNotEmpty) {
    int u = queue.removeAt(0);
    for (int v = 0; v < n; v++) {
      if (!reachable[v] && residualGraph[u][v] > 0) {
        reachable[v] = true;
        queue.add(v);
      }
    }
  }

  print('\nMinimum cut edges:');
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (reachable[i] && !reachable[j] && capacity[i][j] > 0) {
        print('Edge ($i -> $j) with capacity ${capacity[i][j]}');
      }
    }
  }
}

