@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String program, int initialTemp) {





  int temp = initialTemp;
  bool hold = false;
  int i = 0;
  while (i < program.length) {
    String c = program[i];
    if (c == 'H') {
      hold = true;
      i++;
    } else if (c == 'R') {
      hold = false;
      i++;
    } else if (c == 'S' || c == '+' || c == '-') {
      i++;
      int start = i;
      while (i < program.length &&
          program.codeUnitAt(i) >= 48 &&
          program.codeUnitAt(i) <= 57) {
        i++;
      }
      if (start == i) return -1;
      int value = int.parse(program.substring(start, i));
      if (!hold) {
        if (c == 'S') {
          temp = value;
        } else if (c == '+') {
          temp += value;
        } else {
          temp -= value;
        }
      }
    } else {
      return -1;
    }
  }
  return temp;
}

