import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> board = List.filled(9, 0);

  void printBoard() {
    for (int i = 0; i < 9; i += 3) {
      String row = '';
      for (int j = 0; j < 3; j++) {
        if (board[i + j] == 0) {
          row += '${i + j} ';
        } else if (board[i + j] == 1) {
          row += 'X ';
        } else {
          row += 'O ';
        }
      }
      print(row);
    }
    print('');
  }

  int checkWinner() {

    for (int i = 0; i < 9; i += 3) {
      if (board[i] != 0 && board[i] == board[i + 1] && board[i] == board[i + 2]) {
        return board[i];
      }
    }

    for (int i = 0; i < 3; i++) {
      if (board[i] != 0 && board[i] == board[i + 3] && board[i] == board[i + 6]) {
        return board[i];
      }
    }

    if (board[0] != 0 && board[0] == board[4] && board[0] == board[8]) {
      return board[0];
    }
    if (board[2] != 0 && board[2] == board[4] && board[2] == board[6]) {
      return board[2];
    }

    return 0; 
  }

  bool isBoardFull() {
    for (int i = 0; i < 9; i++) {
      if (board[i] == 0) return false;
    }
    return true;
  }

  int minimax(bool isMaximizing, int depth) {
    int winner = checkWinner();

    if (winner == 2) return 10 - depth; 
    if (winner == 1) return depth - 10; 
    if (isBoardFull()) return 0; 

    if (isMaximizing) {
      int maxEval = -1000;
      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 2; 
          int eval = minimax(false, depth + 1);
          board[i] = 0;
          if (eval > maxEval) {
            maxEval = eval;
          }
        }
      }
      return maxEval;
    } else {
      int minEval = 1000;
      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 1; 
          int eval = minimax(true, depth + 1);
          board[i] = 0;
          if (eval < minEval) {
            minEval = eval;
          }
        }
      }
      return minEval;
    }
  }

  int findBestMove() {
    int bestMove = -1;
    int bestValue = -1000;

    for (int i = 0; i < 9; i++) {
      if (board[i] == 0) {
        board[i] = 2; 
        int moveValue = minimax(false, 0);
        board[i] = 0;

        if (moveValue > bestValue) {
          bestValue = moveValue;
          bestMove = i;
        }
      }
    }

    return bestMove;
  }

  print('Tic-Tac-Toe with Minimax AI');
  print('You are X, AI is O');
  print('Enter position (0-8) to make your move:\n');

  printBoard();

  List<int> humanMoves = [4, 0, 2]; 
  int moveIndex = 0;

  while (true) {

    if (moveIndex < humanMoves.length) {
      int humanMove = humanMoves[moveIndex];
      if (board[humanMove] == 0) {
        board[humanMove] = 1;
        print('Human plays at position $humanMove');
        printBoard();
        moveIndex++;
      }
    } else {

      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 1;
          print('Human plays at position $i');
          printBoard();
          break;
        }
      }
    }

    int winner = checkWinner();
    if (winner == 1) {
      print('Human wins!');
      break;
    }
    if (isBoardFull()) {
      print('It\'s a draw!');
      break;
    }

    int aiMove = findBestMove();
    if (aiMove != -1) {
      board[aiMove] = 2;
      print('AI plays at position $aiMove');
      printBoard();
    }

    winner = checkWinner();
    if (winner == 2) {
      print('AI wins!');
      break;
    }
    if (isBoardFull()) {
      print('It\'s a draw!');
      break;
    }
  }
}

