import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<List<int>> shelves) {
  if (shelves.isEmpty) return <int>{};
  Set<int> prevPicked = <int>{};
  Set<int> prevSkipped = <int>{};
  for (final w in shelves[0]) {
    prevPicked.add(w);
  }
  prevSkipped.add(0);
  for (int i = 1; i < shelves.length; i++) {
    final Set<int> newPicked = <int>{};
    final Set<int> newSkipped = <int>{};
    final Set<int> allPrev = <int>{...prevPicked, ...prevSkipped};
    for (final w in shelves[i]) {
      for (final x in allPrev) {
        newPicked.add(w + x);
      }
    }
    newSkipped.addAll(prevPicked);
    prevPicked = newPicked;
    prevSkipped = newSkipped;
  }
  return <int>{...prevPicked, ...prevSkipped};
}

