double fn0(List<int> cards, int maxFaceCards) {
  int n = cards.length;
  if (n == 0) return 0.0;
  int left = 0, faceCount = 0, maxLen = 0;
  for (int right = 0; right < n; right++) {
    if (cards[right] >= 11) faceCount++;
    while (faceCount > maxFaceCards) {
      if (cards[left] >= 11) faceCount--;
      left++;
    }
    int len = right - left + 1;
    if (len > maxLen) maxLen = len;
  }
  return maxLen / n;
}

