import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> bucketCounts, int maxGap) {
  int n = bucketCounts.length;
  if (n == 0) {
    return <int>[];
  }

  List<int> bestLength = List<int>.filled(n, 1);
  List<int> bestSum = List<int>.from(bucketCounts);

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < i; j++) {
      int difference = bucketCounts[i] - bucketCounts[j];

      if (difference >= 0 && difference <= maxGap) {
        int candidateLength = bestLength[j] + 1;
        int candidateSum = bestSum[j] + bucketCounts[i];

        if (candidateLength > bestLength[i]) {
          bestLength[i] = candidateLength;
          bestSum[i] = candidateSum;
        } else if (candidateLength == bestLength[i] &&
            candidateSum > bestSum[i]) {
          bestSum[i] = candidateSum;
        }
      }
    }
  }

  return bestLength;
}

