import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {



  final int vertices = 6;
  List<List<int>> graph = [

    [  0, 16, 13,  0,  0,  0], 
    [  0,  0, 10, 12,  0,  0], 
    [  0,  4,  0,  0, 14,  0], 
    [  0,  0,  9,  0,  0, 20], 
    [  0,  0,  0,  7,  0,  4], 
    [  0,  0,  0,  0,  0,  0], 
  ];

  List<List<int>> residualGraph = List.generate(
    vertices, 
    (i) => List.from(graph[i])
  );

  bool bfs(List<List<int>> rGraph, int source, int sink, List<int> parent) {
    List<bool> visited = List.filled(vertices, false);
    List<int> queue = [];

    queue.add(source);
    visited[source] = true;
    parent[source] = -1;

    while (queue.isNotEmpty) {
      int u = queue.removeAt(0);

      for (int v = 0; v < vertices; v++) {
        if (!visited[v] && rGraph[u][v] > 0) {
          queue.add(v);
          parent[v] = u;
          visited[v] = true;

          if (v == sink) {
            return true;
          }
        }
      }
    }

    return false;
  }

  int fordFulkerson(int source, int sink) {
    List<int> parent = List.filled(vertices, 0);
    int maxFlow = 0;

    while (bfs(residualGraph, source, sink, parent)) {

      int pathFlow = 999999999; 

      for (int v = sink; v != source; v = parent[v]) {
        int u = parent[v];
        if (residualGraph[u][v] < pathFlow) {
          pathFlow = residualGraph[u][v];
        }
      }

      for (int v = sink; v != source; v = parent[v]) {
        int u = parent[v];
        residualGraph[u][v] -= pathFlow;
        residualGraph[v][u] += pathFlow;
      }

      maxFlow += pathFlow;

      print('Found augmenting path with flow: $pathFlow');
      List<int> path = [];
      for (int v = sink; v != -1; v = parent[v]) {
        path.insert(0, v);
      }
      print('Path: ${path.join(' -> ')}');
    }

    return maxFlow;
  }

  print('Original Graph (Capacity Matrix):');
  print('     0   1   2   3   4   5');
  for (int i = 0; i < vertices; i++) {
    String row = '$i: ';
    for (int j = 0; j < vertices; j++) {
      row += graph[i][j].toString().padLeft(4);
    }
    print(row);
  }
  print('');

  int source = 0;
  int sink = 5;

  print('Finding maximum flow from node $source to node $sink...\n');
  int maxFlow = fordFulkerson(source, sink);

  print('\nMaximum flow from source to sink: $maxFlow');

  print('\nFinal Residual Graph:');
  print('     0   1   2   3   4   5');
  for (int i = 0; i < vertices; i++) {
    String row = '$i: ';
    for (int j = 0; j < vertices; j++) {
      row += residualGraph[i][j].toString().padLeft(4);
    }
    print(row);
  }

  print('\nActual flow through edges:');
  for (int i = 0; i < vertices; i++) {
    for (int j = 0; j < vertices; j++) {
      if (graph[i][j] > 0) {
        int flow = graph[i][j] - residualGraph[i][j];
        if (flow > 0) {
          print('Edge ($i -> $j): $flow / ${graph[i][j]}');
        }
      }
    }
  }
}

