  print('=== Original Mutable Collections ===');
  print('List: $mutableList');
  print('Set: $mutableSet');
  print('Map: $mutableMap');

  var unmodifiableListView = List.unmodifiable(mutableList);
  var unmodifiableSetView = Set.unmodifiable(mutableSet);
  var unmodifiableMapView = Map.unmodifiable(mutableMap);

  print('\n=== Unmodifiable Views Created ===');
  print('Unmodifiable List: $unmodifiableListView');
  print('Unmodifiable Set: $unmodifiableSetView');
  print('Unmodifiable Map: $unmodifiableMapView');

  mutableList.add(6);
  mutableSet.add('grape');
  mutableMap['country'] = 'USA';

  print('\n=== After Modifying Original Collections ===');
  print('Original List: $mutableList');
  print('Original Set: $mutableSet');
  print('Original Map: $mutableMap');
  print('Unmodifiable List View: $unmodifiableListView');
  print('Unmodifiable Set View: $unmodifiableSetView');
  print('Unmodifiable Map View: $unmodifiableMapView');

  var immutableList = List.unmodifiable([10, 20, 30, 40]);
  var immutableSet = Set.unmodifiable({'red', 'green', 'blue'});
  var immutableMap = Map.unmodifiable({'x': 100, 'y': 200, 'z': 300});

  print('\n=== Truly Immutable Collections ===');
  print('Immutable List: $immutableList');
  print('Immutable Set: $immutableSet');
  print('Immutable Map: $immutableMap');

  const constList = [1, 2, 3];
  const constSet = {'a', 'b', 'c'};
  const constMap = {'key1': 'value1', 'key2': 'value2'};

  print('\n=== Const Collections (Compile-time Constants) ===');
  print('Const List: $constList');
  print('Const Set: $constSet');
  print('Const Map: $constMap');

  print('\n=== Attempting Modifications (Will Catch Errors) ===');

  try {
    unmodifiableListView.add(7);
  } catch (e) {
    print('Cannot add to unmodifiable list: ${e.runtimeType}');
  }

  try {
    unmodifiableSetView.remove('apple');
  } catch (e) {
    print('Cannot remove from unmodifiable set: ${e.runtimeType}');
  }

  try {
    unmodifiableMapView['newKey'] = 'newValue';
  } catch (e) {
    print('Cannot add to unmodifiable map: ${e.runtimeType}');
  }

  try {
    immutableList[0] = 999;
  } catch (e) {
    print('Cannot modify element in immutable list: ${e.runtimeType}');
  }

  var nestedMutable = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
  ];

  var shallowUnmodifiable = List.unmodifiable(nestedMutable);
  print('\n=== Nested Collections ===');
  print('Shallow unmodifiable nested list: $shallowUnmodifiable');

  nestedMutable[0].add(10);
  print('After modifying inner list: $shallowUnmodifiable');

  var deepUnmodifiable = List.unmodifiable(
    nestedMutable.map((innerList) => List.unmodifiable(innerList))
  );
  print('Deep unmodifiable nested list: $deepUnmodifiable');

  try {

    (deepUnmodifiable[0] as List).add(11);
  } catch (e) {
    print('Cannot modify inner list in deep unmodifiable: ${e.runtimeType}');
  }

  var scores = List.unmodifiable([95, 87, 92, 88, 90]);
  var sum = scores.reduce((a, b) => a + b);
  var average = sum / scores.length;
  var sorted = List.from(scores)..sort();

  print('\n=== Practical Example: Student Scores ===');
  print('Scores (unmodifiable): $scores');
  print('Sum: $sum');
  print('Average: ${average.toStringAsFixed(2)}');
  print('Sorted copy: $sorted');

  List<String> getDaysOfWeek() {
    return List.unmodifiable(['Monday', 'Tuesday', 'Wednesday', 
                              'Thursday', 'Friday', 'Saturday', 'Sunday']);
  }

  var days = getDaysOfWeek();
  print('\n=== Days of Week (Unmodifiable Return) ===');
  print('Days: $days');
  print('First day: ${days.first}');
  print('Last day: ${days.last}');
  print('Weekend: ${days.sublist(5)}');
}

