  }
  if (nonZero.isEmpty) {
    return [];
  }

  int g = nonZero[0];
  for (int i = 1; i < nonZero.length; i++) {
    int a = g;
    int b = nonZero[i];
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    g = a;
  }

  List<int> divisors = [];
  int i = 1;
  while (i * i <= g) {
    if (g % i == 0) {
      if (i >= minSize) {
        divisors.add(i);
      }
      int complement = g ~/ i;
      if (complement != i && complement >= minSize) {
        divisors.add(complement);
      }
    }
    i++;
  }

  divisors.sort();
  return divisors;
