import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> precinctIds, List<List<int>> boundaries, List<List<int>> voteTallies, int zoneLeft, int zoneBottom, int zoneRight, int zoneTop, int hubX, int hubY, int maxHubDistance, int maxMargin) {
  final Set<int> selected = <int>{};
  int count = precinctIds.length;
  if (boundaries.length < count) count = boundaries.length;
  if (voteTallies.length < count) count = voteTallies.length;

  final int zl = zoneLeft < zoneRight ? zoneLeft : zoneRight, zr = zoneLeft < zoneRight ? zoneRight : zoneLeft;
  final int zb = zoneBottom < zoneTop ? zoneBottom : zoneTop, zt = zoneBottom < zoneTop ? zoneTop : zoneBottom;

  for (int i = 0; i < count; i++) {
    if (boundaries[i].length < 4 || voteTallies[i].length < 2) continue;
    final int x1 = boundaries[i][0], y1 = boundaries[i][1], x2 = boundaries[i][2], y2 = boundaries[i][3];
    final int left = x1 < x2 ? x1 : x2, right = x1 < x2 ? x2 : x1;
    final int bottom = y1 < y2 ? y1 : y2, top = y1 < y2 ? y2 : y1;
    if (left == right || bottom == top) continue;

    final int ol = left > zl ? left : zl, orr = right < zr ? right : zr;
    final int ob = bottom > zb ? bottom : zb, ot = top < zt ? top : zt;
    if (ol < orr && ob < ot) {
      final int area = (right - left) * (top - bottom);
      final int overlapArea = (orr - ol) * (ot - ob);
      int margin = voteTallies[i][0] - voteTallies[i][1];
      if (margin < 0) margin = -margin;
      if (margin <= maxMargin) {
        final int doubledDistance = (left + right - 2 * hubX).abs() + (bottom + top - 2 * hubY).abs();
        final bool mostlyInZone = overlapArea * 2 >= area;
        final bool nearHub = doubledDistance <= maxHubDistance * 2;
        if (mostlyInZone || nearHub) selected.add(precinctIds[i]);
      }
    }
  }
  return selected;
}

