double fn0(List<List<int>> zones) {
  if (zones.length < 2) return 0.0;
  final xSet = <int>{}, ySet = <int>{};
  for (final z in zones) {
    xSet.add(z[0]);
    xSet.add(z[2]);
    ySet.add(z[1]);
    ySet.add(z[3]);
  }
  final xs = xSet.toList()..sort();
  final ys = ySet.toList()..sort();
  double total = 0.0;
  for (int i = 0; i < xs.length - 1; i++) {
    for (int j = 0; j < ys.length - 1; j++) {
      final cx1 = xs[i], cx2 = xs[i + 1];
      final cy1 = ys[j], cy2 = ys[j + 1];
      int count = 0;
      for (final z in zones) {
        if (z[0] <= cx1 && z[2] >= cx2 && z[1] <= cy1 && z[3] >= cy2) {
          count++;
        }
      }
      if (count >= 2) {
        total += (cx2 - cx1) * (cy2 - cy1);
      }
    }
  }
  return total;
}

