import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> entryDays, int minGap) {
  if (entryDays.isEmpty) return {};
  List<int> sorted = List.from(entryDays)..sort();
  Set<int> result = {};
  for (int i = 0; i < sorted.length; i++) {
    bool leftOk = (i == 0) || (sorted[i] - sorted[i - 1] >= minGap);
    bool rightOk = (i == sorted.length - 1) || (sorted[i + 1] - sorted[i] >= minGap);
    if (leftOk && rightOk) {
      result.add(sorted[i]);
    }
  }
  return result;
}

