import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String tape) {
  List<String> out = [];
  Map<String, int> votes = {};
  List<String> parts = [];
  String current = '';
  bool quoted = false;

  for (int i = 0; i < tape.length; i++) {
    String ch = tape[i];
    if (ch == "'") {
      if (quoted && i + 1 < tape.length && tape[i + 1] == "'") {
        current += "'";
        i++;
      } else {
        quoted = !quoted;
        current += ch;
      }
    } else if (ch == '|' && !quoted) {
      parts.add(current);
      current = '';
    } else {
      current += ch;
    }
  }
  parts.add(current);

  String? readName(String s) {
    if (s.isEmpty) return null;
    if (s.startsWith("'")) {
      if (!s.endsWith("'") || s.length < 2) return null;
      return s.substring(1, s.length - 1);
    }
    for (int i = 0; i < s.length; i++) {
      int c = s.codeUnitAt(i);
      if (c < 65 || c > 90) return null;
    }
    return s;
  }

  for (String raw in parts) {
    String cmd = raw.trim();
    if (cmd == '*') {
      int best = 0;
      List<String> leaders = [];
      votes.forEach((k, v) {
        if (v > best) {
          best = v;
          leaders = [k];
        } else if (v == best && v > 0) {
          leaders.add(k);
        }
      });
      leaders.sort();
      out.add(best == 0 ? 'NONE' : '${leaders.join('&')}=$best');
    } else if (cmd.startsWith('?')) {
      String? name = readName(cmd.substring(1));
      if (name == null) {
        out.add('ERR');
      } else {
        out.add('$name=${votes[name] ?? 0}');
      }
    } else if (cmd.startsWith('+') || cmd.startsWith('-')) {
      int colon = cmd.lastIndexOf(':');
      if (colon <= 1) {
        out.add('ERR');
        continue;
      }
      String? name = readName(cmd.substring(1, colon));
      int? value = int.tryParse(cmd.substring(colon + 1));
      if (name == null || value == null || value < 0) {
        out.add('ERR');
        continue;
      }
      int next = (votes[name] ?? 0) + (cmd[0] == '+' ? value : -value);
      votes[name] = next < 0 ? 0 : next;
    } else if (cmd.isNotEmpty) {
      out.add('ERR');
    }
  }

  return out;
}

