import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<String> operations) {
  List<int> stack = [];
  List<int> result = [];
  int currentWeight = 0;
  for (String op in operations) {
    if (op == 'UNDO') {
      if (stack.isNotEmpty) {
        currentWeight -= stack.removeLast();
      }
    } else {
      int weight = int.parse(op.substring(4));
      stack.add(weight);
      currentWeight += weight;
    }
    result.add(currentWeight);
  }
  return result;
}

