import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String encoded) {



  if (encoded.isEmpty) return 0.0;
  var totalBuckets = 0;
  var totalEntries = 0;
  for (final seg in encoded.split(',')) {
    final parts = seg.split('x');
    if (parts.length != 2 || parts[0].isEmpty || parts[1].isEmpty) {
      return -1.0;
    }
    var run = 0;
    for (var i = 0; i < parts[0].length; i++) {
      final d = parts[0].codeUnitAt(i) - 48;
      if (d < 0 || d > 9) return -1.0;
      run = run * 10 + d;
    }
    var count = 0;
    for (var i = 0; i < parts[1].length; i++) {
      final d = parts[1].codeUnitAt(i) - 48;
      if (d < 0 || d > 9) return -1.0;
      count = count * 10 + d;
    }
    if (run == 0) return -1.0;
    totalBuckets += run;
    totalEntries += run * count;
  }
  return totalEntries / totalBuckets;
}

