import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String encoded) {
  int pos = 0;
  int n = encoded.length;

  int parse() {
    if (pos >= n) return -1;
    String c = encoded[pos];
    if (c == '0') {
      pos++;
      if (pos + 2 > n) return -1;
      int val = 0;
      for (int i = 0; i < 2; i++) {
        String b = encoded[pos];
        if (b != '0' && b != '1') return -1;
        val = val * 2 + (b == '1' ? 1 : 0);
        pos++;
      }
      return val;
    } else if (c == '1') {
      pos++;
      int left = parse();
      if (left == -1) return -1;
      int right = parse();
      if (right == -1) return -1;
      return left > right ? 2 * left : 2 * right;
    }
    return -1;
  }

  if (n == 0) return -1;
  int result = parse();
  if (result == -1 || pos != n) return -1;
  return result;
}

