import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  var circle = Circle(5.0);
  var rectangle = Rectangle(4.0, 6.0);
  var square = Square(3.0);

  print('Circle with radius ${circle.radius}:');
  print('  Area: ${circle.calculateArea()}');
  print('  Perimeter: ${circle.calculatePerimeter()}');

  print('\nRectangle with width ${rectangle.width} and height ${rectangle.height}:');
  print('  Area: ${rectangle.calculateArea()}');
  print('  Perimeter: ${rectangle.calculatePerimeter()}');

  print('\nSquare with side ${square.side}:');
  print('  Area: ${square.calculateArea()}');
  print('  Perimeter: ${square.calculatePerimeter()}');

  List<Shape> shapes = [circle, rectangle, square];

  print('\nProcessing all shapes:');
  for (var shape in shapes) {
    print('  ${shape.describe()} - Area: ${shape.calculateArea().toStringAsFixed(2)}');
  }

  var red = Color(255, 0, 0);
  var green = Color(0, 255, 0);

  print('\nColors:');
  print('  Red: ${red.toHex()}');
  print('  Green: ${green.toHex()}');

  var user = User.create('Alice', 25);
  var admin = User.createAdmin('Bob', 30);

  print('\nUsers:');
  print('  ${user.toString()}');
  print('  ${admin.toString()}');
}

abstract class Shape {
  double calculateArea();
  double calculatePerimeter();
  String describe();
}

final class Circle extends Shape {
  final double radius;

  Circle(this.radius);

  @override
  double calculateArea() {
    return 3.14159 * radius * radius;
  }

  @override
  double calculatePerimeter() {
    return 2 * 3.14159 * radius;
  }

  @override
  String describe() {
    return 'Circle(radius: $radius)';
  }
}

final class Rectangle extends Shape {
  final double width;
  final double height;

  Rectangle(this.width, this.height);

  @override
  double calculateArea() {
    return width * height;
  }

  @override
  double calculatePerimeter() {
    return 2 * (width + height);
  }

  @override
  String describe() {
    return 'Rectangle(width: $width, height: $height)';
  }
}

final class Square extends Shape {
  final double side;

  Square(this.side);

  @override
  double calculateArea() {
    return side * side;
