import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String grid) {
  if (grid.isEmpty) return [];
  List<String> result = [];
  List<String> rows = grid.split('|');
  for (String row in rows) {
    if (row.isEmpty) continue;
    List<String> cells = row.split(',');
    for (String cell in cells) {
      String trimmed = cell.trim();
      if (trimmed.isEmpty) continue;
      if (trimmed == 'D') {
        result.add('0');
      } else if (trimmed == 'S') {
        result.add('100');
      } else if (trimmed.contains(':')) {
        List<String> parts = trimmed.split(':');
        int start = int.parse(parts[0].trim()).clamp(0, 100);
        int end = int.parse(parts[1].trim()).clamp(0, 100);
        int step = int.parse(parts[2].trim());
        if (step <= 0) step = 1;
        if (start <= end) {
          for (int v = start; v <= end; v += step) result.add(v.toString());
        } else {
          for (int v = start; v >= end; v -= step) result.add(v.toString());
        }
      } else if (trimmed.contains('~')) {
        List<String> parts = trimmed.split('~');
        int start = int.parse(parts[0].trim()).clamp(0, 100);
        int end = int.parse(parts[1].trim()).clamp(0, 100);
        if (start <= end) {
          for (int v = start; v <= end; v += 5) result.add(v.toString());
        } else {
          for (int v = start; v >= end; v -= 5) result.add(v.toString());
        }
      } else {
        int val = int.parse(trimmed).clamp(0, 100);
        result.add(val.toString());
      }
    }
  }
  return result;
}

