        for (int r = 0; r < count; r++) {
          expanded.write(payload);
        }
        i = close + 1;
      } else {
        expanded.write(encodedLog.substring(begin, i));
      }
    } else {
      expanded.writeCharCode(unit);
      i++;
    }
  }
  final back = shift % 26;
  final decoded = StringBuffer();
  for (int j = 0; j < expanded.length; j++) {
    int c = expanded.toString().codeUnitAt(j);
    if (c >= 65 && c <= 90) {
      c = 65 + ((c - 65 - back) % 26);
    } else if (c >= 97 && c <= 122) {
      c = 97 + ((c - 97 - back) % 26);
    }
    decoded.writeCharCode(c);
  }
  for (final record in decoded.toString().split(';')) {
    if (record.isEmpty || record.codeUnitAt(0) != 67) continue;
    final colon = record.indexOf(':');
    if (colon < 2) continue;
    final arrow = record.indexOf('>', colon + 1);
    final hash = record.indexOf('#', arrow + 1);
    if (arrow < 0 || hash < 0) continue;
    final id = int.tryParse(record.substring(1, colon));
    final start = int.tryParse(record.substring(colon + 1, arrow));
    final end = int.tryParse(record.substring(arrow + 1, hash));
    final checksum = int.tryParse(record.substring(hash + 1));
    if (id == null || start == null || end == null || checksum == null) continue;
    if (id < 0 || start < 0 || start > 100 || end < start || end > 100) continue;
    final expected = (id * 17 + start * 3 + end * 5 + 11) % 100;
    if (checksum == expected && end - start >= minimumGain) result.add(id);
  }
  return result;
}

