import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(String manifest) {
  List<int> stack = [];
  int maxDepth = 0;
  int totalSections = 0;
  bool valid = true;
  for (int i = 0; i < manifest.length; i++) {
    if (manifest[i] == '[') {
      stack.add(i);
      if (stack.length > maxDepth) maxDepth = stack.length;
    } else if (manifest[i] == ']') {
      if (stack.isEmpty) {
        valid = false;
        break;
      }
      stack.removeLast();
      totalSections++;
    }
  }
  if (stack.isNotEmpty) valid = false;
  if (!valid) return {"valid": 0, "max_depth": 0, "total_sections": 0};
  return {"valid": 1, "max_depth": maxDepth, "total_sections": totalSections};
}

