import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> logDays) {
  if (logDays.isEmpty) return <int>{};
  int minDay = logDays[0];
  int maxDay = logDays[0];
  Set<int> activeDays = {};
  for (int day in logDays) {
    if (day < minDay) minDay = day;
    if (day > maxDay) maxDay = day;
    activeDays.add(day);
  }
  Set<int> quietDays = {};
  for (int d = minDay; d <= maxDay; d++) {
    if (!activeDays.contains(d)) {
      quietDays.add(d);
    }
  }
  return quietDays;
}

