@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> scheduleHours, List<double> scheduleTemps) {
  List<double> hourlyTemps = List<double>.filled(24, 16.0);
  double currentTemp = 16.0;
  int eventIdx = 0;

  for (int h = 0; h < 24; h++) {
    if (eventIdx < scheduleHours.length && scheduleHours[eventIdx] == h) {
      currentTemp = scheduleTemps[eventIdx];
      eventIdx++;
      while (eventIdx < scheduleHours.length && scheduleHours[eventIdx] == h) {
        currentTemp = scheduleTemps[eventIdx];
        eventIdx++;
      }
    }
    hourlyTemps[h] = currentTemp;
  }

  return hourlyTemps.fold(0.0, (double sum, double t) => sum + t) / 24.0;
}

