bool fn0(List<String> rows) {
  int leading(String s) {
    int n = 0;
    while (n < s.length && s[n] == ' ') n++;
    return n;
  }
  if (rows.isEmpty) return true;
  int p = leading(rows[0]);
  if (p != 0) return false;
  for (int i = 1; i < rows.length; i++) {
    int c = leading(rows[i]);
    if (c != p + 1) return false;
    p = c;
  }
  return true;
}

