import 'dart:async';
import 'dart:convert';
import 'dart:collection';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  bool bfs(List<List<int>> residual, int source, int sink, List<int> parent, int n) {
    List<bool> visited = List<bool>.filled(n, false);
    Queue<int> queue = Queue<int>();

    queue.add(source);
    visited[source] = true;
    parent[source] = -1;

    while (queue.isNotEmpty) {
      int u = queue.removeFirst();

      for (int v = 0; v < n; v++) {
        if (!visited[v] && residual[u][v] > 0) {
          queue.add(v);
          parent[v] = u;
          visited[v] = true;
          if (v == sink) {
            return true;
          }
        }
      }
    }
    return false;
  }

  int n = 6;
  int source = 0;
  int sink = 5;

  List<List<int>> capacity = List.generate(n, (_) => List<int>.filled(n, 0));

  capacity[0][1] = 16;
  capacity[0][2] = 13;
  capacity[1][2] = 10;
  capacity[1][3] = 12;
  capacity[2][1] = 4;
  capacity[2][4] = 14;
  capacity[3][2] = 9;
  capacity[3][5] = 20;
  capacity[4][3] = 7;
  capacity[4][5] = 4;

  List<List<int>> residual = List.generate(n, (i) => List<int>.from(capacity[i]));

  List<int> parent = List<int>.filled(n, -1);

  int maxFlow = 0;

  while (bfs(residual, source, sink, parent, n)) {

    int pathFlow = 9223372036854775807; 
    for (int v = sink; v != source; v = parent[v]) {
      int u = parent[v];
      pathFlow = min(pathFlow, residual[u][v]);
    }

    for (int v = sink; v != source; v = parent[v]) {
      int u = parent[v];
      residual[u][v] -= pathFlow;
      residual[v][u] += pathFlow;
    }

    maxFlow += pathFlow;
  }

  print('Max flow: $maxFlow'); 
}

