Map<String, int> fn0(List<String> playlist, int maxRepeat) {
  if (playlist.isEmpty || maxRepeat <= 0) return {};
  Map<String, int> current = {};
  int left = 0;
  int bestLen = -1;
  int bestStart = -1;
  Map<String, int> bestCounts = {};
  for (int right = 0; right < playlist.length; right++) {
    String song = playlist[right];
    current[song] = (current[song] ?? 0) + 1;
    while (current[song]! > maxRepeat && left <= right) {
      String out = playlist[left];
      current[out] = current[out]! - 1;
      if (current[out] == 0) current.remove(out);
      left++;
    }
    int len = right - left + 1;
    if (len > bestLen) {
      bestLen = len;
      bestStart = left;
      bestCounts = Map<String, int>.from(current);
    }
  }
  return bestCounts;
}

