import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(int period1, int offset1, int period2, int offset2) {




  int a = offset1 % period1;
  int b = offset2 % period2;

  int oldR = period1, r = period2;
  int oldS = 1, s = 0;
  while (r != 0) {
    int q = oldR ~/ r;
    int tmp = oldR - q * r;
    oldR = r;
    r = tmp;
    tmp = oldS - q * s;
    oldS = s;
    s = tmp;
  }
  int g = oldR;
  if ((b - a) % g != 0) return -1;
  int m = period2 ~/ g; 
  int mult = ((b - a) ~/ g) % m;
  int x = (mult * (oldS % m)) % m;
  if (x < 0) x += m;
  int t = a + period1 * x;
  int lcm = period1 ~/ g * period2;
  return t % lcm;
}

