double fn0(List<List<double>> grid) {
  Map<double, int> counts = {};
  double bestValue = 0.0;
  int bestCount = 0;

  for (List<double> row in grid) {
    for (double value in row) {
      int nextCount = (counts[value] ?? 0) + 1;
      counts[value] = nextCount;
      if (nextCount > bestCount ||
          (nextCount == bestCount && value > bestValue)) {
        bestCount = nextCount;
        bestValue = value;
      }
    }
  }

  return bestValue;
}

