import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {



  final List<int> numbers = [170, 45, 75, 90, 802, 24, 2, 66];
  print('Before sorting: $numbers');

  int getMax(List<int> list) {
    int maxVal = list.first;
    for (var value in list.skip(1)) {
      if (value > maxVal) maxVal = value;
    }
    return maxVal;
  }

  void countingSort(List<int> list, int exp) {
    final int n = list.length;
    final output = List<int>.filled(n, 0); 
    final count  = List<int>.filled(10, 0); 

    for (var value in list) {
      final int digit = (value ~/ exp) % 10;
      count[digit]++;
    }

    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    for (int i = n - 1; i >= 0; i--) {
      final int digit = (list[i] ~/ exp) % 10;
      output[count[digit] - 1] = list[i];
      count[digit]--;
    }

    for (int i = 0; i < n; i++) {
      list[i] = output[i];
    }
  }

  for (int exp = 1, maxVal = getMax(numbers); maxVal ~/ exp > 0; exp *= 10) {
    countingSort(numbers, exp);
  }

  print('After sorting:  $numbers');
}

