@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String stream) {
  List<int> contentLengths = [];
  bool insideSample = false;
  for (int i = 0; i < stream.length; i++) {
    String ch = stream[i];
    if (ch == '<') {
      contentLengths.add(0);
      insideSample = true;
      if (contentLengths.length > 3) return false;
    } else if (ch == '>') {
      if (contentLengths.isEmpty) return false;
      int contentLen = contentLengths.removeLast();
      if (contentLen == 0) return false;
      if (contentLengths.isNotEmpty) {
        contentLengths[contentLengths.length - 1]++;
      }
      insideSample = contentLengths.isNotEmpty;
    } else if (ch == '!') {
      if (!insideSample) return false;
      contentLengths[contentLengths.length - 1]++;
    } else {
      if (contentLengths.isNotEmpty) {
        contentLengths[contentLengths.length - 1]++;
      }
    }
  }
  return contentLengths.isEmpty;
}

