double fn0(List<int> towerX, List<int> floorY) {
  if (towerX.length <= 1) {
    return 0.0;
  }
  int totalDistance = 0;
  for (int i = 0; i < towerX.length - 1; i++) {
    int dx = (towerX[i + 1] - towerX[i]).abs();
    int dy = (floorY[i + 1] - floorY[i]).abs();
    totalDistance += dx + dy;
  }
  return totalDistance.toDouble() / (towerX.length - 1);
}

