bool fn0(String encoded, int expectedTotal) {
  if (encoded.isEmpty) {
    return expectedTotal == 0;
  }
  int totalBrightness = 0;
  List<String> groups = encoded.split(',');
  for (String group in groups) {
    try {
      int colonIndex = group.indexOf(':');
      if (colonIndex != 9) return false;
      String rgbPart = group.substring(0, 9);
      String countPart = group.substring(colonIndex + 1);
      int r = int.parse(rgbPart.substring(0, 3));
      int g = int.parse(rgbPart.substring(3, 6));
      int b = int.parse(rgbPart.substring(6, 9));
      int count = int.parse(countPart);
      if (count < 0) return false;
      totalBrightness += (r + g + b) * count;
    } catch (_) {
      return false;
    }
  }
  return totalBrightness == expectedTotal;
}

