@pragma('vm:entry-point')
void fn0() {
  SkipList skipList = SkipList();

  skipList.insert(3);
  skipList.insert(6);
  skipList.insert(7);
  skipList.insert(9);
  skipList.insert(12);
  skipList.insert(19);
  skipList.insert(17);
  skipList.insert(26);
  skipList.insert(21);
  skipList.insert(25);

  skipList.printList();

  print('Search for 19: ${skipList.search(19)}'); 
  print('Search for 15: ${skipList.search(15)}'); 

  skipList.delete(19);
  print('After deleting 19:');
  skipList.printList();

  print('Search for 19 after deletion: ${skipList.search(19)}'); 
}

