  final body = manifest.substring(0, hashIdx);
  final checkStr = manifest.substring(hashIdx + 1);
  for (var k = 0; k < checkStr.length; k++) {
    final c = checkStr.codeUnitAt(k);
    if (c < 48 || c > 57) return {};
  }
  final expected = int.parse(checkStr);
  final result = <String, int>{};
  var i = 0;
  var segIndex = 0;
  var weighted = 0;
  while (i < body.length) {
    final codeStart = i;
    while (i < body.length) {
      final c = body.codeUnitAt(i);
      if (c >= 97 && c <= 122) {
        i++;
      } else {
        break;
      }
    }
    if (i == codeStart) return {};
    final code = body.substring(codeStart, i);
    final numStart = i;
    while (i < body.length) {
      final c = body.codeUnitAt(i);
      if (c >= 48 && c <= 57) {
        i++;
      } else {
        break;
      }
    }
    if (i == numStart) return {};
    final count = int.parse(body.substring(numStart, i));
    segIndex++;
    weighted += count * segIndex;
    if (count > 0) {
      result[code] = (result[code] ?? 0) + count;
    }
  }
  if (segIndex == 0) return {};
  if (weighted % 97 != expected) return {};
  return result;
}

