@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(int total, List<int> targetSizes, int minFrag) {
  if (targetSizes.isEmpty) return false;
  int sum = 0;
  for (int s in targetSizes) sum += s;
  if (sum != total) return false;
  if (targetSizes.length == 1) return targetSizes[0] >= minFrag && targetSizes[0] == total;
  int n = targetSizes.length;
  for (int mask = 1; mask < (1 << n) - 1; mask++) {
    int sumA = 0, sumB = 0;
    List<int> groupA = [], groupB = [];
    for (int i = 0; i < n; i++) {
      if ((mask & (1 << i)) != 0) {
        sumA += targetSizes[i];
        groupA.add(targetSizes[i]);
      } else {
        sumB += targetSizes[i];
        groupB.add(targetSizes[i]);
      }
    }
    if (sumA >= minFrag && sumB >= minFrag) {
      if (fn0(sumA, groupA, minFrag) &&
          fn0(sumB, groupB, minFrag)) {
        return true;
      }
    }
  }
  return false;
}

