Map<String, int> fn0(String ledger) {
  var deposits = 0, withdrawals = 0, fees = 0, i = 0;
  while (i < ledger.length) {
    while (i < ledger.length && ledger[i] == ' ') i++;
    if (i >= ledger.length) break;
    var code = ledger[i++], amount = 0;
    while (i < ledger.length && ledger[i] != ' ') amount = amount * 10 + ledger[i++].codeUnitAt(0) - 48;
