import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<String> log) {
  final edits = <String>[];
  final redoStack = <String>[];
  double penalty = 0.0;
  for (final entry in log) {
    if (entry.startsWith('edit:')) {
      edits.add(entry.substring(5));
      redoStack.clear();
    } else if (entry == 'undo') {
      if (edits.isNotEmpty) {
        redoStack.add(edits.removeLast());
      } else {
        penalty += 0.25;
      }
    } else if (entry == 'redo') {
      if (redoStack.isNotEmpty) {
        edits.add(redoStack.removeLast());
      } else {
        penalty += 0.25;
      }
    }
  }
  double total = 0.0;
  for (final word in edits) {
    total += word.length * 0.5;
  }
  return total - penalty;
}

