import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<int> dailyErrors) {
  if (dailyErrors.isEmpty) return "no period";
  int n = dailyErrors.length;
  List<int> dp = List<int>.filled(n, 1);
  int maxLen = 1;
  int endIdx = 0;
  for (int i = 1; i < n; i++) {
    if (dailyErrors[i] >= dailyErrors[i - 1]) {
      dp[i] = dp[i - 1] + 1;
      if (dp[i] > maxLen) {
        maxLen = dp[i];
        endIdx = i;
      }
    }
  }
  int start = endIdx - maxLen + 1;
  return "$start-$endIdx:$maxLen";
}

