import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> requests, int maxTravel, int minSize, int maxSize) {
  if (requests.isEmpty || minSize > maxSize || minSize <= 0) {
    return 0;
  }
  var req = List<int>.from(requests)..sort();
  int count = 0;
  int left = 0;
  for (int right = 0; right < req.length; right++) {
    while (req[right] - req[left] > maxTravel) {
      left++;
    }
    int lower = left > (right - maxSize + 1) ? left : (right - maxSize + 1);
    int upper = right - minSize + 1;
    if (lower <= upper) {
      count += (upper - lower + 1);
    }
  }
  return count;
}

