import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {


  List<int> data = [3, 2, -1, 6, 5, 4, -3, 3, 7, 2, 3];
  int n = data.length;

  List<int> tree = List.filled(n + 1, 0);

  int lsb(int x) => x & -x;

  void update(int idx, int delta) {
    while (idx <= n) {
      tree[idx] += delta;
      idx += lsb(idx);
    }
  }

  int prefixSum(int idx) {
    int result = 0;
    while (idx > 0) {
      result += tree[idx];
      idx -= lsb(idx);
    }
    return result;
  }

  for (int i = 0; i < n; i++) {
    update(i + 1, data[i]);
  }

  print('Initial data: $data');
  print('Sum of first 5 elements: ${prefixSum(5)}');              
  print('Sum of range 3 to 7: ${prefixSum(7) - prefixSum(2)}');   

  update(3, 4);
  data[2] += 4;

  print('\nAfter adding 4 to index 3:');
  print('Updated data: $data');
  print('Sum of first 5 elements: ${prefixSum(5)}');              
  print('Sum of range 3 to 7: ${prefixSum(7) - prefixSum(2)}');
}

