import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> stacks) {
  final result = <String, int>{};
  for (final stack in stacks) {
    final colonIndex = stack.lastIndexOf(':');
    if (colonIndex == -1) {
      result[stack] = (result[stack] ?? 0) + 1;
    } else {
      final item = stack.substring(0, colonIndex);
      final count = int.parse(stack.substring(colonIndex + 1));
      result[item] = (result[item] ?? 0) + count;
    }
  }
  return result;
}

