import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> cycleReadings) {
  if (cycleReadings.isEmpty) {
    return 0.0;
  }

  Map<int, int> bandCounts = {};
  Set<int> seenReadings = {};
  Set<int> repeatedReadings = {};

  for (int reading in cycleReadings) {
    int band = reading ~/ 100;
    bandCounts[band] = (bandCounts[band] ?? 0) + 1;

    if (seenReadings.contains(reading)) {
      repeatedReadings.add(reading);
    } else {
      seenReadings.add(reading);
    }
  }

  double score = 0.0;

  bandCounts.forEach((int band, int count) {
    if (count >= 4) {
      score += 2.0;
    } else if (count >= 2) {
      score += 1.0;
    } else {
      score += 0.5;
    }

    if (band >= 5) {
      score += 0.5;
    }
  });

  score += repeatedReadings.length * 0.25;
  return score;
}

