import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> edits) {
  int totalArea = 0;
  Map<int, List<List<int>>> intervalsByRow = {};
  for (var edit in edits) {
    int row = edit[0];
    int start = edit[1];
    int end = edit[2];
    int length = end - start + 1;
    totalArea += length;
    intervalsByRow.putIfAbsent(row, () => []).add([start, end]);
  }

  int overlapArea = 0;
  intervalsByRow.forEach((row, intervals) {
    List<List<int>> events = [];
    for (var interval in intervals) {
      events.add([interval[0], 1]);
      events.add([interval[1] + 1, -1]);
    }
    events.sort((a, b) => a[0].compareTo(b[0]));
    int coverage = 0;
    int prevPos = events.isNotEmpty ? events[0][0] : 0;
    for (var event in events) {
      int pos = event[0];
      int delta = event[1];
      if (coverage >= 2) {
        overlapArea += pos - prevPos;
      }
      coverage += delta;
      prevPos = pos;
    }
  });

  int maxManhattanDistance = 0;
  for (int i = 0; i < edits.length; i++) {
    for (int j = i + 1; j < edits.length; j++) {
      int d = (edits[i][0] - edits[j][0]).abs() + (edits[i][1] - edits[j][1]).abs();
      if (d > maxManhattanDistance) maxManhattanDistance = d;
    }
  }

  return {
    'totalArea': totalArea,
    'overlapArea': overlapArea,
    'maxManhattanDistance': maxManhattanDistance,
  };
}

