import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> barcodeDigits) {
  List<int> stack = [];
  for (int i = 0; i < barcodeDigits.length; i++) {
    int d = barcodeDigits[i];
    if (stack.isNotEmpty && barcodeDigits[stack.last] + d == 9) {
      stack.removeLast();
    } else {
      stack.add(i);
    }
  }
  return stack.map((i) => barcodeDigits[i]).toSet();
}

