import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> pixels) {
  Map<String, int> result = {
    'dark': 0,
    'mid': 0,
    'bright': 0,
    'redDominant': 0,
    'greenDominant': 0,
    'blueDominant': 0,
    'clipped': 0,
  };

  List<int>? previous;

  for (List<int> pixel in pixels) {
    if (pixel.length != 3) {
      continue;
    }

    if (previous != null &&
        previous[0] == pixel[0] &&
        previous[1] == pixel[1] &&
        previous[2] == pixel[2]) {
      continue;
    }

    previous = [pixel[0], pixel[1], pixel[2]];

    int r = pixel[0];
    int g = pixel[1];
    int b = pixel[2];

    if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
      result['clipped'] = result['clipped']! + 1;
    }

    int brightness = (r + g + b) ~/ 3;

    if (brightness < 64) {
      result['dark'] = result['dark']! + 1;
    } else if (brightness >= 192) {
      result['bright'] = result['bright']! + 1;
    } else {
      result['mid'] = result['mid']! + 1;
    }

    if (r > g && r > b) {
      result['redDominant'] = result['redDominant']! + 1;
    } else if (g > r && g > b) {
      result['greenDominant'] = result['greenDominant']! + 1;
    } else if (b > r && b > g) {
      result['blueDominant'] = result['blueDominant']! + 1;
    }
  }

  return result;
}

