@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> days, List<int> signals) {
  if (days.isEmpty) return 0.0;
  if (days.length != signals.length) throw ArgumentError('Length mismatch');
  int minDay = days[0];
  int maxDay = days[0];
  for (int d in days) {
    if (d < minDay) minDay = d;
    if (d > maxDay) maxDay = d;
  }
  int totalDays = maxDay - minDay + 1;
  List<int> freq = List<int>.filled(5, 0);
  for (int i = 0; i < days.length; i++) {
    int signal = signals[i];
    int bin;
    if (signal >= -50) bin = 4;
    else if (signal >= -60) bin = 3;
    else if (signal >= -70) bin = 2;
    else if (signal >= -80) bin = 1;
    else bin = 0;
    freq[bin]++;
  }
  int missingDays = totalDays - days.length;
  freq[0] += missingDays;
  int mid1 = (totalDays - 1) >> 1;
  int mid2 = totalDays >> 1;
  int count = 0;
  int val1 = -1, val2 = -1;
  for (int b = 0; b < 5; b++) {
    int f = freq[b];
    if (f == 0) continue;
    int start = count;
    int end = count + f - 1;
    if (val1 == -1 && mid1 >= start && mid1 <= end) {
      val1 = b;
    }
    if (val2 == -1 && mid2 >= start && mid2 <= end) {
      val2 = b;
    }
    if (val1 != -1 && val2 != -1) break;
    count += f;
  }
  return (val1 + val2) / 2.0;
}

