@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> barcodes, int index) {
  int digitSum(int n) {
    int sum = 0;
    n = n.abs();
    while (n > 0) {
      sum += n % 10;
      n ~/= 10;
    }
    return sum;
  }
  final sorted = List<int>.from(barcodes);
  sorted.sort((a, b) {
    int sa = digitSum(a);
    int sb = digitSum(b);
    if (sa != sb) return sa.compareTo(sb);
    return a.compareTo(b);
  });
  return sorted[index];
}

