import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String fenRanks) {
  const whiteValues = {'P': 1, 'N': 3, 'B': 3, 'R': 5, 'Q': 9, 'K': 0};
  const blackValues = {'p': 1, 'n': 3, 'b': 3, 'r': 5, 'q': 9, 'k': 0};
  int whiteSum = 0;
  int blackSum = 0;
  List<String> ranks = fenRanks.split('/');
  if (ranks.length != 8) return 0.0;
  for (int rowIdx = 0; rowIdx < 8; rowIdx++) {
    int rank = 8 - rowIdx;
    int file = 1;
    for (int i = 0; i < ranks[rowIdx].length; i++) {
      String ch = ranks[rowIdx][i];
      if (ch.codeUnitAt(0) >= 49 && ch.codeUnitAt(0) <= 56) {
        int emptyCount = int.parse(ch);
        file += emptyCount;
      } else {
        if ((file + rank) % 2 == 1) {
          if (ch == ch.toUpperCase()) {
            whiteSum += whiteValues[ch] ?? 0;
          } else {
            blackSum += blackValues[ch] ?? 0;
          }
        }
        file += 1;
      }
    }
  }
  return (whiteSum - blackSum).toDouble();
}

