import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> entryDays, List<int> balances) {
  if (entryDays.isEmpty || balances.isEmpty) {
    return [0, 0, 0, 0, 0];
  }
  int minDay = entryDays[0];
  int maxDay = entryDays[0];
  int minBalance = balances[0];
  int maxBalance = balances[0];
  for (int i = 1; i < entryDays.length; i++) {
    if (entryDays[i] < minDay) minDay = entryDays[i];
    if (entryDays[i] > maxDay) maxDay = entryDays[i];
    if (balances[i] < minBalance) minBalance = balances[i];
    if (balances[i] > maxBalance) maxBalance = balances[i];
  }
  int area = (maxDay - minDay) * (maxBalance - minBalance);
  return [minDay, minBalance, maxDay, maxBalance, area];
}

