import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  List<int> data;
  {
    final parsed = <int>[];
    for (final a in args) {
      for (final m in RegExp(r'-?\d+').allMatches(a)) {
        parsed.add(int.parse(m.group(0)!));
      }
    }
    data = parsed.isNotEmpty
        ? parsed
        : <int>[-2, 9, 5, 0, -2, 3, 1, 0, 3, 3]; 
  }

  print('Input: $data');

  if (data.isEmpty) {
    print('Sorted: []');
    return;
  }

  int minVal = data[0];
  int maxVal = data[0];
  for (final v in data) {
    if (v < minVal) minVal = v;
    if (v > maxVal) maxVal = v;
  }

  final int rangeSize = maxVal - minVal + 1;

  const int maxRangeForCountingSort = 1000000;

  List<int> sorted;
  if (rangeSize <= maxRangeForCountingSort) {

    final counts = Uint32List(rangeSize); 
    for (final v in data) {
      counts[v - minVal]++;
    }

    for (int i = 1; i < counts.length; i++) {
      counts[i] += counts[i - 1];
    }

    final out = List<int>.filled(data.length, 0);
    for (int i = data.length - 1; i >= 0; i--) {
      final v = data[i];
      final idx = v - minVal;
      final pos = --counts[idx];
      out[pos] = v;
    }

    sorted = out;
    print('Sorted (counting sort, range ${minVal}..${maxVal}, size $rangeSize): $sorted');
  } else {

    sorted = List<int>.from(data)..sort();
    print('Sorted (fallback, range too large: size $rangeSize): $sorted');
  }
}

