@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<List<String>> shelves) {
  if (shelves.isEmpty) return [];
  int rows = shelves.length;
  int maxCols = 0;
  for (int i = 0; i < rows; i++) {
    if (shelves[i].length > maxCols) {
      maxCols = shelves[i].length;
    }
  }
  if (maxCols == 0) return [];

  List<String> result = [];
  for (int k = 0; k < rows + maxCols - 1; k++) {
    List<String> diag = [];
    for (int r = 0; r < rows; r++) {
      int c = k - r;
      if (c >= 0 && c < shelves[r].length) {
        String code = shelves[r][c];
        if (code.isNotEmpty) {
          diag.add(code);
        }
      }
    }
    diag.sort((a, b) {
      int cmp = a.toLowerCase().compareTo(b.toLowerCase());
      return cmp == 0 ? a.compareTo(b) : cmp;
    });
    result.add(diag.join('-'));
  }
  return result;
}

