@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> packetSizesPerDay, int startDay, int dayCount) {
  if (packetSizesPerDay.isEmpty || dayCount <= 0) {
    return 0.0;
  }
  int sum = 0;
  int patternLength = packetSizesPerDay.length;
  for (int i = startDay; i < startDay + dayCount; i++) {
    int idx = i % patternLength;
    sum += packetSizesPerDay[idx];
  }
  return sum.toDouble();
}

