import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<String> codes) {
  Map<String, String> matches = {'(': ')', '[': ']', '{': '}'};
  Map<String, int> weights = {'[': 1, '(': 2, '{': 3};
  List<int> results = [];

  for (String code in codes) {
    List<String> bracketStack = [];
    int currentMultiplier = 1;
    int priority = 0;
    bool valid = true;

    for (int i = 0; i < code.length; i++) {
      String ch = code[i];
      if (matches.containsKey(ch)) {
        bracketStack.add(ch);
        currentMultiplier *= weights[ch]!;
      } else if (ch == ')' || ch == ']' || ch == '}') {
        if (bracketStack.isEmpty) {
          valid = false;
          break;
        }
        String open = bracketStack.removeLast();
        if (matches[open] != ch) {
          valid = false;
          break;
        }
        currentMultiplier ~/= weights[open]!;
      } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        priority += int.parse(ch) * currentMultiplier;
      }
    }

    if (!valid || bracketStack.isNotEmpty) {
      results.add(-1);
    } else {
      results.add(priority);
    }
  }

  return results;
}

