    if (ledger[i].length < 2) return false;
  }
  for (int r = 0; r < ledger.length - 1; r++) {
    int cols = ledger[r].length < ledger[r + 1].length
        ? ledger[r].length
        : ledger[r + 1].length;
    for (int c = 0; c < cols - 1; c++) {
      int tl = ledger[r][c];
      int tr = ledger[r][c + 1];
      int bl = ledger[r + 1][c];
      int br = ledger[r + 1][c + 1];
      int total = tl + tr + bl + br;
      if (tl > 0 && br > 0 && tr < 0 && bl < 0 && total == 0) {
        return true;
      }
      if (tr > 0 && bl > 0 && tl < 0 && br < 0 && total == 0) {
        return true;
      }
    }
  }
  return false;
}

