  if (serverLogDays.isEmpty) return false;
  if (daysInCalendar <= 0) return false;

  final uniqueDays = <int>{};
  for (final day in serverLogDays) {
    if (day >= 0 && day < daysInCalendar) {
      uniqueDays.add(day);
    }
  }

  if (uniqueDays.length < requiredConsecutiveDays) return false;

  for (int start = 0; start < daysInCalendar; start++) {
    int count = 0;
    int current = start;
    while (uniqueDays.contains(current)) {
      count++;
      if (count >= requiredConsecutiveDays) return true;
      current = (current + 1) % daysInCalendar;
    }
  }
  return false;
}

