Map<String, int> fn0(List<int> manifests) {
  int fragile = 0;
  int refrigerated = 0;
  int hazardous = 0;
  int totalFlags = 0;
  for (final code in manifests) {
    if ((code & 1) != 0) fragile++;
    if ((code & 2) != 0) refrigerated++;
    if ((code & 4) != 0) hazardous++;
    int bits = code;
    while (bits > 0) {
      totalFlags += bits & 1;
      bits >>= 1;
    }
  }
  return {
    'fragile': fragile,
    'refrigerated': refrigerated,
    'hazardous': hazardous,
    'totalFlags': totalFlags
  };
}

