import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String rle) {
  if (rle.isEmpty) return 0;
  int totalScore = 0;
  int currentPosition = 1;
  int i = 0;
  const int modulo = 1000007;

  while (i < rle.length) {
    int charCode = rle.codeUnitAt(i);
    if (charCode < 65 || charCode > 90) return -1;
    i++;

    if (i >= rle.length) return -1;

    int count = 0;
    bool hasDigit = false;
    while (i < rle.length) {
      int digitCode = rle.codeUnitAt(i);
      if (digitCode >= 48 && digitCode <= 57) {
        count = count * 10 + (digitCode - 48);
        hasDigit = true;
        i++;
      } else {
        break;
      }
    }

    if (!hasDigit || count <= 0) return -1;

    int n1 = count;
    int n2 = 2 * currentPosition + count - 1;
    int indexSum = (n1 % 2 == 0) ? (n1 ~/ 2) * n2 : n1 * (n2 ~/ 2);

    int blockScore = (charCode * (indexSum % modulo)) % modulo;
    totalScore = (totalScore + blockScore) % modulo;
    currentPosition += count;
  }

  return totalScore;
}

