List<int> fn0(List<int> packetStream) {
  List<int> stack = [];
  for (int value in packetStream) {
    if (value > 0) {
      stack.add(value);
    } else if (value < 0) {
      stack.add(value);
    } else {
      int markerIndex = -1;
      for (int i = stack.length - 1; i >= 0; i--) {
        if (stack[i] < 0) {
          markerIndex = i;
          break;
        }
      }
      if (markerIndex >= 0) {
        int sum = 0;
        while (stack.length > markerIndex) {
          int popped = stack.removeLast();
          if (popped > 0) {
            sum += popped;
          } else {
            sum += -popped;
          }
        }
        stack.add(sum);
      }
    }
  }
  return stack;
}

