@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<int> availableGrams, int baseGrams, double scaleFactor, String ingredientName) {
  final needed = baseGrams * scaleFactor;
  var left = 0;
  var right = availableGrams.length;
  while (left < right) {
    final mid = (left + right) ~/ 2;
    if (availableGrams[mid] < needed) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  if (left == availableGrams.length) return 'No package large enough for $ingredientName';
  return 'Buy ${availableGrams[left]}g $ingredientName';
}

