Set<int> fn0(List<int> rolls, int targetSum) {
  int start = 0, end = 0, currentSum = 0;
  Set<int> result = {};
  while (end < rolls.length) {
    currentSum += rolls[end++];
    while (currentSum > targetSum && start < end) {
      currentSum -= rolls[start++];
    }
    if (currentSum == targetSum && start < end) {
      result.add(start);
      currentSum -= rolls[start++];
    }
  }
  return result;
}

