import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String line) {




  final results = <String>[];
  final n = line.length;
  int i = 0;
  while (i <= n) {
    final start = i;
    while (i < n && line[i] != ',') {
      i++;
    }
    final raw = line.substring(start, i).trim();
    i++;
    if (raw.isEmpty) continue;
    int state = 0; 
    final qty = StringBuffer();
    final code = StringBuffer();
    bool fragile = false;
    bool bad = false;
    for (int j = 0; j < raw.length && !bad; j++) {
      final u = raw.codeUnitAt(j);
      if (state == 0) {
        if (u >= 49 && u <= 57) {
          qty.writeCharCode(u);
          state = 1;
        } else {
          bad = true;
        }
      } else if (state == 1) {
        if (u >= 48 && u <= 57) {
          qty.writeCharCode(u);
        } else if (u == 120) {
          state = 2;
        } else {
          bad = true;
        }
      } else if (state == 2) {
        if (u >= 65 && u <= 90) {
          code.writeCharCode(u);
          if (code.length > 5) bad = true;
        } else if (u == 33 && code.length >= 3) {
          fragile = true;
          state = 3;
        } else {
          bad = true;
        }
      } else {
        bad = true;
      }
    }
    if (!bad && (state == 3 || (state == 2 && code.length >= 3))) {
      results.add((fragile ? 'FRAGILE:' : '') + code.toString() + '*' + qty.toString());
    } else {
      results.add('BAD');
    }
  }
  return results;
}

