Map<String, int> fn0(List<String> squares) {
  if (squares.isEmpty) return {'minDay': 0, 'maxDay': 0, 'spanDays': 0};
  int min = 64, max = -1;
  for (String sq in squares) {
    int file = sq.codeUnitAt(0) - 'a'.codeUnitAt(0);
    int rank = int.parse(sq[1]) - 1;
    int day = file * 8 + rank;
    if (day < min) min = day;
    if (day > max) max = day;
  }
  return {'minDay': min, 'maxDay': max, 'spanDays': max - min};
}

