import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<List<int>> grid) {
  int rows = grid.length;
  if (rows == 0) return [0, -1, -1];
  int cols = grid[0].length;
  if (cols == 0) return [0, -1, -1];

  int maxLen = 0;
  int bestStartRow = -1;
  int bestStartCol = -1;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == 1) {
        int len = 1;
        while (c + len < cols && grid[r][c + len] == 1) {
          len++;
        }
        if (len > maxLen) {
          maxLen = len;
          bestStartRow = r;
          bestStartCol = c;
        } else if (len == maxLen && len > 0) {
          if (r < bestStartRow || (r == bestStartRow && c < bestStartCol)) {
            bestStartRow = r;
            bestStartCol = c;
          }
        }
        c += len - 1;
      }
    }
  }

  return [maxLen, bestStartRow, bestStartCol];
}

