void fn0() {

  List<int> nums1 = [1, 2, 3];
  List<int> nums2 = [1, 2];
  List<String> chars = ['A', 'B', 'C'];

  print('Permutations of $nums1:');
  List<List<int>> result1 = [];
  List<int> current1 = [];
  List<bool> used1 = List.filled(nums1.length, false);

  void backtrack1(List<int> nums, List<int> current, List<bool> used, List<List<int>> result) {

    if (current.length == nums.length) {
      result.add(List.from(current));
      return;
    }

    for (int i = 0; i < nums.length; i++) {
      if (used[i]) continue;

      current.add(nums[i]);
      used[i] = true;

      backtrack1(nums, current, used, result);

      current.removeLast();
      used[i] = false;
    }
  }

  backtrack1(nums1, current1, used1, result1);
  for (var perm in result1) {
    print(perm);
  }

  print('\nPermutations of $nums2:');
  List<List<int>> result2 = [];
  List<int> current2 = [];
  List<bool> used2 = List.filled(nums2.length, false);

  void backtrack2(List<int> nums, List<int> current, List<bool> used, List<List<int>> result) {
    if (current.length == nums.length) {
      result.add(List.from(current));
      return;
    }

    for (int i = 0; i < nums.length; i++) {
      if (used[i]) continue;

      current.add(nums[i]);
      used[i] = true;
      backtrack2(nums, current, used, result);
      current.removeLast();
      used[i] = false;
    }
  }

  backtrack2(nums2, current2, used2, result2);
  for (var perm in result2) {
    print(perm);
  }

  print('\nPermutations of $chars:');
  List<List<String>> result3 = [];
  List<String> current3 = [];
  List<bool> used3 = List.filled(chars.length, false);

  void backtrack3(List<String> items, List<String> current, List<bool> used, List<List<String>> result) {
    if (current.length == items.length) {
      result.add(List.from(current));
      return;
    }

    for (int i = 0; i < items.length; i++) {
      if (used[i]) continue;

      current.add(items[i]);
      used[i] = true;
      backtrack3(items, current, used, result);
      current.removeLast();
      used[i] = false;
    }
  }

  backtrack3(chars, current3, used3, result3);
  for (var perm in result3) {
    print(perm);
  }

  print('\nPermutations using swap method for [1, 2, 3]:');
  List<int> nums3 = [1, 2, 3];
  List<List<int>> result4 = [];

  void permuteSwap(List<int> nums, int start, List<List<int>> result) {
    if (start == nums.length) {
      result.add(List.from(nums));
      return;
    }

    for (int i = start; i < nums.length; i++) {

      int temp = nums[start];
      nums[start] = nums[i];
      nums[i] = temp;

      permuteSwap(nums, start + 1, result);

      temp = nums[start];
      nums[start] = nums[i];
      nums[i] = temp;
    }
  }

  permuteSwap(nums3, 0, result4);
  for (var perm in result4) {
    print(perm);
  }

  print('\nTotal permutations of [1, 2, 3]: ${result1.length}');
  print('Expected (3!): ${3 * 2 * 1}');
}

