    return 0.0;
  }
  double total = 0.0;
  for (int i = 0; i < switchTimes.length; i++) {
    int segStart = switchTimes[i];
    int segEnd = (i + 1 < switchTimes.length) ? switchTimes[i + 1] : 1440;
