import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String playlist) {
  if (playlist.isEmpty) return 0.0;
  int originalLength = playlist.length;
  int encodedLength = 0;

  int vlqBytes(int value) {
    int bytes = 0;
    do {
      bytes++;
      value >>= 7;
    } while (value > 0);
    return bytes;
  }

  int i = 0;
  while (i < originalLength) {
    int runStart = i;
    String current = playlist[i];
    while (i < originalLength && playlist[i] == current) {
      i++;
    }
    int runLength = i - runStart;
    encodedLength += 1 + vlqBytes(runLength);
  }
  return originalLength / encodedLength;
}

