import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(String input) {
  int r = 0, g = 0, b = 0, pixels = 0, inversions = 0;
  String ch = '';
  int acc = -1;
  void commit() {
    if (acc >= 0 && ch.isNotEmpty) {
      int v = acc > 255 ? 255 : acc;
      if (ch == 'r') r = v;
      else if (ch == 'g') g = v;
      else b = v;
    }
    acc = -1; ch = '';
  }
  for (int i = 0; i < input.length; i++) {
    var c = input[i];
    if (c == 'R' || c == 'G' || c == 'B') {
      commit(); ch = c.toLowerCase(); acc = 0;
    } else if (c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57 && acc >= 0) {
      acc = acc * 10 + (c.codeUnitAt(0) - 48);
    } else if (c == '!') {
      commit(); pixels++; r = 0; g = 0; b = 0;
    } else if (c == '~') {
      commit(); r = 255 - r; g = 255 - g; b = 255 - b; inversions++;
    }
  }
  commit();
  return {'r': r, 'g': g, 'b': b, 'pixels': pixels, 'inversions': inversions};
}

