import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {



  List<List<int>> dist = [
    [0, 1, 2, 3],
    [1, 0, 4, 6],
    [2, 4, 0, 5],
    [3, 6, 5, 0],
  ];

  int n = dist.length;
  List<int> cities = List.generate(n, (i) => i);

  int minCost = 1 << 30;
  List<int> bestPath = [];

  void permute(List<int> arr, int l, int r) {
    if (l == r) {

      int cost = 0;
      int prev = 0;
      for (int city in arr) {
        cost += dist[prev][city];
        prev = city;
      }
      cost += dist[prev][0]; 

      if (cost < minCost) {
        minCost = cost;
        bestPath = [0, ...arr, 0];
      }
    } else {
      for (int i = l; i <= r; i++) {
        arr = List.from(arr); 
        int tmp = arr[l];
        arr[l] = arr[i];
        arr[i] = tmp;
        permute(arr, l + 1, r);
      }
    }
  }

  List<int> permCities = List.generate(n - 1, (i) => i + 1);
  permute(permCities, 0, permCities.length - 1);

  print('Minimum cost: $minCost');
  print('Best path: ${bestPath.join(" -> ")}');
}

