import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String text, String pattern, int maxEdits) {
  if (pattern.isEmpty || text.length < pattern.length) {
    return {};
  }

  Map<String, int> targetFreq = {};
  for (int i = 0; i < pattern.length; i++) {
    String ch = pattern[i];
    targetFreq[ch] = (targetFreq[ch] ?? 0) + 1;
  }

  Map<String, int> windowFreq = {};
  int excess = 0;
  int m = pattern.length;

  for (int i = 0; i < m; i++) {
    String ch = text[i];
    windowFreq[ch] = (windowFreq[ch] ?? 0) + 1;
    if (windowFreq[ch]! > (targetFreq[ch] ?? 0)) {
      excess++;
    }
  }

  Set<int> result = {};
  if (excess <= maxEdits) {
    result.add(0);
  }

  for (int i = m; i < text.length; i++) {
    String outChar = text[i - m];
    if (windowFreq[outChar]! > (targetFreq[outChar] ?? 0)) {
      excess--;
    }
    windowFreq[outChar] = windowFreq[outChar]! - 1;
    if (windowFreq[outChar] == 0) {
      windowFreq.remove(outChar);
    }

    String inChar = text[i];
    windowFreq[inChar] = (windowFreq[inChar] ?? 0) + 1;
    if (windowFreq[inChar]! > (targetFreq[inChar] ?? 0)) {
      excess++;
    }

    if (excess <= maxEdits) {
      result.add(i - m + 1);
    }
  }

  return result;
}

