import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> requests) {
  if (requests.isEmpty || requests[0].isEmpty) return 0.0;
  int rows = requests.length;
  int cols = requests[0].length;

  List<double> maxLoad = List<double>.filled(cols, 0.0);

  for (int r = 0; r < rows; r++) {
    List<double> L = List<double>.filled(cols, 0.0);
    List<double> R = List<double>.filled(cols, 0.0);

    L[0] = requests[r][0].toDouble();
    for (int c = 1; c < cols; c++) {
      L[c] = requests[r][c].toDouble() + 0.5 * L[c - 1];
    }

    R[cols - 1] = requests[r][cols - 1].toDouble();
    for (int c = cols - 2; c >= 0; c--) {
      R[c] = requests[r][c].toDouble() + 0.5 * R[c + 1];
    }

    for (int c = 0; c < cols; c++) {
      maxLoad[c] += L[c] + R[c] - requests[r][c].toDouble();
    }
  }

  double maxVal = 0.0;
  for (int c = 0; c < cols; c++) {
    if (maxLoad[c] > maxVal) {
      maxVal = maxLoad[c];
    }
  }

  return maxVal;
}

