import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> dailyViewers, int minimumRevenue) {
  int n = dailyViewers.length;
  if (n == 0) return [];
  int minLen = n + 1;
  int bestStart = -1;
  int bestEnd = -1;
  int left = 0;
  int sum = 0;
  for (int right = 0; right < n; right++) {
    sum += dailyViewers[right];
    while (sum >= minimumRevenue && left <= right) {
      int currLen = right - left + 1;
      if (currLen < minLen) {
        minLen = currLen;
        bestStart = left;
        bestEnd = right;
      }
      sum -= dailyViewers[left];
      left++;
    }
  }
  if (bestStart == -1) return [];
  return [bestStart, bestEnd];
}

