import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int fastPow(int base, int exponent, [int? mod]) {
    if (exponent < 0) {
      throw ArgumentError('Negative exponents not supported for integer base');
    }

    int result = 1;
    int currentBase = base;
    int exp = exponent;

    while (exp > 0) {

      if (exp & 1 == 1) {
        if (mod != null) {
          result = (result * currentBase) % mod;
        } else {
          result = result * currentBase;
        }
      }

      if (mod != null) {
        currentBase = (currentBase * currentBase) % mod;
      } else {
        currentBase = currentBase * currentBase;
      }

      exp >>= 1;
    }

    return result;
  }

  print('Fast Exponentiation Examples:');
  print('=' * 40);

  print('2^10 = ${fastPow(2, 10)}');
  print('3^5 = ${fastPow(3, 5)}');
  print('5^3 = ${fastPow(5, 3)}');
  print('7^0 = ${fastPow(7, 0)}');
  print('10^6 = ${fastPow(10, 6)}');

  print('\nLarge exponents:');
  print('2^20 = ${fastPow(2, 20)}');
  print('2^30 = ${fastPow(2, 30)}');

  print('\nModular exponentiation:');
  print('2^10 mod 1000 = ${fastPow(2, 10, 1000)}');
  print('3^100 mod 7 = ${fastPow(3, 100, 7)}');
  print('5^117 mod 19 = ${fastPow(5, 117, 19)}');
  print('10^9 mod 6 = ${fastPow(10, 9, 6)}');

  print('\nLarge modular exponentiation:');
  print('2^1000000 mod 1000007 = ${fastPow(2, 1000000, 1000007)}');
  print('123^456789 mod 1000000007 = ${fastPow(123, 456789, 1000000007)}');

  print('\nEdge cases:');
  print('1^1000000 = ${fastPow(1, 1000000)}');
  print('0^5 = ${fastPow(0, 5)}');
  print('100^1 = ${fastPow(100, 1)}');

  print('\nAlgorithm verification:');
  int naivePow(int base, int exp) {
    int result = 1;
    for (int i = 0; i < exp; i++) {
      result *= base;
    }
    return result;
  }

