  expect(implementation([]), <String, int>{});
  expect(implementation([[28, 0, 10], [28, 2, 5]]), {'e4': 10});
  expect(implementation([[28, 1, 5], [28, 5, 10]]), {'e4': 9});
  expect(implementation([[0, 5, 5]]), <String, int>{});
