double fn0(List<List<int>> tallies, int startDay, int endDay) {




  if (endDay < startDay) return 0.0;
  final int windowDays = endDay - startDay + 1;
  int total = 0;
  for (final entry in tallies) {
    final int day = entry[0];
    final int votes = entry[1];
    if (votes < 0) continue;
    if (day >= startDay && day <= endDay) {
      int dow = day % 7;
      if (dow < 0) dow += 7;
      if (dow == 5 || dow == 6) {
        total += votes * 2;
      } else {
        total += votes;
      }
    }
  }
  return total / windowDays;
}

