import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String deckNotation) {
  if (deckNotation.trim().isEmpty) {
    return 0.0;
  }

  List<String> tokens = deckNotation.split(',');
  Map<String, int> ranks = {
    'A': 1,
    'J': 11,
    'Q': 12,
    'K': 13,
  };

  double score = 0.0;
  int? previousRank;
  String? previousSuit;

  for (String rawToken in tokens) {
    String token = rawToken.trim();

    if (token.length < 2) {
      score -= 0.5;
      continue;
    }

    String suit = token.substring(token.length - 1);
    String rankText = token.substring(0, token.length - 1);

    int? rank = ranks[rankText];
    rank ??= int.tryParse(rankText);

    bool validSuit = 'SHDC'.contains(suit);
    bool validRank = rank != null && rank >= 1 && rank <= 10 || rank == 11 || rank == 12 || rank == 13;

    if (!validSuit || !validRank) {
      score -= 0.5;
      continue;
    }

    score += 1.0;

    if (previousSuit == suit) {
      score += 0.5;
    }

    if (previousRank != null && (previousRank - rank!).abs() == 1) {
      score += 0.25;
    }

    bool currentFace = rank! >= 11;
    bool previousFace = previousRank != null && previousRank >= 11;

    if (currentFace && previousFace) {
      score += 0.25;
    }

    previousRank = rank;
    previousSuit = suit;
  }

  return score;
}

