import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> pixels) {
  Map<String, int> counts = {};
  for (String pixel in pixels) {
    List<String> parts = pixel.split(',');
    int r = int.parse(parts[0]);
    int g = int.parse(parts[1]);
    int b = int.parse(parts[2]);
    int maxVal = r > g ? (r > b ? r : b) : (g > b ? g : b);
    int minVal = r < g ? (r < b ? r : b) : (g < b ? g : b);
    String classification;
    if (maxVal - minVal < 30) {
      classification = 'N';
    } else if (r == maxVal) {
      classification = 'R';
    } else if (g == maxVal) {
      classification = 'G';
    } else {
      classification = 'B';
    }
    counts[classification] = (counts[classification] ?? 0) + 1;
  }
  List<MapEntry<String, int>> entries = counts.entries.where((e) => e.value >= 2).toList();
  entries.sort((a, b) {
    if (a.value != b.value) return b.value.compareTo(a.value);
    return a.key.compareTo(b.key);
  });
  return entries.map((e) => e.key).toList();
}

