import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  int n = args.isNotEmpty ? int.tryParse(args[0]) ?? 8 : 8;
  if (n <= 0) {
    print('Board size must be positive.');
    return;
  }

  final positions = List<int>.filled(n, -1);
  int solutions = 0;

  bool isSafe(int row, int col) {
    for (int r = 0; r < row; r++) {
      final c = positions[r];
      if (c == col ||                 
          (r - row).abs() == (c - col).abs()) { 
        return false;
      }
    }
    return true;
  }

  void place(int row) {
    if (row == n) {

      solutions++;
      print('Solution #$solutions');
      for (int r = 0; r < n; r++) {
        final line = List.generate(n, (c) => c == positions[r] ? 'Q' : '.').join(' ');
        print(line);
      }
      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        positions[row] = col;
        place(row + 1);

      }
    }
  }

  place(0);
  print('Total solutions for N=$n: $solutions');
}

