List<int> fn0(List<String> rows) {




  if (rows.isEmpty) return <int>[];
  var width = 0;
  for (final r in rows) {
    if (r.length > width) width = r.length;
  }
  if (width == 0) return <int>[];
  final heights = List<int>.filled(width, 0);
  for (var c = 0; c < width; c++) {
    var h = 0;
    for (var r = rows.length - 1; r >= 0; r--) {
      final row = rows[r];
      final ch = c < row.length ? row[c] : ' ';
      if (ch == ' ') break;
      h++;
    }
    heights[c] = h;
  }
  final peaks = <int>[];
  var current = 0;
  var inTower = false;
  for (final h in heights) {
    if (h > 0) {
      inTower = true;
      if (h > current) current = h;
    } else if (inTower) {
      peaks.add(current);
      current = 0;
      inTower = false;
    }
  }
  if (inTower) peaks.add(current);
  return peaks;
}

