import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> actualDepartures, int start, int interval, int k) {
  int left = 0;
  int right = actualDepartures.length - 1;
  int firstDelayed = actualDepartures.length;

  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (actualDepartures[mid] > start + mid * interval) {
      firstDelayed = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }

  List<int> result = [];
  int limit = firstDelayed + k;
  if (limit > actualDepartures.length) {
    limit = actualDepartures.length;
  }

  for (int i = firstDelayed; i < limit; i++) {
    result.add(actualDepartures[i]);
  }

  return result;
}

