int fn0(List<int> commands) {
  List<int> stack = [];
  for (int cmd in commands) {
    if (cmd >= 0) {
      stack.add(cmd);
    } else if (stack.isNotEmpty) {
      stack.removeLast();
    }
  }
  int total = 0;
  for (int val in stack) {
    total += val;
  }
  return total;
}

