import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> tokens) {


  final result = <String, int>{
    'valid': 0,
    'invalid': 0,
    'uniqueValid': 0,
    'totalUnits': 0,
    'maxUnits': 0,
    'dotHeavy': 0,
  };
  final seen = <String>{};
  for (final token in tokens) {
    final symbols = token.split('');
    final isValid =
        token.isNotEmpty && symbols.every((c) => c == '.' || c == '-');
    if (!isValid) {
      result['invalid'] = result['invalid']! + 1;
      continue;
    }
    final units = symbols.fold<int>(
            0, (acc, c) => acc + (c == '.' ? 1 : 3)) +
        (token.length - 1);
    final dots = symbols.where((c) => c == '.').length;
    final dashes = token.length - dots;
    result['valid'] = result['valid']! + 1;
    result['totalUnits'] = result['totalUnits']! + units;
    if (units > result['maxUnits']!) {
      result['maxUnits'] = units;
    }
    if (dots > dashes) {
      result['dotHeavy'] = result['dotHeavy']! + 1;
    }
    if (seen.add(token)) {
      result['uniqueValid'] = result['uniqueValid']! + 1;
    }
  }
  return result;
}

