@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String dna) {
  if (dna.length < 4) return -1;

  for (int len = 4; len <= dna.length; len += 4) {
    int countA = 0, countC = 0, countG = 0, countT = 0;
    for (int i = 0; i < len; i++) {
      switch (dna[i]) {
        case 'A': countA++; break;
        case 'C': countC++; break;
        case 'G': countG++; break;
        case 'T': countT++; break;
      }
    }
    if (countA == countC && countC == countG && countG == countT) {
      return len;
    }
    for (int start = 1; start <= dna.length - len; start++) {
      switch (dna[start - 1]) {
        case 'A': countA--; break;
        case 'C': countC--; break;
        case 'G': countG--; break;
        case 'T': countT--; break;
      }
      switch (dna[start + len - 1]) {
        case 'A': countA++; break;
        case 'C': countC++; break;
        case 'G': countG++; break;
        case 'T': countT++; break;
      }
      if (countA == countC && countC == countG && countG == countT) {
        return len;
      }
    }
  }
  return -1;
}

