import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String mazeRow) {
  List<int> scores = [];
  int dotCount = 0;
  int specialCount = 0;
  int trapCount = 0;
  bool inCorridor = false;

  for (int i = 0; i < mazeRow.length; i++) {
    String cell = mazeRow[i];
    if (cell == '#') {
      if (inCorridor) {
        int score = dotCount + 3 * specialCount - 2 * trapCount;
        if (score > 0) scores.add(score);
        inCorridor = false;
        dotCount = 0;
        specialCount = 0;
        trapCount = 0;
      }
    } else {
      if (!inCorridor) {
        inCorridor = true;
      }
      if (cell == '.') {
        dotCount++;
      } else if (cell == 'S' || cell == 'E') {
        specialCount++;
      } else if (cell == '*') {
        trapCount++;
      }
    }
  }

  if (inCorridor) {
    int score = dotCount + 3 * specialCount - 2 * trapCount;
    if (score > 0) scores.add(score);
  }

  return scores;
}

