@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> digits) {
  if (digits.isEmpty) return 0.0;

  List<int> oddIndices = [];
  List<int> evenIndices = [];

  for (int i = 0; i < digits.length; i++) {
    if (i % 2 == 0) {
      oddIndices.add(digits[i]);
    } else {
      evenIndices.add(digits[i]);
    }
  }

  int oddUniqueSum = oddIndices.toSet().fold(0, (sum, d) => sum + d);
  int evenUniqueSum = evenIndices.toSet().fold(0, (sum, d) => sum + d);

  return (oddUniqueSum * 3 - evenUniqueSum) / 4.0;
}

