import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> readings) {
  if (readings.isEmpty) return {};
  List<String> zones = [];
  List<int> levels = [];
  for (var r in readings) {
    var p = r.split(':');
    zones.add(p[0]);
    levels.add(int.parse(p[1]));
  }
  List<int> idx = List.generate(zones.length, (i) => i);
  idx.sort((a, b) => levels[a].compareTo(levels[b]));
  Map<String, int> result = {};
  int rank = 1;
  for (int i = 0; i < idx.length; i++) {
    if (i > 0 && levels[idx[i]] != levels[idx[i - 1]]) rank = i + 1;
    result[zones[idx[i]]] = rank;
  }
  return result;
}

